INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13734, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "使机器、系统或过程按照一定方式运行的系统。", "primary_collocate": null, "pronunciation": "kòng zhì xì tǒng", "ipa": "kʰʊŋ˥˩ ʈʂɨ˥˩ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "现代风力涡轮机已集成智能控制系统：激光雷达预判风速变化，实时调节桨距角以优化转矩；数字孪生技术则构建虚拟机组模型，实现故障预测性维护。", "target_word": "控制系统", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台机器的控制系统出了问题。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在修理工厂的控制系统。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯的控制系统让它在每层楼停下来。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新车有一套很先进的控制系统。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "控制系统一坏，机器就停了。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机上的控制系统由电脑管理。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天在办公室看着工厂的控制系统。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调的控制系统可以自动调温度。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给工厂换了新的控制系统。", "target_word": "控制系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套控制系统", "label": "量词"}, {"form": "控制系統", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让机器或过程按设定方式运行的系统", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '385e789d-21ea-49b5-b03e-4cf712cdbae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13734, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "控制系统", "is_correct": true, "explanation": "控制系统负责预判风速、实时调节桨距角、预测维护，与句中的功能一致。"}, {"text": "通信系统", "is_correct": false, "explanation": "语义：通信系统负责传递信息，不负责实时调节桨距角。"}, {"text": "冷却系统", "is_correct": false, "explanation": "语义：冷却系统负责降温散热，不负责预判风速变化。"}, {"text": "发电机", "is_correct": false, "explanation": "搭配：“集成”多用于系统或电路，不说“集成发电机”。"}], "explanations": {"控制系统": "控制系统负责预判风速、实时调节桨距角、预测维护，与句中的功能一致。", "通信系统": "语义：通信系统负责传递信息，不负责实时调节桨距角。", "冷却系统": "语义：冷却系统负责降温散热，不负责预判风速变化。", "发电机": "搭配：“集成”多用于系统或电路，不说“集成发电机”。"}, "sentence_index": 0, "correct_answer": "控制系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂里装了一只控制系统。", "explanation": "这里应该用〈套〉。控制系统是成套的装置，量词用“套”，不用“只”。"}, {"text": "工厂里有一条控制系统。", "explanation": "这里应该用〈套〉。“条”用于细长的东西，控制系统要用“套”。"}, {"text": "这把控制系统很先进。", "explanation": "这里应该用〈套〉。“把”用于有柄的器具，控制系统要用“套”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "控制系统", "is_correct": true, "explanation": "控制系统负责管理飞机上的运行，与“由电脑管理”一致。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是摆设，不需要电脑管理，“由电脑管理”的说法不成立。"}, {"text": "餐车", "is_correct": false, "explanation": "搭配：“由……管理”要求对象是系统或设备，不说“由电脑管理餐车”。"}, {"text": "垃圾桶", "is_correct": false, "explanation": "语义：垃圾桶没有运行功能，不需要电脑管理。"}], "explanations": {"控制系统": "控制系统负责管理飞机上的运行，与“由电脑管理”一致。", "花瓶": "语义：花瓶是摆设，不需要电脑管理，“由电脑管理”的说法不成立。", "餐车": "搭配：“由……管理”要求对象是系统或设备，不说“由电脑管理餐车”。", "垃圾桶": "语义：垃圾桶没有运行功能，不需要电脑管理。"}, "sentence_index": 6, "correct_answer": "控制系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜里他用控制系统照路。", "explanation": "这里应该用〈手电筒〉。控制系统是指挥机器或过程运行的系统，照路要用手电筒。"}, {"text": "他每天早上打开控制系统听新闻。", "explanation": "这里应该用〈收音机〉。控制系统用于调节机器或过程的运行，听新闻要用收音机。"}, {"text": "他每天用控制系统洗衣服。", "explanation": "这里应该用〈洗衣机〉。控制系统负责指挥运行，洗衣服要用洗衣机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂的机器装了一条新的控制系统。", "corrected_sentence": "工厂的机器装了一套新的控制系统。", "error_description": "量词用错：“条”用于细长的东西。控制系统是成套的装置，应说“一套新的控制系统”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆控制系统运行得很稳定。", "corrected_sentence": "这套控制系统运行得很稳定。", "error_description": "量词用错：“辆”用于车辆。控制系统是成套的装置，应说“这套控制系统”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
