INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13735, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "激光雷达是一种通过发射激光束并接收反射信号来探测目标距离、速度等信息的遥感技术，常用于自动驾驶、测绘等领域。", "primary_collocate": null, "pronunciation": "jī guāng léi dá", "ipa": "tɕi˥ kwɑŋ˥ lei˧˥ ta˧˥", "syllable_count": 4, "sentences": [{"text": "风力涡轮机用激光雷达预判风速变化。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆自动驾驶汽车装了激光雷达。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "激光雷达可以测出前面物体的距离。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在调试车顶的激光雷达。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "测绘人员用激光雷达绘制地形图。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "激光雷达发出激光，再接收反射回来的信号。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台激光雷达的价格比摄像头贵很多。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机上也装着激光雷达来探测地面。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨雾天气会影响激光雷达的探测效果。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "激光雷达能帮机器人识别周围的障碍。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "车载激光雷达", "label": "复合"}], "register": "中性", "sense_fingerprint": "发射激光并接收反射信号、探测距离和速度的遥感技术或设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ae084-1987-4b16-afb3-69290c5fa6f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13735, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "激光雷达", "is_correct": true, "explanation": "正确：激光雷达能感知周围环境，可以预判风速变化，符合句意。"}, {"text": "温度计", "is_correct": false, "explanation": "语义：温度计用来测温度，不能预判风速的变化。"}, {"text": "电池", "is_correct": false, "explanation": "语义：电池只提供电能，不能感知或预判风速。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“预判……变化”需要能感知环境的设备，不能与“冰箱”搭配。"}], "explanations": {"激光雷达": "正确：激光雷达能感知周围环境，可以预判风速变化，符合句意。", "温度计": "语义：温度计用来测温度，不能预判风速的变化。", "电池": "语义：电池只提供电能，不能感知或预判风速。", "冰箱": "搭配：“预判……变化”需要能感知环境的设备，不能与“冰箱”搭配。"}, "sentence_index": 0, "correct_answer": "激光雷达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门口的激光雷达拍下了小偷的脸。", "explanation": "这里应该用〈摄像头〉。摄像头用来拍摄图像，激光雷达靠激光测距离，不能“拍下”人脸。"}, {"text": "激光雷达能告诉我们哪边是北。", "explanation": "这里应该用〈指南针〉。指南针用来指示方向，激光雷达测量的是距离和速度，不指示方向。"}, {"text": "工程师正在调试车顶的一辆激光雷达。", "explanation": "这里应该用量词〈台〉。“辆”用于车辆，激光雷达是机器，应说“一台激光雷达”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13735, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激光雷达", "is_correct": true, "explanation": "正确：激光雷达是价格较高的设备，可以与摄像头比较价格，符合句意。"}, {"text": "计算器", "is_correct": false, "explanation": "语义：计算器一般比摄像头便宜，与“比摄像头贵很多”相矛盾。"}, {"text": "收音机", "is_correct": false, "explanation": "语义：收音机通常比摄像头便宜，与“贵很多”相矛盾。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟一般很便宜，与“比摄像头贵很多”相矛盾。"}], "explanations": {"激光雷达": "正确：激光雷达是价格较高的设备，可以与摄像头比较价格，符合句意。", "计算器": "语义：计算器一般比摄像头便宜，与“比摄像头贵很多”相矛盾。", "收音机": "语义：收音机通常比摄像头便宜，与“贵很多”相矛盾。", "闹钟": "语义：闹钟一般很便宜，与“比摄像头贵很多”相矛盾。"}, "sentence_index": 6, "correct_answer": "激光雷达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "激光雷达能称出人的体重。", "explanation": "这里应该用〈体重秤〉。体重秤用来称重，激光雷达用来测距离，不能称出体重。"}, {"text": "激光雷达能收到电台的广播。", "explanation": "这里应该用〈收音机〉。收音机用来接收广播，激光雷达发射激光、接收反射信号，不接收广播。"}, {"text": "激光雷达能给室内的衣服烘干。", "explanation": "这里应该用〈烘干机〉。烘干机靠加热吹干衣物，激光雷达是测距与感知设备，不能烘干衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13735, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司买了一只激光雷达，装在无人车上。", "corrected_sentence": "我们公司买了一台激光雷达，装在无人车上。", "error_description": "量词错误：激光雷达是机器，应该用量词“台”。“只”通常用于动物等，不能用于激光雷达，正确说法是“一台激光雷达”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13735, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "机器人用激光雷达测了出前方的墙。", "corrected_sentence": "机器人用激光雷达测出了前方的墙。", "error_description": "补语位置错误：“测出”是动补式复合动词，了应放在补语之后，应说“测出了”，不能说“测了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc88f9a4-542a-47e5-806f-f580b6c12250') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
