INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13738, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "天文学中，从地球观测，行星与太阳之间的角距离。", "primary_collocate": null, "pronunciation": "jù jiǎo", "ipa": "tɕy˥˩ tɕjaʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "水星离太阳的距角最大是二十八度。", "target_word": "距角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "金星的距角最大时，最容易看到它。", "target_word": "距角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天文学家用距角说明行星的位置。", "target_word": "距角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "距角越大，行星在天空中离太阳越远。", "target_word": "距角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当距角很小时，水星藏在阳光里。", "target_word": "距角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上说，金星的距角不会超过四十八度。", "target_word": "距角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用望远镜测量了木星的距角。", "target_word": "距角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "内行星的距角有一个最大值。", "target_word": "距角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在黑板上画出了地球、太阳和金星的距角。", "target_word": "距角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚金星的距角达到最大，适合观测。", "target_word": "距角", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "最大距角", "label": "复合"}], "register": "书面", "sense_fingerprint": "距角|名词|天文学行星与太阳的角距离", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef9cf912-3233-4a4e-8b9e-0ce8bdd8a849') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "语义：时间是时长，不是角度，“水星离太阳的时间最大是二十八度”说不通。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：速度用公里每秒等单位计量，不能用“度”表示最大值，句子搭配不通。"}, {"text": "距角", "is_correct": true, "explanation": "正确。距角指行星与太阳的角距离，此处指水星与太阳之间角距离的最大值。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积是空间大小，天体之间没有用角度表示的“体积”，句子不通。"}], "explanations": {"时间": "语义：时间是时长，不是角度，“水星离太阳的时间最大是二十八度”说不通。", "速度": "搭配：速度用公里每秒等单位计量，不能用“度”表示最大值，句子搭配不通。", "距角": "正确。距角指行星与太阳的角距离，此处指水星与太阳之间角距离的最大值。", "体积": "语义：体积是空间大小，天体之间没有用角度表示的“体积”，句子不通。"}, "sentence_index": 0, "correct_answer": "距角"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水星离太阳的距角是五千八百万千米。", "explanation": "这里应该用〈距离〉。距角是用角度表示的数，说多少千米要用距离。"}, {"text": "这颗彗星的距角每秒达到四十公里。", "explanation": "这里应该用〈速度〉。距角是角度，不以公里每秒计量，这种单位属于速度。"}, {"text": "这个三角形的距角是六十度。", "explanation": "这里应该用〈角度〉。距角专指天文学中行星与太阳的角距离，三角形的角不能叫距角。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "搭配：“测量”用于长度、温度等可量化的属性，不能用于价格。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是口感，木星不能用望远镜测量味道，句子不通。"}, {"text": "名声", "is_correct": false, "explanation": "语义：名声是社会评价，无法用望远镜测量，句子不通。"}, {"text": "距角", "is_correct": true, "explanation": "正确。距角指行星与太阳的角距离，此处用望远镜测量木星与太阳之间的角距离。"}], "explanations": {"价格": "搭配：“测量”用于长度、温度等可量化的属性，不能用于价格。", "味道": "语义：味道是口感，木星不能用望远镜测量味道，句子不通。", "名声": "语义：名声是社会评价，无法用望远镜测量，句子不通。", "距角": "正确。距角指行星与太阳的角距离，此处用望远镜测量木星与太阳之间的角距离。"}, "sentence_index": 6, "correct_answer": "距角"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的距角达到了两千米。", "explanation": "这里应该用〈高度〉。距角是天文学中行星与太阳的角距离，山的高低要说高度。"}, {"text": "这幅照片的距角很独特。", "explanation": "这里应该用〈视角〉。距角专指天文学中的角距离，拍摄或观看的角度要说视角。"}, {"text": "这座雷达测得目标的距角是北偏东三十度。", "explanation": "这里应该用〈方位角〉。方位角是目标在水平面上的方向，雷达测定方向要说方位角；距角专指天文学中行星与太阳的角距离，不能用于雷达观测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只距角大约是二十度。", "corrected_sentence": "这个距角大约是二十度。", "error_description": "量词错误：“距角”是抽象概念，应用“个”计量；“只”用于动物，不能修饰距角，正确说法是“这个距角”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今晚金星的距角增大地很快。", "corrected_sentence": "今晚金星的距角增大得很快。", "error_description": "补语标记错误：动词后的程度补语应用“得”，不能用“地”；“增大地很快”不成立，应说“增大得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04f73984-7a74-4d64-b89f-f11b7f861d2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
