INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13740, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指飞机上全体工作人员，包括驾驶员、乘务员等。", "primary_collocate": null, "pronunciation": "jī zǔ", "ipa": "tɕi˥ tsu˨˩˦", "syllable_count": 2, "sentences": [{"text": "起飞前，机组已经检查完了所有设备。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机组人员提前两小时到机场。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机组有两名飞行员和五名乘务员。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机组向乘客问好，飞机很快起飞了。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机组成员每天都要检查飞机。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到大风，机组让大家系好安全带。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架飞机的机组都很有经验。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下飞机时，乘客感谢机组的服务。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机组在飞机上给乘客送水。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是同一个机组的，常常一起飞。", "target_word": "机组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "机组人员", "label": "复合"}, {"form": "机组成员", "label": "复合"}], "register": "中性", "sense_fingerprint": "机组：飞机上的全体工作人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d86f571-e8f9-490c-a880-a6de728f335c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13740, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机组", "is_correct": true, "explanation": "机组：指飞机上的全体工作人员，句中是负责检查设备的人员，符合句意。"}, {"text": "机身", "is_correct": false, "explanation": "语义：机身是飞机的主体结构，不能检查设备，句意不通。"}, {"text": "机票", "is_correct": false, "explanation": "语义：机票是乘机凭证，不能检查设备，句意不通。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位是供乘客就坐的位置，不能检查设备，句意不通。"}], "explanations": {"机组": "机组：指飞机上的全体工作人员，句中是负责检查设备的人员，符合句意。", "机身": "语义：机身是飞机的主体结构，不能检查设备，句意不通。", "机票": "语义：机票是乘机凭证，不能检查设备，句意不通。", "座位": "语义：座位是供乘客就坐的位置，不能检查设备，句意不通。"}, "sentence_index": 0, "correct_answer": "机组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个机组一共有两百个座位。", "explanation": "这里应该用〈航班〉。航班可以说有多少座位；机组是飞行人员，不能说有座位。"}, {"text": "这个机组有三条跑道。", "explanation": "这里应该用〈机场〉。跑道属于机场，机组是人，不能说有跑道。"}, {"text": "这个机组有四台发动机。", "explanation": "这里应该用〈飞机〉。发动机是飞机的部件，要说某架飞机有几台发动机；机组是飞机上的工作人员，不能说有发动机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13740, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机组", "is_correct": true, "explanation": "“机组”指飞机上的全体工作人员，可以说有经验，句意通顺。"}, {"text": "机场", "is_correct": false, "explanation": "搭配：“有经验”用于人，机场是场所，不能说有经验。"}, {"text": "跑道", "is_correct": false, "explanation": "语义：跑道是供飞机起降的道路，不能说有经验。"}, {"text": "发动机", "is_correct": false, "explanation": "语义：发动机是飞机的动力部件，不能说有经验。"}], "explanations": {"机组": "“机组”指飞机上的全体工作人员，可以说有经验，句意通顺。", "机场": "搭配：“有经验”用于人，机场是场所，不能说有经验。", "跑道": "语义：跑道是供飞机起降的道路，不能说有经验。", "发动机": "语义：发动机是飞机的动力部件，不能说有经验。"}, "sentence_index": 6, "correct_answer": "机组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "机组一个人就能决定是否延误航班。", "explanation": "这里应该用〈机长〉。机组是整个工作团队，不能与“一个人”搭配，决定延误的是机长。"}, {"text": "机组负责给飞机加油。", "explanation": "这里应该用〈地勤〉。加油是地勤人员的工作，机组是飞行和客舱人员，不负责加油。"}, {"text": "机组一共买了两百张票。", "explanation": "这里应该用〈乘客〉。买票的是乘客，机组是飞机上的全体工作人员，不会买票。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个机组们的每个人都很有经验。", "corrected_sentence": "这个机组的每个人都很有经验。", "error_description": "错误：“机组”本身表示一个群体，后面不能再加“们”。应为“这个机组的每个人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一只机组成员负责检查机舱。", "corrected_sentence": "一位机组成员负责检查机舱。", "error_description": "错误：“机组成员”指人，量词应用“位”，不能用“只”。应为“一位机组成员”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13741, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13741, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13741, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指机器、设备等不能正常工作或出现毛病。", "primary_collocate": null, "pronunciation": "gù zhàng", "ipa": "ku⁵¹ ʈʂɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "现代风力涡轮机已集成智能控制系统：激光雷达预判风速变化，实时调节桨距角以优化转矩；数字孪生技术则构建虚拟机组模型，实现故障预测性维护。", "target_word": "故障", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "电梯出了故障，我们只好走楼梯。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在检查机器的故障。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台洗衣机老是出故障，该换新的了。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机发现车有故障，马上停了下来。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅很快就排除了空调的故障。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为信号灯故障，路口堵车了。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机出现故障后，我把它送去修了。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故障很小，换个零件就好了。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的发动机发生过故障，所以推迟起飞。", "target_word": "故障", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "故障率", "label": "复合"}], "register": "中性", "sense_fingerprint": "机器设备出毛病、不能正常工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a6d8aef-a14f-4db1-9f94-df23b2e8ce72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13741, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "故障", "is_correct": true, "explanation": "正确答案：故障 gù zhàng，指机器、设备等不能正常工作或出现毛病。"}, {"text": "鼓掌", "is_correct": false, "explanation": "鼓掌 gǔ zhǎng 的两个音节声调都与 gù zhàng 不同（均为第三声），意思是拍手。"}, {"text": "鼓胀", "is_correct": false, "explanation": "鼓胀 gǔ zhàng 第一音节声调不同（第三声），意思是鼓起、膨胀。"}, {"text": "姑丈", "is_correct": false, "explanation": "姑丈 gū zhàng 第一音节声调不同（第一声），意思是姑父。"}, {"text": "腹胀", "is_correct": false, "explanation": "腹胀 fù zhàng 声母不同（f 与 g），意思是肚子胀。"}], "explanations": {"故障": "正确答案：故障 gù zhàng，指机器、设备等不能正常工作或出现毛病。", "鼓掌": "鼓掌 gǔ zhǎng 的两个音节声调都与 gù zhàng 不同（均为第三声），意思是拍手。", "鼓胀": "鼓胀 gǔ zhàng 第一音节声调不同（第三声），意思是鼓起、膨胀。", "姑丈": "姑丈 gū zhàng 第一音节声调不同（第一声），意思是姑父。", "腹胀": "腹胀 fù zhàng 声母不同（f 与 g），意思是肚子胀。"}, "sentence_index": null, "correct_answer": "故障"}, "level_3": {"options": [{"text": "故障", "is_correct": true, "explanation": "正确：故障指机器、设备不能正常工作，可以作“预测性维护”的对象。"}, {"text": "色彩", "is_correct": false, "explanation": "语义：“色彩”与设备维护无关，“实现色彩预测性维护”说不通。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”不能作“预测性维护”的对象，“实现速度预测性维护”说不通。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”不能作“预测性维护”的对象，“实现温度预测性维护”搭配不当。"}], "explanations": {"故障": "正确：故障指机器、设备不能正常工作，可以作“预测性维护”的对象。", "色彩": "语义：“色彩”与设备维护无关，“实现色彩预测性维护”说不通。", "速度": "搭配：“速度”不能作“预测性维护”的对象，“实现速度预测性维护”说不通。", "温度": "搭配：“温度”不能作“预测性维护”的对象，“实现温度预测性维护”搭配不当。"}, "sentence_index": 0, "correct_answer": "故障"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在考试中出现了故障，丢了不少分。", "explanation": "这里应该用〈失误〉。故障指机器、设备不能正常工作，人在考试中的疏忽要说失误。"}, {"text": "他有坏故障，总爱迟到。", "explanation": "这里应该用〈毛病〉。故障指机器、设备不能正常工作，人的不良习惯要说坏毛病。"}, {"text": "爸爸前几天出了故障，在家休息了两天。", "explanation": "这里应该用〈生病〉。故障指机器、设备出毛病，不能用来指人身体不舒服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13741, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "故障", "is_correct": true, "explanation": "正确：故障指信号灯出了毛病、不能正常工作，才会导致路口堵车。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与信号灯出问题导致堵车没有因果关系，句子说不通。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“数量”需要“多、少”等修饰才能作原因，单说“信号灯数量”不成立。"}, {"text": "外观", "is_correct": false, "explanation": "语义：外观与路口堵车无关，不能作原因。"}], "explanations": {"故障": "正确：故障指信号灯出了毛病、不能正常工作，才会导致路口堵车。", "价格": "语义：价格与信号灯出问题导致堵车没有因果关系，句子说不通。", "数量": "搭配：“数量”需要“多、少”等修饰才能作原因，单说“信号灯数量”不成立。", "外观": "语义：外观与路口堵车无关，不能作原因。"}, "sentence_index": 6, "correct_answer": "故障"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在计算时犯了故障，结果全算错了。", "explanation": "这里应该用〈错误〉。故障指设备出毛病，人在计算中的过失要说犯错误。"}, {"text": "这次投标故障了，公司没有中标。", "explanation": "这里应该用〈失败〉。故障指机器、设备工作失常，投标没有成功要说失败。"}, {"text": "我们在山里故障了，天黑前没能下山。", "explanation": "这里应该用〈迷路〉。故障只用于机器、设备，人走错方向要说迷路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13741, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台复印机昨天出了一台故障，修好了。", "corrected_sentence": "这台复印机昨天出了一次故障，修好了。", "error_description": "量词错误：“故障”是一次性的事件，应该用量词“次”，说“一次故障”；“台”用于机器等具体物件，不能用来计数故障。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13741, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套音响在演出时做了故障，声音突然没了。", "corrected_sentence": "这套音响在演出时出了故障，声音突然没了。", "error_description": "搭配错误：“故障”要用动词“出”（出了故障），“做”不能与“故障”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
