INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13742, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指事物能够被提前知道或推测出来的特性", "primary_collocate": null, "pronunciation": "yù cè xìng", "ipa": "y⁵¹ tsʰɤ⁵¹ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "现代风力涡轮机已集成智能控制系统：激光雷达预判风速变化，实时调节桨距角以优化转矩；数字孪生技术则构建虚拟机组模型，实现故障预测性维护。", "target_word": "预测性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个模型的预测性很强，结果几乎都对。", "target_word": "预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种天气没有预测性，很难提前知道。", "target_word": "预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的计划要有预测性，不能只看眼前。", "target_word": "预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说这份报告缺少预测性。", "target_word": "预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的判断很有预测性，公司因此少亏了钱。", "target_word": "预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股市的预测性不高，不要随便相信别人。", "target_word": "预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套软件的预测性怎么样？", "target_word": "预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震的预测性还比较差，人们要提前准备。", "target_word": "预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李写的文章有预测性，几年后真的发生了。", "target_word": "预测性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预测性维护", "label": "复合"}], "register": "书面", "sense_fingerprint": "事物可被提前推测的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a6d8aef-a14f-4db1-9f94-df23b2e8ce72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预测性", "is_correct": true, "explanation": "正确：“预测性维护”指提前判断设备故障再进行维护，“预测性”与之搭配。"}, {"text": "美观性", "is_correct": false, "explanation": "语义：维护的目的是防止设备出故障，与“美观”无关，句子说不通。"}, {"text": "舒适性", "is_correct": false, "explanation": "搭配：“舒适性”多修饰居住、乘坐等体验，不能用于设备故障的维护。"}, {"text": "趣味性", "is_correct": false, "explanation": "语义：故障与“趣味”无关，“趣味性维护”不成立。"}], "explanations": {"预测性": "正确：“预测性维护”指提前判断设备故障再进行维护，“预测性”与之搭配。", "美观性": "语义：维护的目的是防止设备出故障，与“美观”无关，句子说不通。", "舒适性": "搭配：“舒适性”多修饰居住、乘坐等体验，不能用于设备故障的维护。", "趣味性": "语义：故障与“趣味”无关，“趣味性维护”不成立。"}, "sentence_index": 0, "correct_answer": "预测性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药的预测性很苦，孩子吃了直皱眉。", "explanation": "这里应该用〈苦味〉。预测性指事物能被提前推测，药的味道要说苦味。"}, {"text": "这张照片的预测性很高，连字都看得清。", "explanation": "这里应该用〈清晰度〉。预测性指事物能被提前推测，照片的清楚程度要说清晰度。"}, {"text": "这辆车的预测性很高，撞车时能保护司机。", "explanation": "这里应该用〈安全性〉。预测性指事物能被提前推测，车辆撞车时的保护作用要说安全性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预测性", "is_correct": true, "explanation": "正确：“预测性”指事物能被提前推测，股市难以预测，所以“预测性不高”，不要随便相信别人。"}, {"text": "美观性", "is_correct": false, "explanation": "语义：股市的走势与美观无关，“美观性不高”说不通。"}, {"text": "海拔", "is_correct": false, "explanation": "搭配：“海拔”只用于地形、地点，不能修饰股市。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的形体，不能用来形容股市。"}], "explanations": {"预测性": "正确：“预测性”指事物能被提前推测，股市难以预测，所以“预测性不高”，不要随便相信别人。", "美观性": "语义：股市的走势与美观无关，“美观性不高”说不通。", "海拔": "搭配：“海拔”只用于地形、地点，不能修饰股市。", "身高": "体貌：“身高”指人的形体，不能用来形容股市。"}, "sentence_index": 6, "correct_answer": "预测性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的财务预测性很高，投资人都能看清账目。", "explanation": "这里应该用〈透明度〉。预测性指事物能被提前推测，账目清楚、能被看清要说透明度。"}, {"text": "这款手表的预测性很好，游泳时也不怕。", "explanation": "这里应该用〈防水性〉。预测性指事物能被提前推测，手表游泳时不怕水要说防水性。"}, {"text": "这双鞋的预测性很好，穿了两年还很结实。", "explanation": "这里应该用〈耐用性〉。预测性不指耐用，鞋子经久耐穿要说耐用性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套系统很预测性，能提前发现故障。", "corrected_sentence": "这套系统很有预测性，能提前发现故障。", "error_description": "句法错误：抽象名词“预测性”前要用“有”，应说“很有预测性”；“很”不能直接修饰名词，丢了“有”就不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这款游戏的预测性低很，每一局都让人意外。", "corrected_sentence": "这款游戏的预测性很低，每一局都让人意外。", "error_description": "程度词位置错误：“很”修饰形容词，应放在“低”之前，说“预测性很低”，不能说“低很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13743, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13743, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13743, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指一台独立的计算机或不依赖网络的游戏模式。", "primary_collocate": null, "pronunciation": "dān jī", "ipa": "tan⁵⁵ tɕi⁵⁵", "syllable_count": 2, "sentences": [{"text": "为了保证数据安全，研究所把涉密计算任务迁移到一台与外网隔离的单机上完成。", "target_word": "单机", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这款游戏是单机，不用连网。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在火车上玩单机，没有信号也不怕。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑是单机，不能上网。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想玩联机还是单机？", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "单机比较安全，因为不连网络。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件有单机和联网两种模式。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机上没有网络，我只好选单机。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "单机的速度很快，但是不能和朋友一起玩。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟喜欢单机，因为不会被别人打扰。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "單機", "label": "繁体"}, {"form": "单机游戏", "label": "复合"}], "register": "中性", "sense_fingerprint": "独立不联网的电脑或游戏模式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a6d8aef-a14f-4db1-9f94-df23b2e8ce72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13743, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "单机", "is_correct": true, "explanation": "正确：单机指一台独立的计算机，或不依赖网络的游戏模式。"}, {"text": "当机", "is_correct": false, "explanation": "dāng（第一声）与 dān（第一声）韵尾不同（-ng 与 -n），意思是电脑突然停止响应。"}, {"text": "蛋鸡", "is_correct": false, "explanation": "dàn（第四声）与 dān（第一声）声调不同，意思是下蛋的母鸡。"}, {"text": "单极", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是只有一个极。"}, {"text": "班机", "is_correct": false, "explanation": "bān 与 dān 声母不同（b 与 d），意思是定期航班。"}], "explanations": {"单机": "正确：单机指一台独立的计算机，或不依赖网络的游戏模式。", "当机": "dāng（第一声）与 dān（第一声）韵尾不同（-ng 与 -n），意思是电脑突然停止响应。", "蛋鸡": "dàn（第四声）与 dān（第一声）声调不同，意思是下蛋的母鸡。", "单极": "jí（第二声）与 jī（第一声）声调不同，意思是只有一个极。", "班机": "bān 与 dān 声母不同（b 与 d），意思是定期航班。"}, "sentence_index": null, "correct_answer": "单机"}, "level_3": {"options": [{"text": "单机", "is_correct": true, "explanation": "正确：单机指一台独立的计算机，此处指与外网隔离、不联网的单机。"}, {"text": "草坪", "is_correct": false, "explanation": "语义：草坪不是计算设备，不能用来完成计算任务。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯不是计算设备，“迁移到水杯上完成计算任务”说不通。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不是计算设备，不能承载计算任务。"}], "explanations": {"单机": "正确：单机指一台独立的计算机，此处指与外网隔离、不联网的单机。", "草坪": "语义：草坪不是计算设备，不能用来完成计算任务。", "水杯": "语义：水杯不是计算设备，“迁移到水杯上完成计算任务”说不通。", "教室": "语义：教室不是计算设备，不能承载计算任务。"}, "sentence_index": 0, "correct_answer": "单机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一本单机，专门写小说。", "explanation": "量词：“本”用于书，电脑应用“台”，这里不能说“一本单机”。"}, {"text": "他是一个单机，很爱跟朋友聊天。", "explanation": "语义：这里把“单机”用成了形容人的〈独来独往〉义，但单机只指计算机或游戏模式，不能形容人。"}, {"text": "这台单机插着网线，随时都能上网。", "explanation": "语义：这里的“单机”被当成了〈联机〉（与网络相连）用。单机指不依赖网络，插网线随时上网正是联机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13743, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "单机", "is_correct": true, "explanation": "正确：单机指不依赖网络的运行模式，与“联网”相对。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是设备，不是软件的运行模式，不能与“联网”并列。"}, {"text": "文件", "is_correct": false, "explanation": "搭配：“模式”的并列项须是运行方式，“文件”不能与“联网”并列。"}, {"text": "键盘", "is_correct": false, "explanation": "语义：键盘是输入设备，不是软件的运行模式。"}], "explanations": {"单机": "正确：单机指不依赖网络的运行模式，与“联网”相对。", "手机": "语义：手机是设备，不是软件的运行模式，不能与“联网”并列。", "文件": "搭配：“模式”的并列项须是运行方式，“文件”不能与“联网”并列。", "键盘": "语义：键盘是输入设备，不是软件的运行模式。"}, "sentence_index": 6, "correct_answer": "单机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台单机的味道很香，我忍不住想尝一口。", "explanation": "语义：这里把“单机”当成了〈食物〉来形容。单机指计算机或游戏模式，没有味道可尝。"}, {"text": "他把单机放进口袋，随时打电话。", "explanation": "语义：这里把“单机”当成了〈手机〉用。单机指计算机或游戏模式，不能用来打电话。"}, {"text": "他很喜欢养单机，每天都给它喂水。", "explanation": "语义：这里把“单机”当成了〈宠物〉来养。单机指计算机或游戏模式，不是活物，不能养、喂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13743, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一只单机，平时只用来打字。", "corrected_sentence": "我买了一台单机，平时只用来打字。", "error_description": "量词错误：单机作为计算机应用量词“台”，“只”用于动物，应改为“台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13743, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台老电脑的单机，只用来放照片。", "corrected_sentence": "这台老电脑是单机，只用来放照片。", "error_description": "句法错误：“这台老电脑的单机”作主语后缺少谓语，应说“这台老电脑是单机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
