INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13747, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使机器、系统等具备像人一样的判断、学习或自动化能力。", "primary_collocate": null, "pronunciation": "zhì néng huà", "ipa": "ʈʂɻ̩˥˩ nɤŋ˧˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "清洁能源的深层变革不仅在于发电端，更体现在能源系统的智能化重构。", "target_word": "智能化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工厂正在智能化，机器会自己做事。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想把仓库智能化，减少人工。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行已经智能化了，不用排队。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市交通智能化以后，堵车少了。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的智能化改造用了两年。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业智能化可以帮农民省很多力。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大楼智能化后，灯会自动开关。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室智能化了，老师用屏幕上课。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的电器全部智能化以后，我们多出了不少时间。", "target_word": "智能化", "complexity_tier": "T3", "furigana": "jiā lǐ de diàn qì quán bù zhì néng huà yǐ hòu wǒ men duō chū le bù shǎo shí jiān", "sentence_source": "generated"}], "morphological_forms": [{"form": "智能化了", "label": "体标"}, {"form": "智能化改造", "label": "复合"}], "register": "书面", "sense_fingerprint": "智能化：使机器或系统具备判断、学习、自动化的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a6d8aef-a14f-4db1-9f94-df23b2e8ce72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13747, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "智能化", "is_correct": true, "explanation": "正确。“能源系统的智能化重构”指让系统具备判断、学习能力，与深层变革的语境相符。"}, {"text": "污染", "is_correct": false, "explanation": "语义：“污染”与“清洁能源”的变革方向相反，不能用来描述重构。"}, {"text": "衰退", "is_correct": false, "explanation": "搭配：“衰退”多用于经济、人口等，不与“能源系统的……重构”搭配。"}, {"text": "老化", "is_correct": false, "explanation": "语义：“老化”指变旧、性能下降，与“深层变革”的语境相反。"}], "explanations": {"智能化": "正确。“能源系统的智能化重构”指让系统具备判断、学习能力，与深层变革的语境相符。", "污染": "语义：“污染”与“清洁能源”的变革方向相反，不能用来描述重构。", "衰退": "搭配：“衰退”多用于经济、人口等，不与“能源系统的……重构”搭配。", "老化": "语义：“老化”指变旧、性能下降，与“深层变革”的语境相反。"}, "sentence_index": 0, "correct_answer": "智能化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子很智能化，一学就会。", "explanation": "这里应该用〈聪明〉。智能化指让机器、系统具备判断和学习能力，形容人聪明要说“聪明”。"}, {"text": "这本小说写得很智能化，读者都喜欢。", "explanation": "这里应该用〈精彩〉。形容小说写得好要说精彩；智能化只用于让机器、系统具备判断和学习能力的对象。"}, {"text": "这支足球队已经智能化了，每场都能取胜。", "explanation": "这里应该用〈强大〉。形容球队实力变强要说强大；智能化不能用于球队这类团体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13747, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "智能化", "is_correct": true, "explanation": "正确。“农业智能化”指让农业具备自动判断能力，与“帮农民省很多力”相符。"}, {"text": "退化", "is_correct": false, "explanation": "语义：“退化”指变差，与“帮农民省很多力”的效果相反。"}, {"text": "荒废", "is_correct": false, "explanation": "搭配：“荒废”多用于土地、时间，不与“农业”及“帮农民省力”的语境搭配。"}, {"text": "萎缩", "is_correct": false, "explanation": "语义：“萎缩”指缩小、衰落，与“省很多力”的正面效果不符。"}], "explanations": {"智能化": "正确。“农业智能化”指让农业具备自动判断能力，与“帮农民省很多力”相符。", "退化": "语义：“退化”指变差，与“帮农民省很多力”的效果相反。", "荒废": "搭配：“荒废”多用于土地、时间，不与“农业”及“帮农民省力”的语境搭配。", "萎缩": "语义：“萎缩”指缩小、衰落，与“省很多力”的正面效果不符。"}, "sentence_index": 6, "correct_answer": "智能化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只苹果已经智能化了，吃起来很甜。", "explanation": "这里应该用〈成熟〉。苹果变熟要说成熟；智能化指让机器、系统具备判断和学习能力，不能用于水果。"}, {"text": "这位老师的讲课很智能化，学生都爱听。", "explanation": "这里应该用〈生动〉。形容讲课有生气要说生动；智能化只用于让机器、系统具备判断和学习能力的对象。"}, {"text": "这家工厂的产量智能化了一倍。", "explanation": "这里应该用〈提高〉。产量是数量，要说提高或增加；智能化不能用来说数量的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13747, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂打算把生产线智能化了，明年开始施工。", "corrected_sentence": "这家工厂打算把生产线智能化，明年开始施工。", "error_description": "时态错误：“明年”指将来，打算做的事还没发生，不能用“了”；应说“打算把生产线智能化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13747, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座老楼去年全部智能化着，住户都很满意。", "corrected_sentence": "这座老楼去年全部智能化了，住户都很满意。", "error_description": "体标错误：“着”表示持续的状态，而“去年”指已完成的变化，应用“了”，说“去年全部智能化了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7330877-37c4-474f-9cfc-225b8556bf9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
