INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13749, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "产消者指既是生产者又是消费者的人或组织，例如在共享经济中，用户既创造内容也消费内容。", "primary_collocate": null, "pronunciation": "chǎn xiāo zhě", "ipa": "ʈʂʰan˨˩˦ ɕjau˥ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "当分布式光伏与储能系统构成“产消者”网络，传统自上而下的电网架构正被去中心化模式解构。", "target_word": "产消者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他家屋顶有太阳能板，是一位产消者。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产消者既用电，也把多余的电卖给别人。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在网上写文章又看文章的人，也是产消者。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产消者既是生产者，也是消费者。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "越来越多的家庭成了产消者。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区里的产消者可以互相分享电力。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为产消者，她拍视频也看别人的视频。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位产消者用自家的光伏板发电。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产消者的电既自己用，也能分给邻居。", "target_word": "产消者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "名词：既生产又消费的人或组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff80419-2652-460d-9a29-0cfc782ab013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13749, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产消者", "is_correct": true, "explanation": "正确。“产消者”指既生产又消费的人或组织，与“构成网络”相符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是能源设备，不能与光伏和储能系统构成网络。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，与光伏和储能系统的技术语境无关。"}, {"text": "诗篇", "is_correct": false, "explanation": "语域：诗篇是文学用语，与这里的技术性表述不符。"}], "explanations": {"产消者": "正确。“产消者”指既生产又消费的人或组织，与“构成网络”相符。", "花园": "语义：花园不是能源设备，不能与光伏和储能系统构成网络。", "厨房": "语义：厨房是房间，与光伏和储能系统的技术语境无关。", "诗篇": "语域：诗篇是文学用语，与这里的技术性表述不符。"}, "sentence_index": 0, "correct_answer": "产消者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在网上买东西，是一位产消者。", "explanation": "这里应该用〈消费者〉。产消者既生产又消费，只买东西、不生产的人应称消费者。"}, {"text": "这家中介平台只负责撮合买卖，是一家产消者。", "explanation": "这里应该用〈中介〉。平台只撮合交易，既不生产也不消费商品，不是产消者。"}, {"text": "这家工厂只负责生产，不自己使用产品，是一家产消者。", "explanation": "这里应该用〈生产者〉。工厂只生产、不自己使用产品，而产消者既生产又消费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13749, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产消者", "is_correct": true, "explanation": "正确。“社区里的产消者”指既发电又用电的人或组织，可以互相分享电力。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店不发电也不用电分享，与“分享电力”的语境不符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑构件，不能分享电力，句意不通。"}, {"text": "游戏", "is_correct": false, "explanation": "搭配：“游戏”与“分享电力”不搭配，游戏不是能源的主体。"}], "explanations": {"产消者": "正确。“社区里的产消者”指既发电又用电的人或组织，可以互相分享电力。", "书店": "语义：书店不发电也不用电分享，与“分享电力”的语境不符。", "窗户": "语义：窗户是建筑构件，不能分享电力，句意不通。", "游戏": "搭配：“游戏”与“分享电力”不搭配，游戏不是能源的主体。"}, "sentence_index": 6, "correct_answer": "产消者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小王从电网买电，再转卖给邻居，是一位产消者。", "explanation": "这里应该用〈中间商〉。只买进再转卖的人是中间商，并不生产电，不是产消者。"}, {"text": "这位用户只用电，不发电，是一位产消者。", "explanation": "这里应该用〈用户〉。只用电、不发电的人是用户，产消者必须既生产又消费。"}, {"text": "这家电力公司只负责卖电，不发电，是一家产消者。", "explanation": "这里应该用〈供电商〉。只卖电、不自己发电的组织应称供电商，不是产消者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13749, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她家装了太阳能板，既用电也卖电，是一位产消者的。", "corrected_sentence": "她家装了太阳能板，既用电也卖电，是一位产消者。", "error_description": "错误在“产消者”后多了“的”：作谓语的名词后不加“的”。正确形式是“是一位产消者。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13749, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她自己纺线织布，是一位产消者的。", "corrected_sentence": "她自己纺线织布，是一位产消者。", "error_description": "错误在“产消者”后多了“的”：作谓语的名词后不加“的”。正确形式是“是一位产消者。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13750, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自下而上", "is_correct": true, "explanation": "正确：“自下而上”与“自上而下”表示相反的顺序或方向，是词典列出的反义词。"}, {"text": "温和", "is_correct": false, "explanation": "“温和”形容性情或语气，与顺序或方向无关。"}, {"text": "紧急", "is_correct": false, "explanation": "“紧急”形容事情的急迫程度，与顺序或方向无关。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”形容事物的繁多或不简单，与顺序或方向无关。"}], "correct_answer": "自下而上", "explanations": {"自下而上": "正确：“自下而上”与“自上而下”表示相反的顺序或方向，是词典列出的反义词。", "温和": "“温和”形容性情或语气，与顺序或方向无关。", "紧急": "“紧急”形容事情的急迫程度，与顺序或方向无关。", "复杂": "“复杂”形容事物的繁多或不简单，与顺序或方向无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13750, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自下而上", "is_correct": true, "explanation": "正确：“自下而上”与“自上而下”表示相反的顺序或方向，是词典列出的反义词。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”形容事情不复杂，与顺序或方向无关。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白或分明，与顺序或方向无关。"}, {"text": "鲜艳", "is_correct": false, "explanation": "“鲜艳”形容颜色明亮，与顺序或方向无关。"}], "correct_answer": "自下而上", "explanations": {"自下而上": "正确：“自下而上”与“自上而下”表示相反的顺序或方向，是词典列出的反义词。", "简单": "“简单”形容事情不复杂，与顺序或方向无关。", "清楚": "“清楚”形容明白或分明，与顺序或方向无关。", "鲜艳": "“鲜艳”形容颜色明亮，与顺序或方向无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13750, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指从上面到下面，表示顺序或方向。", "primary_collocate": null, "pronunciation": "zì shàng ér xià", "ipa": "tsɨ˥˩ ʂaŋ˥˩ ɚ˧˥ ɕja˥˩", "syllable_count": 4, "sentences": [{"text": "当分布式光伏与储能系统构成“产消者”网络，传统自上而下的电网架构正被去中心化模式解构。", "target_word": "自上而下", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司的决定是自上而下传达的。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次改革自上而下，一层一层推行。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们自上而下读这张表。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "命令自上而下，由经理传给员工。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用自上而下的方法管理公司。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请自上而下一行一行地看这份名单。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋楼的检查是自上而下进行的。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自上而下的管理，有时听不到员工的话。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划是自上而下做的，先由领导定。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自下而上", "label": "反义"}], "register": "书面", "sense_fingerprint": "形容词：从上层到下层，如管理、传达的顺序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff80419-2652-460d-9a29-0cfc782ab013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13750, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自上而下", "is_correct": true, "explanation": "正确：“自上而下”修饰“电网架构”，表示层级从上到下的组织方式，与句中“去中心化”形成对比。"}, {"text": "自愿", "is_correct": false, "explanation": "语义：“自愿”指出于本人意愿，不能用来描述电网的架构。"}, {"text": "自行", "is_correct": false, "explanation": "搭配：“自行”是副词，不能直接修饰名词“电网架构”。"}, {"text": "自费", "is_correct": false, "explanation": "搭配：“自费”说费用由个人承担，与电网架构的组织方式无关。"}], "explanations": {"自上而下": "正确：“自上而下”修饰“电网架构”，表示层级从上到下的组织方式，与句中“去中心化”形成对比。", "自愿": "语义：“自愿”指出于本人意愿，不能用来描述电网的架构。", "自行": "搭配：“自行”是副词，不能直接修饰名词“电网架构”。", "自费": "搭配：“自费”说费用由个人承担，与电网架构的组织方式无关。"}, "sentence_index": 0, "correct_answer": "自上而下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告是自上而下汇总的，先由基层写，再交给总部。", "explanation": "这里应该用〈自下而上〉。报告先由基层写、再交总部，是从下往上，而“自上而下”指从上往下，方向不符。"}, {"text": "建议自上而下传到领导那里，提的都是基层的想法。", "explanation": "这里应该用〈由下而上〉。建议从基层传到领导，是从下往上，不能说“自上而下”。"}, {"text": "这碗面的味道很自上而下，大家都爱吃。", "explanation": "这里应该用〈鲜美〉。“自上而下”表示层级或方向（也可指做事的方式），不能用来形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自上而下", "is_correct": true, "explanation": "正确：“自上而下”修饰动词“看”，表示按从上到下的顺序，与“一行一行地”相合。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示一起进行，与“一行一行地”的逐个顺序相矛盾。"}, {"text": "整体地", "is_correct": false, "explanation": "语义：“整体地”表示作为一个整体，与“一行一行地”的逐行处理相矛盾。"}, {"text": "齐声地", "is_correct": false, "explanation": "搭配：“齐声”多用于说话或唱歌，不能用来修饰“看”的动作。"}], "explanations": {"自上而下": "正确：“自上而下”修饰动词“看”，表示按从上到下的顺序，与“一行一行地”相合。", "同时": "语义：“同时”表示一起进行，与“一行一行地”的逐个顺序相矛盾。", "整体地": "语义：“整体地”表示作为一个整体，与“一行一行地”的逐行处理相矛盾。", "齐声地": "搭配：“齐声”多用于说话或唱歌，不能用来修饰“看”的动作。"}, "sentence_index": 6, "correct_answer": "自上而下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "问题要自上而下往上报。", "explanation": "这里应该用〈逐级〉。“往上报”是从下到上，与“自上而下”的方向相反。"}, {"text": "今天的天气是自上而下的。", "explanation": "这里应该用〈晴朗〉之类的状况词。这句把“自上而下”当成了描述天气状况的词，它只能表示层级或方向。"}, {"text": "他的声音很自上而下，大家都听得见。", "explanation": "这里应该用〈洪亮〉。“自上而下”表示层级或方向（也可指做事的方式），不能用来形容声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们需要一种自上而下管理方式。", "corrected_sentence": "我们需要一种自上而下的管理方式。", "error_description": "“自上而下”作定语修饰名词“管理方式”时，中间要加“的”，应说“自上而下的管理方式”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你自上而下的检查这台机器。", "corrected_sentence": "请你自上而下地检查这台机器。", "error_description": "“自上而下”修饰动词“检查”时要用状语标记“地”，不能用定语标记“的”，应说“自上而下地检查”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
