INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13753, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指两个节点之间直接建立连接，不经过中间环节的通信或传输方式。", "primary_collocate": null, "pronunciation": "diǎn duì diǎn", "ipa": "tjɛn˨˩˦ twei˥˩ tjɛn˨˩˦", "syllable_count": 3, "sentences": [{"text": "区块链技术赋能点对点电力交易，家庭富余电能可直接售予社区用户；人工智能算法则通过气象数据与用电行为预测，实现跨区域源荷动态平衡。", "target_word": "点对点", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这两台电脑可以点对点连接。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点对点传输不需要服务器。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们用点对点的方式分享文件。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点对点通信比较快，也比较直接。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件支持点对点聊天。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点对点的网络里，每台电脑都是平等的。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们通过点对点的方式交换数据。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点对点连接减少了中间环节。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司选择点对点传输，是为了更安全。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "點對點", "label": "繁体"}], "register": "书面", "sense_fingerprint": "点对点：两个节点直接连接、不经中间环节的通信或传输方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815e1ad1-3b67-482d-a38a-19e3d87ec5a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13753, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "点对点", "is_correct": true, "explanation": "「点对点」指不经中间环节的直接交易，与后句「直接售予社区用户」相符。"}, {"text": "间接", "is_correct": false, "explanation": "语义：「间接」与后句「直接售予社区用户」相矛盾。"}, {"text": "卫星", "is_correct": false, "explanation": "语义：「卫星」与电力交易无关，不能用来修饰「电力交易」。"}, {"text": "人工", "is_correct": false, "explanation": "搭配：「人工」多指人工操作，不能修饰「电力交易」这种交易方式。"}], "explanations": {"点对点": "「点对点」指不经中间环节的直接交易，与后句「直接售予社区用户」相符。", "间接": "语义：「间接」与后句「直接售予社区用户」相矛盾。", "卫星": "语义：「卫星」与电力交易无关，不能用来修饰「电力交易」。", "人工": "搭配：「人工」多指人工操作，不能修饰「电力交易」这种交易方式。"}, "sentence_index": 0, "correct_answer": "点对点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把伞是点对点的，不会漏雨。", "explanation": "这里应该用〈防水〉。「点对点」描述两端之间的直接连接，不能用来形容伞不漏雨。"}, {"text": "这台电脑的硬盘是点对点的，容量很大。", "explanation": "这里应该用〈容量大〉。「点对点」描述两端之间的直接连接，不能用来形容硬盘的容量。"}, {"text": "这只杯子点对点地放在桌上。", "explanation": "这里应该用〈正正地〉。「点对点」描述两端之间的直接连接，不能用来形容杯子的摆放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13753, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点对点", "is_correct": true, "explanation": "「点对点」网络中每台电脑地位平等，与「每台电脑都是平等的」相符。"}, {"text": "集中", "is_correct": false, "explanation": "语义：「集中」指由中心统一控制，与「每台电脑都是平等的」相抵。"}, {"text": "层级", "is_correct": false, "explanation": "语义：「层级」强调上下级关系，与「平等」矛盾。"}, {"text": "主从", "is_correct": false, "explanation": "搭配：「主从」多修饰「结构」或「关系」，不修饰「网络里」，搭配不当。"}], "explanations": {"点对点": "「点对点」网络中每台电脑地位平等，与「每台电脑都是平等的」相符。", "集中": "语义：「集中」指由中心统一控制，与「每台电脑都是平等的」相抵。", "层级": "语义：「层级」强调上下级关系，与「平等」矛盾。", "主从": "搭配：「主从」多修饰「结构」或「关系」，不修饰「网络里」，搭配不当。"}, "sentence_index": 6, "correct_answer": "点对点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条通知是点对点的，全班都能收到。", "explanation": "这里应该用〈群发〉。「点对点」指两端之间的直接连接，发给全班应用〈群发〉。"}, {"text": "老师对全班点对点讲课。", "explanation": "这里应该用〈面向全班〉。「点对点」指两端之间的直接连接，对全班讲课要用〈面向全班〉，不能用「点对点」。"}, {"text": "他们点对点地吃完了整个西瓜。", "explanation": "这里应该用〈一口气〉。「点对点」描述两端直接连接，不能修饰吃东西的动作，吃完西瓜应说〈一口气吃完〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13753, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "设备之间用点对点地方式通信。", "corrected_sentence": "设备之间用点对点的方式通信。", "error_description": "的地误用：「点对点」修饰名词「方式」，应用结构助词「的」，不能用「地」。应改为「用点对点的方式通信」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13753, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套系统点对点的传得很快。", "corrected_sentence": "这套系统点对点地传得很快。", "error_description": "的地误用：「点对点」修饰动词「传」，作状语时应用「地」，不能用「的」。应改为「点对点地传得很快」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
