INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13755, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "足够而有剩余；多余。", "primary_collocate": null, "pronunciation": "fù yu", "ipa": "fu˥˩ y", "syllable_count": 2, "sentences": [{"text": "区块链技术赋能点对点电力交易，家庭富余电能可直接售予社区用户；人工智能算法则通过气象数据与用电行为预测，实现跨区域源荷动态平衡。", "target_word": "富余", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我家的粮食还很富余。", "target_word": "富余", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个月钱很富余，不用担心。", "target_word": "富余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今天时间富余，可以帮你。", "target_word": "富余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套房子的房间很富余，来再多客人也住得下。", "target_word": "富余", "complexity_tier": "T3", "furigana": "zhè tào fáng zi de fáng jiān hěn fù yu, lái zài duō kè rén yě zhù de xià.", "sentence_source": "generated"}, {"text": "我们的人手不富余，请再等等。", "target_word": "富余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次买的菜很富余，晚饭吃不完。", "target_word": "富余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂里的电很富余，可以卖给别人。", "target_word": "富余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时间富余时，你可以多看书。", "target_word": "富余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年雨水多，水库里的水很富余。", "target_word": "富余", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "足够之后还有剩下的，数量比需要的多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815e1ad1-3b67-482d-a38a-19e3d87ec5a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13755, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "富余", "is_correct": true, "explanation": "正确。富余：足够之后还有剩余，数量比需要的多。"}, {"text": "富裕", "is_correct": false, "explanation": "yù（第四声）与轻声 yu 声调不同，富裕指钱财充足，不是剩余。"}, {"text": "赋予", "is_correct": false, "explanation": "yǔ（第三声）与轻声 yu 声调不同，赋予指给予，意思不同。"}, {"text": "富于", "is_correct": false, "explanation": "yú（第二声）与轻声 yu 声调不同，富于指具有某种特点，意思不同。"}], "explanations": {"富余": "正确。富余：足够之后还有剩余，数量比需要的多。", "富裕": "yù（第四声）与轻声 yu 声调不同，富裕指钱财充足，不是剩余。", "赋予": "yǔ（第三声）与轻声 yu 声调不同，赋予指给予，意思不同。", "富于": "yú（第二声）与轻声 yu 声调不同，富于指具有某种特点，意思不同。"}, "sentence_index": null, "correct_answer": "富余"}, "level_3": {"options": [{"text": "富余", "is_correct": true, "explanation": "正确。「家庭富余电能」指家里用不完、可以卖出去的电，符合句意。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：陈旧指过时，与可以售予他人的多余电能不符。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：寒冷形容温度，不能用来修饰电能。"}, {"text": "缓慢", "is_correct": false, "explanation": "搭配：缓慢形容速度，不用来修饰电能。"}], "explanations": {"富余": "正确。「家庭富余电能」指家里用不完、可以卖出去的电，符合句意。", "陈旧": "语义：陈旧指过时，与可以售予他人的多余电能不符。", "寒冷": "语义：寒冷形容温度，不能用来修饰电能。", "缓慢": "搭配：缓慢形容速度，不用来修饰电能。"}, "sentence_index": 0, "correct_answer": "富余"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的知识很富余，讲课很有深度。", "explanation": "这里应该用〈丰富〉。知识要说「丰富」，「富余」指数量超过需要，不用于知识。"}, {"text": "我昨晚的睡眠很富余，早上精神很好。", "explanation": "这里应该用〈充足〉。睡眠要说「充足」，「富余」不用于睡眠。"}, {"text": "他的心胸很富余，很能包容别人。", "explanation": "这里应该用〈宽广〉。心胸要说「宽广」，「富余」不用来形容心胸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13755, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "富余", "is_correct": true, "explanation": "正确。「这次买的菜很富余」指买得多，晚饭吃不完，符合句意。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：菜不能「聪明」，这个形容词不能用在菜上。"}, {"text": "紧张", "is_correct": false, "explanation": "语义：菜不会「紧张」，与「晚饭吃不完」的语境不合。"}, {"text": "清晰", "is_correct": false, "explanation": "搭配：「清晰」形容声音、字迹、思路，不用来形容菜。"}], "explanations": {"富余": "正确。「这次买的菜很富余」指买得多，晚饭吃不完，符合句意。", "聪明": "语义：菜不能「聪明」，这个形容词不能用在菜上。", "紧张": "语义：菜不会「紧张」，与「晚饭吃不完」的语境不合。", "清晰": "搭配：「清晰」形容声音、字迹、思路，不用来形容菜。"}, "sentence_index": 6, "correct_answer": "富余"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为人很富余，对朋友很大方。", "explanation": "这里应该用〈宽厚〉。形容为人要说「宽厚」，「富余」指数量超过需要，不形容人的品性。"}, {"text": "他的脾气很富余，很少发火。", "explanation": "这里应该用〈温和〉。脾气要说「温和」，「富余」指数量超过需要，不用于形容脾气。"}, {"text": "这篇文章的情绪很富余，读完很感动。", "explanation": "这里应该用〈饱满〉。情绪要说「饱满」，「富余」不用于情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13755, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们家的米很还富余。", "corrected_sentence": "他们家的米还很富余。", "error_description": "错误：「很还富余」；正确：「还很富余」。副词「还」要放在「很」前面，应说「还很富余」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13755, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次的米很很富余，可以送给邻居。", "corrected_sentence": "这次的米很富余，可以送给邻居。", "error_description": "错误：「很很富余」；正确：「很富余」。程度副词「很」只用一个，重复使用不合规范，应说「很富余」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13756, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "购买", "is_correct": true, "explanation": "反义：购买是卖的对面，指买方取得东西，与售予相对。"}, {"text": "收藏", "is_correct": false, "explanation": "收藏：指保存珍贵的东西，与售予没有对立关系。"}, {"text": "修理", "is_correct": false, "explanation": "修理：指把坏了的东西弄好，与售予无关。"}, {"text": "种植", "is_correct": false, "explanation": "种植：指栽培植物，与售予无关。"}], "correct_answer": "购买", "explanations": {"购买": "反义：购买是卖的对面，指买方取得东西，与售予相对。", "收藏": "收藏：指保存珍贵的东西，与售予没有对立关系。", "修理": "修理：指把坏了的东西弄好，与售予无关。", "种植": "种植：指栽培植物，与售予无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13756, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "购买", "is_correct": true, "explanation": "反义：购买与售予方向相反，售予是卖出，购买是买进。"}, {"text": "翻译", "is_correct": false, "explanation": "翻译：指转换语言的表达，与售予无关。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳：指在水中活动，与售予无关。"}, {"text": "生长", "is_correct": false, "explanation": "生长：指植物或人的成长，与售予无关。"}], "correct_answer": "购买", "explanations": {"购买": "反义：购买与售予方向相反，售予是卖出，购买是买进。", "翻译": "翻译：指转换语言的表达，与售予无关。", "游泳": "游泳：指在水中活动，与售予无关。", "生长": "生长：指植物或人的成长，与售予无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13756, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把物品或服务卖给他人。", "primary_collocate": null, "pronunciation": "shòu yǔ", "ipa": "ʂoʊ˥˩ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "区块链技术赋能点对点电力交易，家庭富余电能可直接售予社区用户；人工智能算法则通过气象数据与用电行为预测，实现跨区域源荷动态平衡。", "target_word": "售予", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他把旧房子售予了邻居。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定把这块地售予一家银行。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批货已经售予外国客户了。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人将祖传的画售予博物馆。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把多余的电售予附近居民。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子不能售予个人。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把农场售予一位年轻人。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店主愿意把小店售予老员工。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年她把股票全部售予朋友。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "售予了", "label": "体标"}, {"form": "售予过", "label": "体标"}], "register": "书面", "sense_fingerprint": "把物品或服务卖给某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff80419-2652-460d-9a29-0cfc782ab013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13756, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "售予", "is_correct": true, "explanation": "售予：把物品或服务卖给他人，正是这里的意思。"}, {"text": "手语", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，意思是手语。"}, {"text": "咒语", "is_correct": false, "explanation": "zhòu 与 shòu 声母不同（zh 与 sh），意思是咒语。"}, {"text": "术语", "is_correct": false, "explanation": "shù 与 shòu 韵母不同（shòu 多一个 o），意思是术语。"}, {"text": "熟语", "is_correct": false, "explanation": "shú（第二声）与 shòu（第四声）声调不同，韵母也不同，意思是熟语。"}], "explanations": {"售予": "售予：把物品或服务卖给他人，正是这里的意思。", "手语": "shǒu（第三声）与 shòu（第四声）声调不同，意思是手语。", "咒语": "zhòu 与 shòu 声母不同（zh 与 sh），意思是咒语。", "术语": "shù 与 shòu 韵母不同（shòu 多一个 o），意思是术语。", "熟语": "shú（第二声）与 shòu（第四声）声调不同，韵母也不同，意思是熟语。"}, "sentence_index": null, "correct_answer": "售予"}, "level_3": {"options": [{"text": "售予", "is_correct": true, "explanation": "语义：“售予”正是把富余电能卖给用户，与前文的“电力交易”一致。"}, {"text": "赠予", "is_correct": false, "explanation": "语义：赠予是无偿送给，与前文“电力交易”以买卖为前提相矛盾。"}, {"text": "收购", "is_correct": false, "explanation": "配价：收购的宾语应是物品，“收购社区用户”不成立；且收购是从对方买进，方向与“售予用户”相反。"}, {"text": "收取", "is_correct": false, "explanation": "配价：收取的宾语是费用，不能直接带“社区用户”作宾语，“收取社区用户”说不通。"}], "explanations": {"售予": "语义：“售予”正是把富余电能卖给用户，与前文的“电力交易”一致。", "赠予": "语义：赠予是无偿送给，与前文“电力交易”以买卖为前提相矛盾。", "收购": "配价：收购的宾语应是物品，“收购社区用户”不成立；且收购是从对方买进，方向与“售予用户”相反。", "收取": "配价：收取的宾语是费用，不能直接带“社区用户”作宾语，“收取社区用户”说不通。"}, "sentence_index": 0, "correct_answer": "售予"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校向优秀学生售予了一笔奖学金。", "explanation": "这里应该用〈颁发〉。售予是把东西卖给买方，奖学金是奖励而不是买卖的商品，应说颁发奖学金。"}, {"text": "他把房子售予了学生，每月收取三千元租金。", "explanation": "这里应该用〈出租〉。售予是一次性卖断，后面“每月收取租金”说明是按月收钱的租赁，应说出租。"}, {"text": "父亲把农场无偿售予了儿子。", "explanation": "这里应该用〈赠予〉。售予是有偿卖给买方，“无偿”说明不是买卖，应说赠予。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "售予", "is_correct": true, "explanation": "语义：这里说房子不能卖给个人，“售予”正合此意。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：房子是无生命的东西，不能欺骗个人，句子说不通。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：房子没有情感，不能喜欢个人，句子说不通。"}, {"text": "出租", "is_correct": false, "explanation": "配价：出租要说“出租给某人”，不能直接带“个人”作宾语，“出租个人”不成立。"}], "explanations": {"售予": "语义：这里说房子不能卖给个人，“售予”正合此意。", "欺骗": "语义：房子是无生命的东西，不能欺骗个人，句子说不通。", "喜欢": "语义：房子没有情感，不能喜欢个人，句子说不通。", "出租": "配价：出租要说“出租给某人”，不能直接带“个人”作宾语，“出租个人”不成立。"}, "sentence_index": 6, "correct_answer": "售予"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从邻居那里售予了一辆旧车。", "explanation": "这里应该用〈购买〉。售予是卖方把东西卖给买方，“从邻居那里”表示来源，句子却说卖方从对方那里卖出，方向搞反了。"}, {"text": "那家公司从农民手里售予了一片土地。", "explanation": "这里应该用〈收购〉。收购是从别人手里买进，“从农民手里”是来源；售予的方向是卖方交给买方，二者正好相反。"}, {"text": "我从商店售予了一台电视。", "explanation": "这里应该用〈买下〉。买下是买方取得东西，“从商店”是来源；用售予就把买卖方向搞反了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司把这栋楼售予给一家保险公司。", "corrected_sentence": "公司把这栋楼售予一家保险公司。", "error_description": "错误形式：“售予给”。正确形式：“售予”。“予”本身已含“给”的意思，后面不能再加“给”，应说“售予一家保险公司”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把老房子售予了一只律师。", "corrected_sentence": "他把老房子售予了一位律师。", "error_description": "错误形式：“一只律师”。正确形式：“一位律师”。“只”多用于动物或物品，“律师”指人，应用量词“位”，应说“售予了一位律师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
