INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13760, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "使用电力来驱动设备或照明。", "primary_collocate": null, "pronunciation": "yòng diàn", "ipa": "jʊŋ˥˩ tjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "区块链技术赋能点对点电力交易，家庭富余电能可直接售予社区用户；人工智能算法则通过气象数据与用电行为预测，实现跨区域源荷动态平衡。", "target_word": "用电", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "夏天空调多，用电很多。", "target_word": "用电", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请注意用电安全。", "target_word": "用电", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "晚上是用电最多的时间。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂每个月用电很多。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校提醒学生节约用电。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天我们家用电比夏天少。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用电的时候，手不能是湿的。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里终于可以用电了。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用电太多，电费就会很高。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "用电量", "label": "复合"}], "register": "中性", "sense_fingerprint": "使用电力来驱动设备或照明的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815e1ad1-3b67-482d-a38a-19e3d87ec5a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用电", "is_correct": true, "explanation": "正确。“用电行为”指使用电力的行为，与气象数据一起用于预测。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是用电的行为，无法用来预测用电。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是一个地方，不能说“花园行为”，与用电无关。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是文学作品，与用电行为无关。"}], "explanations": {"用电": "正确。“用电行为”指使用电力的行为，与气象数据一起用于预测。", "颜色": "语义：颜色不是用电的行为，无法用来预测用电。", "花园": "语义：花园是一个地方，不能说“花园行为”，与用电无关。", "诗歌": "语义：诗歌是文学作品，与用电行为无关。"}, "sentence_index": 0, "correct_answer": "用电"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冰箱是一种用电。", "explanation": "这里应该用〈用电器〉。用电器是用电工作的器具，冰箱是器具；“用电”指使用电能的行为，不能指物品。"}, {"text": "昨晚突然用电了，全家只好点蜡烛。", "explanation": "这里应该用〈停电〉。停电指供电突然中断，所以全家只好点蜡烛；“用电”是使用电能的行为，不能表示电被切断。"}, {"text": "学校的用电有三层楼。", "explanation": "这里应该用〈教学楼〉。“用电”是使用电能的行为，不能指建筑物，所以不能说“有三层楼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用电", "is_correct": true, "explanation": "正确。“用电”指使用电力，冬天家里用电比夏天少。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史是过去的事情，不能用家里的多少来和夏天比较。"}, {"text": "教授", "is_correct": false, "explanation": "搭配：“我们家教授”不能这样说，人不是家里的用量，不能和夏天比多少。"}, {"text": "旋律", "is_correct": false, "explanation": "语义：旋律是音乐的音高组合，与家里的用量无关。"}], "explanations": {"用电": "正确。“用电”指使用电力，冬天家里用电比夏天少。", "历史": "语义：历史是过去的事情，不能用家里的多少来和夏天比较。", "教授": "搭配：“我们家教授”不能这样说，人不是家里的用量，不能和夏天比多少。", "旋律": "语义：旋律是音乐的音高组合，与家里的用量无关。"}, "sentence_index": 6, "correct_answer": "用电"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块用电很耐用，可以用两年。", "explanation": "这里应该用〈电池〉。电池是可以耐用的物品；“用电”是行为，不能说“很耐用”。"}, {"text": "用电是一种能量。", "explanation": "这里应该用〈电能〉。电能是一种能量；“用电”是使用电能的行为，不能说“是一种能量”。"}, {"text": "这根用电很粗，能承受大电流。", "explanation": "这里应该用〈电线〉。电线是可以粗细的物体；“用电”是行为，不能用来形容粗细。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校终于可以用电着。", "corrected_sentence": "学校终于可以用电了。", "error_description": "了/着错误：“终于可以……了”表示状态发生变化，应说“可以用电了”；“着”表示动作持续，不能说“用电着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月我们家用电得很多，电费也高。", "corrected_sentence": "这个月我们家用电很多，电费也高。", "error_description": "补语错误：“用电”后面直接说程度时不能加“得”，应说“用电很多”（或“用电用得很多”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3186c52-aa3c-4555-b2fb-c321f9c6f8eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
