INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13761, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13761, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据已知情况，对未来的事情进行推测或估计。", "primary_collocate": null, "pronunciation": "yù cè", "ipa": "y˥˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "区块链技术赋能点对点电力交易，家庭富余电能可直接售予社区用户；人工智能算法则通过气象数据与用电行为预测，实现跨区域源荷动态平衡。", "target_word": "预测", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "专家预测明年天气会更热。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也无法预测比赛的结果。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据数据，他预测房价会下降。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气象台预测明天有大雨。", "target_word": "预测", "complexity_tier": "T3", "furigana": "qì xiàng tái yù cè míng tiān yǒu dà yǔ", "sentence_source": "generated"}, {"text": "老师预测这次考试不太难。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她预测得很准。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司预测今年的销量会增加。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人预测过这样的变化。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们可以预测下个月的客流量。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预测了", "label": "体标"}, {"form": "预测过", "label": "体标"}], "register": "中性", "sense_fingerprint": "根据已知情况推测未来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ff80419-2652-460d-9a29-0cfc782ab013') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13761, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预测", "is_correct": true, "explanation": "语义：预测指根据已知数据推断将来的情况，与“气象数据与用电行为”的推算一致。"}, {"text": "感受", "is_correct": false, "explanation": "搭配：“感受”的宾语是感觉，不能说感受用电行为。"}, {"text": "享用", "is_correct": false, "explanation": "搭配：“享用”的宾语是享受的东西，不能说享用用电行为。"}, {"text": "检修", "is_correct": false, "explanation": "语义：检修是对设备的检查和修理，与通过数据推算未来的语境不合。"}], "explanations": {"预测": "语义：预测指根据已知数据推断将来的情况，与“气象数据与用电行为”的推算一致。", "感受": "搭配：“感受”的宾语是感觉，不能说感受用电行为。", "享用": "搭配：“享用”的宾语是享受的东西，不能说享用用电行为。", "检修": "语义：检修是对设备的检查和修理，与通过数据推算未来的语境不合。"}, "sentence_index": 0, "correct_answer": "预测"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法医预测死者死于昨天夜里。", "explanation": "这里应该用〈推断〉。昨天夜里已经发生的事只能推断，不能用预测；预测只用于尚未发生的事。"}, {"text": "她预测了童年的那次旅行。", "explanation": "这里应该用〈回忆〉。童年的事已经过去，预测只能用于将来的事。"}, {"text": "警察预测了事故的原因。", "explanation": "这里应该用〈查明〉。事故已经发生，原因要去查明，不能用预测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13761, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预测", "is_correct": true, "explanation": "语义：“预测得很准”指推断的结果准确，与句意相符。"}, {"text": "哭", "is_correct": false, "explanation": "语义：哭与“准不准”无关，“哭得很准”说不通。"}, {"text": "睡", "is_correct": false, "explanation": "搭配：睡觉不能用“准”来形容，“睡得很准”不成立。"}, {"text": "笑", "is_correct": false, "explanation": "语义：笑没有准确与否的问题，“笑得很准”说不通。"}], "explanations": {"预测": "语义：“预测得很准”指推断的结果准确，与句意相符。", "哭": "语义：哭与“准不准”无关，“哭得很准”说不通。", "睡": "搭配：睡觉不能用“准”来形容，“睡得很准”不成立。", "笑": "语义：笑没有准确与否的问题，“笑得很准”说不通。"}, "sentence_index": 6, "correct_answer": "预测"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士预测了病人此刻的体温。", "explanation": "这里应该用〈测量〉。预测是推断将来的情况，此刻的体温已经是已知的，应该用测量。"}, {"text": "店员预测了店里此刻的客人数。", "explanation": "这里应该用〈统计〉。此刻的人数是已知的事实，要用统计；预测只用于将来的情况。"}, {"text": "司机预测了仪表盘上的数字。", "explanation": "这里应该用〈读取〉。仪表盘上的数字就在眼前，应该读取，不能预测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老专家预测地很准。", "corrected_sentence": "这位老专家预测得很准。", "error_description": "错误形式：“地”。正确形式：“得”。“地”用在动词前作状语，动词后引出补语要用“得”，所以应说“预测得很准”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究人员已经预测着明年的销量。", "corrected_sentence": "研究人员已经预测了明年的销量。", "error_description": "错误形式：“预测着”。正确形式：“预测了”。“着”表示动作持续的状态，与“已经”表示的完成相矛盾，应用“了”表示动作已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d556d08-b63b-4743-8382-d884c4168080') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
