INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13764, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物具有补充、增加以完善整体的特性。", "primary_collocate": null, "pronunciation": "bǔ chōng xìng", "ipa": "pu˨˩˦ ʈʂʰʊŋ˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这种系统级创新使清洁能源从补充性能源，进化为新型电力系统的基石。", "target_word": "补充性", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这本书的补充性很强，可以和课本一起用。", "target_word": "补充性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络课程有补充性，不能代替学校教育。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些练习题具有补充性，做不做都可以。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个方案只有补充性，不是主要办法。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把兼职当作补充性收入，不影响正式工作。", "target_word": "补充性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告里的数据只起补充性作用。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种维生素起补充性的作用，不能代替正常饮食。", "target_word": "补充性", "complexity_tier": "T3", "furigana": "zhè zhǒng wéi shēng sù qǐ bǔ chōng xìng de zuò yòng, bù néng dài tì zhèng cháng yǐn shí", "sentence_source": "generated"}, {"text": "他的发言有补充性，让大家听得更明白。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图只是补充性资料，不是考试的重点。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "補充性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "补充性：事物起补充、完善整体作用的特性，不是主要部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31173b25-2d4d-4630-a105-47245d8daad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13764, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "补充性", "is_correct": true, "explanation": "正确：“补充性能源”指起辅助作用的能源，与“进化为……基石”的上升关系相符。"}, {"text": "主导性", "is_correct": false, "explanation": "语义：“主导性”本身已居核心地位，与“从……进化为基石”由次要到核心的转变相矛盾。"}, {"text": "污染性", "is_correct": false, "explanation": "语义：“污染性”与句中的“清洁能源”相冲突，无法与“进化为基石”搭配理解。"}, {"text": "装饰性", "is_correct": false, "explanation": "语义：“装饰性”指起美化作用，与能源的功能无关，不说“装饰性能源”。"}], "explanations": {"补充性": "正确：“补充性能源”指起辅助作用的能源，与“进化为……基石”的上升关系相符。", "主导性": "语义：“主导性”本身已居核心地位，与“从……进化为基石”由次要到核心的转变相矛盾。", "污染性": "语义：“污染性”与句中的“清洁能源”相冲突，无法与“进化为基石”搭配理解。", "装饰性": "语义：“装饰性”指起美化作用，与能源的功能无关，不说“装饰性能源”。"}, "sentence_index": 0, "correct_answer": "补充性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方案的补充性很强，是整个计划的核心。", "explanation": "这里应该用〈主导性〉。补充性指起补充、完善作用，不是主要部分；说“是……核心”要用〈主导性〉。"}, {"text": "这条规定的补充性很强，任何人都不能省略。", "explanation": "这里应该用〈必要性〉。补充性指增加内容使整体更完善，不表示不可缺少；说“任何人都不能省略”要用〈必要性〉。"}, {"text": "他的补充性很强，总是乐于帮别人做事。", "explanation": "用法错误：补充性用来说事物所起的补充作用，不用来形容人的性格。描述人乐于帮忙应说〈热心〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "补充性", "is_correct": true, "explanation": "正确：“只起补充性作用”指数据只起辅助参考的作用，与“只”的限定语气相符。"}, {"text": "装饰性", "is_correct": false, "explanation": "语义：数据是论证用的实用资料，不起装饰作用，与报告语境不符。"}, {"text": "阻碍性", "is_correct": false, "explanation": "语义：数据是补充论证的资料，只起阻碍作用与句意相反。"}, {"text": "无关性", "is_correct": false, "explanation": "语义：“无关性”指毫不相干，与数据应起的作用相反，句意不通。"}], "explanations": {"补充性": "正确：“只起补充性作用”指数据只起辅助参考的作用，与“只”的限定语气相符。", "装饰性": "语义：数据是论证用的实用资料，不起装饰作用，与报告语境不符。", "阻碍性": "语义：数据是补充论证的资料，只起阻碍作用与句意相反。", "无关性": "语义：“无关性”指毫不相干，与数据应起的作用相反，句意不通。"}, "sentence_index": 6, "correct_answer": "补充性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门课有补充性作用，是学好数学的前提。", "explanation": "这里应该用〈基础性〉。补充性指辅助、补充，不是根基；说“前提”要用〈基础性〉。"}, {"text": "这个方案的补充性很强，它完全取代了原来的全部计划。", "explanation": "词义错误：这里说的是取代，应该用〈替代性〉。补充性指增加内容使整体更完善，不表示替换。"}, {"text": "这次相遇的补充性很强，完全是偶然的。", "explanation": "这里应该用〈偶然性〉。补充性指增加内容使整体更完善，与事情出于意外无关；描述相遇的意外性质要用〈偶然性〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套题的补充性强很，学生可以用来查漏补缺。", "corrected_sentence": "这套题的补充性很强，学生可以用来查漏补缺。", "error_description": "语序错误：程度副词“很”应放在形容词“强”之前，“补充性很强”是正确说法，不说“补充性强很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只补充性很强，能帮助学生理解课文。", "corrected_sentence": "这种补充性很强，能帮助学生理解课文。", "error_description": "量词错误：“补充性”是抽象名词，应该用“种”，不用“只”。正确说法是“这种补充性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
