INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13765, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电力系统是由发电、输电、变电、配电和用电等环节组成的整体，用于生产和供应电能。", "primary_collocate": null, "pronunciation": "diàn lì xì tǒng", "ipa": "tjɛn˥˩ li˥˩ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "这种系统级创新使清洁能源从补充性能源，进化为新型电力系统的基石。", "target_word": "电力系统", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这座城市的电力系统很安全。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暴雨把附近的电力系统弄坏了。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在检查电力系统。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电力系统把电从电厂送到千家万户。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天用电多，电力系统的压力很大。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的电力系统已经运行了很多年。", "target_word": "电力系统", "complexity_tier": "T3", "furigana": "zhè ge guó jiā de diànlì xìtǒng yǐjīng yùnxíng le hěn duō nián", "sentence_source": "generated"}, {"text": "他在电力系统工作过十年。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区新建的电力系统让村民用上了电。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学里有一门课专门讲电力系统。", "target_word": "电力系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "套", "label": "量词"}, {"form": "電力系統", "label": "繁体"}], "register": "书面", "sense_fingerprint": "电力系统|发电、输电、变电、配电、用电组成的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c7e75e3-72ef-41eb-a7d0-3ec13fec9d12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13765, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电影", "is_correct": false, "explanation": "语义：句中讲的是清洁能源的演化，电影与能源技术无关，不能作“新型…的基石”。"}, {"text": "电力系统", "is_correct": true, "explanation": "正确：“新型电力系统”指由发电、输电等环节组成的能源体系，与清洁能源的演化语境吻合。"}, {"text": "足球", "is_correct": false, "explanation": "语义：句中讲能源技术的进化，足球与之无关，放进空格后语义不通。"}, {"text": "饭碗", "is_correct": false, "explanation": "语域：“饭碗”是口语词，与这句书面语的语体不协调，也与能源演化的语境不符。"}], "explanations": {"电影": "语义：句中讲的是清洁能源的演化，电影与能源技术无关，不能作“新型…的基石”。", "电力系统": "正确：“新型电力系统”指由发电、输电等环节组成的能源体系，与清洁能源的演化语境吻合。", "足球": "语义：句中讲能源技术的进化，足球与之无关，放进空格后语义不通。", "饭碗": "语域：“饭碗”是口语词，与这句书面语的语体不协调，也与能源演化的语境不符。"}, "sentence_index": 0, "correct_answer": "电力系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他吃了三碗饭，电力系统一下子就恢复了。", "explanation": "这里应该用〈体力〉。电力系统指发电、输电的整体设施，不能比喻人的体力。"}, {"text": "我这个月的电力系统交了两百块钱。", "explanation": "这里应该用〈电费〉。电力系统是设施，不是费用，交的应该是电费。"}, {"text": "我们班的电力系统在运动会上得了冠军。", "explanation": "这里不能用〈电力系统〉指团队，应该用〈班级〉。电力系统不是团体，也不参加比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小说", "is_correct": false, "explanation": "搭配：“运行”用于系统、机器等，不说小说“运行”。"}, {"text": "电力系统", "is_correct": true, "explanation": "正确：句中指国家的供电设施，“运行了很多年”与之搭配自然。"}, {"text": "哥哥", "is_correct": false, "explanation": "语义：哥哥是人，不能“运行”，句中说的是国家的供电设施。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具与国家的供电设施无关，不能说“运行了很多年”。"}], "explanations": {"小说": "搭配：“运行”用于系统、机器等，不说小说“运行”。", "电力系统": "正确：句中指国家的供电设施，“运行了很多年”与之搭配自然。", "哥哥": "语义：哥哥是人，不能“运行”，句中说的是国家的供电设施。", "玩具": "语义：玩具与国家的供电设施无关，不能说“运行了很多年”。"}, "sentence_index": 6, "correct_answer": "电力系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个蛋糕的电力系统很甜。", "explanation": "这里应该用〈甜度〉或〈味道〉。电力系统是输电设施，不能形容食物的味道。"}, {"text": "我把电力系统送给了朋友当生日礼物。", "explanation": "这里把〈电力系统〉当成了可以送人的实物，应该用〈手表〉这类物品。电力系统是供电的设施，不能赠送。"}, {"text": "这首歌的电力系统很好听。", "explanation": "这里应该用〈旋律〉。电力系统指供电设施，不能用来评价歌曲好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市新建了一只电力系统。", "corrected_sentence": "这座城市新建了一套电力系统。", "error_description": "量词错误：电力系统的量词是“套”，“只”只用于动物等。应说“一套电力系统”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹电力系统里工作。", "corrected_sentence": "我妹妹在电力系统里工作。", "error_description": "介词遗漏：表示处所要用“在”，应说“在电力系统里工作”，不说“电力系统里工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bb6c909-05ba-4671-a333-1333114b6300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
