INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13766, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指长度在纳米（十亿分之一米）量级的，形容极小的尺寸。", "primary_collocate": null, "pronunciation": "nà mǐ jí", "ipa": "na˥˩ mi˨˩˦ tɕi˧˥", "syllable_count": 3, "sentences": [{"text": "回望历史，从木质风车到纳米级光伏材料，能源技术的演化本质是人类对自然规律认知深度的具象化。", "target_word": "纳米级", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种纳米级材料比头发细很多。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家做出了纳米级芯片。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "纳米级的颗粒，肉眼是看不见的。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂能生产纳米级的涂层。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种颗粒的大小是纳米级的。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用纳米级颗粒把药物送到病灶处。", "target_word": "纳米级", "complexity_tier": "T3", "furigana": "yī shēng yòng nà mǐ jí kē lì bǎ yào wù sòng dào bìng zào chù", "sentence_source": "generated"}, {"text": "要看清纳米级的东西，必须用特殊显微镜。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块玻璃表面有一层纳米级薄膜。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室里的仪器可以测量纳米级的长度。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "納米級", "label": "繁体"}], "register": "书面", "sense_fingerprint": "纳米级：尺寸在纳米量级的，极其微小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31173b25-2d4d-4630-a105-47245d8daad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纳米级", "is_correct": true, "explanation": "正确。“纳米级”修饰“光伏材料”，指纳米量级的尺寸，与句中由旧到新的演化相合。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指过时，与“光伏材料”这类当代技术矛盾，也与句中由旧到新的演化方向相反。"}, {"text": "木质", "is_correct": false, "explanation": "搭配：“木质”说材料由木头做成，光伏材料不用木材，且句中“木质风车”已占用这一义。"}, {"text": "远古", "is_correct": false, "explanation": "语义：“远古”指很久以前的年代，与“光伏材料”这种当代技术不能搭配。"}], "explanations": {"纳米级": "正确。“纳米级”修饰“光伏材料”，指纳米量级的尺寸，与句中由旧到新的演化相合。", "陈旧": "语义：“陈旧”指过时，与“光伏材料”这类当代技术矛盾，也与句中由旧到新的演化方向相反。", "木质": "搭配：“木质”说材料由木头做成，光伏材料不用木材，且句中“木质风车”已占用这一义。", "远古": "语义：“远古”指很久以前的年代，与“光伏材料”这种当代技术不能搭配。"}, "sentence_index": 0, "correct_answer": "纳米级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的贡献是纳米级的，但大家都很感激他。", "explanation": "这里应该用〈微不足道〉。纳米级只形容物体的尺寸，贡献这类抽象价值不能用它来说明，应说“他的贡献微不足道”。"}, {"text": "他每个月的收入是纳米级的，还不够吃饭。", "explanation": "这里应该用〈微薄〉。纳米级只说物体的尺寸，收入的多少不能用它形容，应说“他的收入微薄”。"}, {"text": "他说话的声音是纳米级的，大家都听不清。", "explanation": "这里应该用〈微弱〉。纳米级只形容尺寸，声音的强弱不能用它描述，应说“他的声音很微弱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纳米级", "is_correct": true, "explanation": "正确。“纳米级”修饰“颗粒”，指能进入病灶的极细颗粒，与送药的语境相合。"}, {"text": "液态", "is_correct": false, "explanation": "语义：“液态”指液体状，与“颗粒”这种固体形态矛盾。"}, {"text": "块状", "is_correct": false, "explanation": "体貌：“块状”描述外形成块，与能送入病灶的细小颗粒不符。"}, {"text": "巨大", "is_correct": false, "explanation": "语义：“巨大”指体积庞大，颗粒太大无法送入病灶，与句意冲突。"}], "explanations": {"纳米级": "正确。“纳米级”修饰“颗粒”，指能进入病灶的极细颗粒，与送药的语境相合。", "液态": "语义：“液态”指液体状，与“颗粒”这种固体形态矛盾。", "块状": "体貌：“块状”描述外形成块，与能送入病灶的细小颗粒不符。", "巨大": "语义：“巨大”指体积庞大，颗粒太大无法送入病灶，与句意冲突。"}, "sentence_index": 6, "correct_answer": "纳米级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场演出只持续了纳米级的时间，转眼就结束了。", "explanation": "这里应该用〈短暂〉。纳米级只说明物体的尺寸，时间的长短不能用它形容，应说“持续了短暂的时间”。"}, {"text": "他的伤是纳米级的，过几天就好了。", "explanation": "这里应该用〈轻微〉。纳米级只形容尺寸，伤势的轻重不能用它说明，应说“他只受了轻微的伤”。"}, {"text": "我只吃了纳米级的饭，还是饿得厉害。", "explanation": "这里应该用〈一丁点儿〉。纳米级只形容尺寸，饭量不能用它来说明，应说“我只吃了一丁点儿饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这层薄膜的厚度是很纳米级的。", "corrected_sentence": "这层薄膜的厚度是纳米级的。", "error_description": "程度副词误用：“纳米级”表示尺寸所属的量级，属于分类性词语，不能受“很”修饰；正确说法是“是纳米级的”，不说“是很纳米级的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台仪器的精度是纳米级地。", "corrected_sentence": "这台仪器的精度是纳米级的。", "error_description": "助词误用：“纳米级”作谓语时接“的”，不接“地”（“地”用于修饰动词）；应说“是纳米级的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
