INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13767, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能源技术是指开发、转换和利用各种能源（如太阳能、风能、核能等）的科学技术方法。", "primary_collocate": null, "pronunciation": "néng yuán jì shù", "ipa": "nɤŋ˧˥ ɥɛn˧˥ tɕi˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "回望历史，从木质风车到纳米级光伏材料，能源技术的演化本质是人类对自然规律认知深度的具象化。", "target_word": "能源技术", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个国家很重视能源技术的研究。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的能源技术让太阳能电池更便宜。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在大学学习能源技术，毕业后想做研究。", "target_word": "能源技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能源技术进步后，风能和核能都能更好地利用。", "target_word": "能源技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每年投入很多钱发展能源技术。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先进的能源技术可以减少环境污染。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写了一篇关于能源技术的报告。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国的能源技术发展得很快。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个论坛讨论各国的能源技术合作。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "新能源技术", "label": "复合"}, {"form": "能源技術", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "开发、转换、利用能源的科学技术方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31173b25-2d4d-4630-a105-47245d8daad4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13767, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能源技术", "is_correct": true, "explanation": "正确。“能源技术”作主语，指开发、转换能源的科学技术，与句中从风车到光伏的演化相合。"}, {"text": "迷信", "is_correct": false, "explanation": "语义：“迷信”指缺乏科学依据的信仰，与“认知深度”的科学内涵相反。"}, {"text": "神话", "is_correct": false, "explanation": "语义：“神话”是虚构的故事，与“自然规律认知”的科学含义矛盾。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这句书面语的语域不合。"}], "explanations": {"能源技术": "正确。“能源技术”作主语，指开发、转换能源的科学技术，与句中从风车到光伏的演化相合。", "迷信": "语义：“迷信”指缺乏科学依据的信仰，与“认知深度”的科学内涵相反。", "神话": "语义：“神话”是虚构的故事，与“自然规律认知”的科学含义矛盾。", "玩意儿": "语域：“玩意儿”是口语说法，与这句书面语的语域不合。"}, "sentence_index": 0, "correct_answer": "能源技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的能源技术很丰富，主要有煤和石油。", "explanation": "这里应该用〈资源〉。能源技术指开发、利用能源的方法，不能用来说储量丰富，应说“资源很丰富”。"}, {"text": "这个工厂每天要消耗大量能源技术。", "explanation": "这里应该用〈电力〉。能源技术是方法，不是可以被消耗的物质，应说“消耗大量电力”。"}, {"text": "这个城市冬天大量烧能源技术取暖。", "explanation": "这里应该用〈煤炭〉。能源技术不是燃料，不能用“烧”来搭配，应说“烧煤炭取暖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13767, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "能源技术", "is_correct": true, "explanation": "正确。“能源技术”作主语，指能减少污染的先进方法，与句意相合。"}, {"text": "污水", "is_correct": false, "explanation": "语义：“污水”本身是污染物，不能减少环境污染。"}, {"text": "废气", "is_correct": false, "explanation": "语义：“废气”是污染物，与“减少环境污染”的句意矛盾。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“先进”多用于技术、设备，不说口味先进。"}], "explanations": {"能源技术": "正确。“能源技术”作主语，指能减少污染的先进方法，与句意相合。", "污水": "语义：“污水”本身是污染物，不能减少环境污染。", "废气": "语义：“废气”是污染物，与“减少环境污染”的句意矛盾。", "口味": "搭配：“先进”多用于技术、设备，不说口味先进。"}, "sentence_index": 6, "correct_answer": "能源技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的能源技术很严重，大家都咳嗽。", "explanation": "这里应该用〈污染〉。能源技术是方法，不能用“严重”形容，应说“污染很严重”。"}, {"text": "这里的能源技术很干燥。", "explanation": "这里应该用〈气候〉。能源技术是方法，不能用“干燥”形容，描述气候才这么说。"}, {"text": "这场能源技术很精彩，大家都鼓掌了。", "explanation": "这里应该用〈比赛〉。能源技术是方法，不是比赛，不能用“精彩”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13767, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们发明了一把新的能源技术。", "corrected_sentence": "他们发明了一项新的能源技术。", "error_description": "量词误用：“能源技术”应搭配量词“项”；“把”用于有柄的器具，不能用于技术，应说“一项新的能源技术”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13767, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们开发了一根先进的能源技术。", "corrected_sentence": "他们开发了一种先进的能源技术。", "error_description": "量词误用：“能源技术”不能用“根”（根多用于细长物体），应该用“种”或“项”，即“一种先进的能源技术”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5992b0d-10da-47f4-a25c-50dcd178afc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
