INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13771, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13771, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "基础科学指研究自然界基本规律和原理的科学，为应用科学提供理论支撑。", "primary_collocate": null, "pronunciation": "jī chǔ kē xué", "ipa": "tɕi˥ ʈʂʰu˨˩˦ kʰɤ˥ ɕɥe˧˥", "syllable_count": 4, "sentences": [{"text": "每一次突破都非孤立发明，而是基础科学、工程实践与社会需求共振的产物。", "target_word": "基础科学", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "基础科学为应用科学提供理论支持。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理和化学都属于基础科学。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家每年投入很多钱支持基础科学。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基础科学不一定马上有用，但很重要。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小喜欢基础科学，后来成了研究员。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有基础科学，就没有新技术。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学里的基础科学课很难，但很有意思。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基础科学的发现要很多年才能用到生活中。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师一辈子都在研究基础科学。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "基础科学研究", "label": "复合"}], "register": "书面语", "sense_fingerprint": "研究自然界基本规律、为应用科学提供理论的学科门类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bb63fc-9d85-45b8-839d-46c1b0107726') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13771, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日常琐事", "is_correct": false, "explanation": "语义：日常琐事与“突破”以及工程实践、社会需求的“共振”不相称，不能作为突破的来源。"}, {"text": "基础科学", "is_correct": true, "explanation": "基础科学指研究自然界基本规律的学科，与工程实践、社会需求并列，句意通顺。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物不是突破的来源，与“工程实践”“社会需求”并列也不成立。"}, {"text": "个人情绪", "is_correct": false, "explanation": "搭配：“共振”一般指需求、思想、力量之间的呼应，不与个人情绪搭配。"}], "explanations": {"日常琐事": "语义：日常琐事与“突破”以及工程实践、社会需求的“共振”不相称，不能作为突破的来源。", "基础科学": "基础科学指研究自然界基本规律的学科，与工程实践、社会需求并列，句意通顺。", "宠物": "语义：宠物不是突破的来源，与“工程实践”“社会需求”并列也不成立。", "个人情绪": "搭配：“共振”一般指需求、思想、力量之间的呼应，不与个人情绪搭配。"}, "sentence_index": 0, "correct_answer": "基础科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂直接把基础科学投入生产线，马上就能赚钱。", "explanation": "这里应该用〈应用科学〉。基础科学重在探索自然的基本规律，不直接用于生产；直接投入生产线的是应用科学。"}, {"text": "他在工地上检查基础科学，确保楼房不会下沉。", "explanation": "这里应该用〈地基〉。基础科学是学科，不是建筑的地基，不能被检查，也不能用来支撑楼房。"}, {"text": "他每天把基础科学放进冰箱，怕它坏掉。", "explanation": "这里应该用〈牛奶〉。基础科学是学科，不是食品，不能放进冰箱防止变质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13771, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小道消息", "is_correct": false, "explanation": "语义：小道消息不能作为新技术的前提，这一句式的因果逻辑不成立。"}, {"text": "基础科学", "is_correct": true, "explanation": "基础科学是新技术的理论前提，放在「没有……就没有……」句式里合乎句意。"}, {"text": "二手货", "is_correct": false, "explanation": "语域：“二手货”是口语说法，且不指向科技前提，放在这句里不协调。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯与新技术没有前提关系，句子的因果逻辑不成立。"}], "explanations": {"小道消息": "语义：小道消息不能作为新技术的前提，这一句式的因果逻辑不成立。", "基础科学": "基础科学是新技术的理论前提，放在「没有……就没有……」句式里合乎句意。", "二手货": "语域：“二手货”是口语说法，且不指向科技前提，放在这句里不协调。", "地毯": "语义：地毯与新技术没有前提关系，句子的因果逻辑不成立。"}, "sentence_index": 6, "correct_answer": "基础科学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师是一位著名的基础科学。", "explanation": "这里应该用〈科学家〉。基础科学指学科领域，不指人，不能用“一位”来称呼老师。"}, {"text": "这位老师每天都在打扫基础科学，很辛苦。", "explanation": "这里应该用〈教室〉。“打扫”针对教室、地面等具体的空间，基础科学是学科，不能被打扫。"}, {"text": "这位老师一辈子都在写基础科学。", "explanation": "这里应该用〈论文〉。“写”的对象是论文、文章，基础科学是学科，不能被“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学了一只基础科学。", "corrected_sentence": "我们学了一门基础科学。", "error_description": "量词错误：学科名词“基础科学”应用“门”计量，不能用“只”（“只”多用于动物或成对的东西）。正确说法：我们学了一门基础科学。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很喜欢基础科学们。", "corrected_sentence": "我很喜欢基础科学。", "error_description": "词尾错误：“们”只用于指人的名词之后，“基础科学”是学科名，不能加“们”。正确说法：我很喜欢基础科学。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13772, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
