INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13773, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由多种因素共同作用形成的结果或成果", "primary_collocate": null, "pronunciation": "chǎn wù", "ipa": "tʂʰan˨˩˦ u˥˩", "syllable_count": 2, "sentences": [{"text": "每一次突破都非孤立发明，而是基础科学、工程实践与社会需求共振的产物。", "target_word": "产物", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种文化是历史发展的产物。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法是长期试验的产物。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络语言是新时代的产物。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项技术是多方合作的产物。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌是他多年生活的产物。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成功往往是努力和运气共同作用的产物。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市是自然和人类共同努力的产物。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题是社会变化的产物。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代城市是工业发展的产物。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "產物", "label": "繁体"}], "register": "书面", "sense_fingerprint": "多种因素共同作用形成的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e92c63b-3679-442a-a17d-628878172573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13773, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产物", "is_correct": true, "explanation": "产物：多种因素共同作用形成的结果，与“突破是基础科学、工程实践与社会需求共振的结果”相符。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是由科学与社会需求共振形成的，句意说不通。"}, {"text": "原料", "is_correct": false, "explanation": "语义：原料是投入的东西，句中“突破”是共振形成的结果，“原料”与之相反。"}, {"text": "工具", "is_correct": false, "explanation": "搭配：“共振”一般修饰抽象成果，不说“共振的工具”。"}], "explanations": {"产物": "产物：多种因素共同作用形成的结果，与“突破是基础科学、工程实践与社会需求共振的结果”相符。", "玩具": "语义：玩具不是由科学与社会需求共振形成的，句意说不通。", "原料": "语义：原料是投入的东西，句中“突破”是共振形成的结果，“原料”与之相反。", "工具": "搭配：“共振”一般修饰抽象成果，不说“共振的工具”。"}, "sentence_index": 0, "correct_answer": "产物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项研究终于取得了重大产物。", "explanation": "这里应该用〈成果〉。产物指多种因素共同作用形成的结果，取得的成就一般说〈成果〉。"}, {"text": "这部小说的产物让很多读者大受感动。", "explanation": "这里应该用〈作品〉。“产物”指多种因素作用后形成的结果，小说这类文艺创作要说〈作品〉，“小说的产物”搭配不通。"}, {"text": "这家工厂推出了一款新产物。", "explanation": "这里应该用〈产品〉。工厂生产、用于销售的东西要说〈产品〉，“产物”指多种因素作用后形成的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13773, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产物", "is_correct": true, "explanation": "产物：共同作用形成的结果，与“成功是努力和运气共同作用的结果”相符。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器不是由努力和运气共同作用形成的，句意说不通。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：“共同作用”后接的应是形成的结果，不说“共同作用的地图”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱与成功无关，“共同作用的冰箱”说不通。"}], "explanations": {"产物": "产物：共同作用形成的结果，与“成功是努力和运气共同作用的结果”相符。", "乐器": "语义：乐器不是由努力和运气共同作用形成的，句意说不通。", "地图": "搭配：“共同作用”后接的应是形成的结果，不说“共同作用的地图”。", "冰箱": "语义：冰箱与成功无关，“共同作用的冰箱”说不通。"}, "sentence_index": 6, "correct_answer": "产物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种现象是社会发展的一只产物。", "explanation": "量词“只”用错了：“只”多用于动物或成对的物件，不能用来数“产物”这种抽象结果，这里应该用〈个〉。"}, {"text": "这笔投资带来了丰厚的产物。", "explanation": "这里应该用〈利润〉。“产物”指多种因素共同作用形成的结果或成果，投资赚到的钱要说〈利润〉。"}, {"text": "这家超市每天卖出很多产物，货架很快就空了。", "explanation": "这里应该用〈商品〉。“产物”指多种因素作用形成的结果，超市卖的东西要说〈商品〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是城市发展的一只产物。", "corrected_sentence": "这是城市发展的一种产物。", "error_description": "量词错误：“产物”前应用“种”，不用“只”（“只”多用于动物或成对的物件）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种风格是多年探索产物。", "corrected_sentence": "这种风格是多年探索的产物。", "error_description": "漏掉定语标记“的”：“多年探索”是动词短语，修饰“产物”时要加“的”，应说“多年探索的产物”，不能直接说“多年探索产物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13774, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13774, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13774, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "幕墙是建筑外围护结构，通常由玻璃、金属板等材料组成，不承受主体结构荷载，具有装饰和防护功能。", "primary_collocate": null, "pronunciation": "mù qiáng", "ipa": "mu˥˩ tɕʰjaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "未来能源图景或将超越“发电”本身——建筑幕墙成为透明太阳能收集器，道路涂层集成压电发电单元，甚至人工光合作用系统直接将二氧化碳转化为燃料。", "target_word": "幕墙", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这栋楼的幕墙全是玻璃做的。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幕墙挂在大楼外面，像一件衣服。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在给高楼安装幕墙。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幕墙不能支撑大楼，只能保护它。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，幕墙上的玻璃碎了。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，幕墙上的灯光特别漂亮。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属板做的幕墙很结实。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天爬上高楼，清洗幕墙。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座新楼的幕墙把阳光都挡在了外面。", "target_word": "幕墙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "玻璃幕墙", "label": "复合"}, {"form": "幕牆", "label": "繁体"}, {"form": "面", "label": "量词"}], "register": "书面语", "sense_fingerprint": "建筑外围护结构，不承重，由玻璃或金属板组成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bb63fc-9d85-45b8-839d-46c1b0107726') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烤箱", "is_correct": false, "explanation": "语义：烤箱是厨房电器，不是建筑外围护结构，不能作“建筑”的组成部分。"}, {"text": "幕墙", "is_correct": true, "explanation": "幕墙指建筑外围护结构，“建筑幕墙”作主语，成为透明太阳能收集器，合乎语境。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物不是建筑构件，不能成为透明太阳能收集器。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干与“建筑”无关，不能作透明太阳能收集器的载体。"}], "explanations": {"烤箱": "语义：烤箱是厨房电器，不是建筑外围护结构，不能作“建筑”的组成部分。", "幕墙": "幕墙指建筑外围护结构，“建筑幕墙”作主语，成为透明太阳能收集器，合乎语境。", "宠物": "语义：宠物不是建筑构件，不能成为透明太阳能收集器。", "饼干": "语义：饼干与“建筑”无关，不能作透明太阳能收集器的载体。"}, "sentence_index": 0, "correct_answer": "幕墙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他推开幕墙走了进去。", "explanation": "这里应该用〈门〉。幕墙是固定在外墙上的构件，不能推开，也不能从中走进去。"}, {"text": "演出开始前，幕墙慢慢拉开了。", "explanation": "这里应该用〈幕布〉。幕墙是固定在建筑外面的墙，不能拉开；舞台上拉开的是幕布。"}, {"text": "工人正在给高楼安装一只幕墙。", "explanation": "这里应该用〈面〉。幕墙按面计量，说“一只”是量词错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不是可以发光的表面，不能说“课本上的灯光”。"}, {"text": "幕墙", "is_correct": true, "explanation": "“幕墙上”指建筑外墙的表面，句中说灯光照在其上，合乎句意。"}, {"text": "信纸", "is_correct": false, "explanation": "语义：信纸是纸张，没有灯光，也不是大面积的发光表面，句意不通。"}, {"text": "二手货", "is_correct": false, "explanation": "语域：“二手货”是口语说法，且指旧物，与这句描写夜景的语境不符。"}], "explanations": {"课本": "语义：课本是书，不是可以发光的表面，不能说“课本上的灯光”。", "幕墙": "“幕墙上”指建筑外墙的表面，句中说灯光照在其上，合乎句意。", "信纸": "语义：信纸是纸张，没有灯光，也不是大面积的发光表面，句意不通。", "二手货": "语域：“二手货”是口语说法，且指旧物，与这句描写夜景的语境不符。"}, "sentence_index": 6, "correct_answer": "幕墙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "卧室的幕墙把阳光都挡在了外面。", "explanation": "这里应该用〈窗帘〉。幕墙是建筑外围护结构，不是室内的遮挡物，不能说“卧室的幕墙”。"}, {"text": "他撑着幕墙走出门。", "explanation": "这里应该用〈遮阳伞〉。幕墙固定在建筑外面，不能撑着走。"}, {"text": "他把幕墙拿到厨房切菜。", "explanation": "这里应该用〈砧板〉。幕墙是建筑构件，不能拿来切菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "幕墙已经装了好。", "corrected_sentence": "幕墙已经装好了。", "error_description": "补语位置错误：“装好”是动补结构，“了”应放在补语之后，说“装好了”，不能说“装了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚上，一只幕墙亮着很多灯。", "corrected_sentence": "晚上，一面幕墙亮着很多灯。", "error_description": "量词错误：“幕墙”按面计量，应说“一面幕墙”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13775, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不透明", "is_correct": true, "explanation": "与“透明”互为反义，指光线不能穿过、看不清后面。"}, {"text": "粗糙", "is_correct": false, "explanation": "无关：“粗糙”形容表面质地，与“透明”的光学性质不构成反义。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：“柔软”形容触感，与“透明”不构成反义。"}, {"text": "坚硬", "is_correct": false, "explanation": "无关：“坚硬”形容硬度，与“透明”不构成反义。"}], "correct_answer": "不透明", "explanations": {"不透明": "与“透明”互为反义，指光线不能穿过、看不清后面。", "粗糙": "无关：“粗糙”形容表面质地，与“透明”的光学性质不构成反义。", "柔软": "无关：“柔软”形容触感，与“透明”不构成反义。", "坚硬": "无关：“坚硬”形容硬度，与“透明”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13775, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不透明", "is_correct": true, "explanation": "与“透明”互为反义，指光线不能穿过。"}, {"text": "冰凉", "is_correct": false, "explanation": "无关：“冰凉”形容温度感受，与“透明”不构成反义。"}, {"text": "宽阔", "is_correct": false, "explanation": "无关：“宽阔”形容面积或空间，与“透明”不构成反义。"}, {"text": "柔和", "is_correct": false, "explanation": "无关：“柔和”形容光线或语气的温和，与“透明”不构成反义。"}], "correct_answer": "不透明", "explanations": {"不透明": "与“透明”互为反义，指光线不能穿过。", "冰凉": "无关：“冰凉”形容温度感受，与“透明”不构成反义。", "宽阔": "无关：“宽阔”形容面积或空间，与“透明”不构成反义。", "柔和": "无关：“柔和”形容光线或语气的温和，与“透明”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13775, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能让光线穿过，看清楚后面的东西", "primary_collocate": null, "pronunciation": "tòu míng", "ipa": "tʰou̯˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "未来能源图景或将超越“发电”本身——建筑幕墙成为透明太阳能收集器，道路涂层集成压电发电单元，甚至人工光合作用系统直接将二氧化碳转化为燃料。", "target_word": "透明", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个杯子是透明的，能看见里面的水。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "透明的玻璃门后面站着一个人。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水很干净，几乎是透明的。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用透明的塑料袋装了午饭。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户的玻璃很透明，擦得干干净净。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种膜又薄又透明，像空气一样。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水非常透明，能看见水底的石头。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这张透明的纸放在地图上。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水母的身体几乎是透明的。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "半透明", "label": "复合"}, {"form": "透明度", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体能让光线穿过、可看清其后事物（物理性质）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bb63fc-9d85-45b8-839d-46c1b0107726') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13775, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "透明", "is_correct": true, "explanation": "“建筑幕墙”要让光线穿过才能收集太阳能，这里只能用“透明”。"}, {"text": "不透明", "is_correct": false, "explanation": "语义：幕墙不透光就无法收集太阳能，与“能源图景”的设想相悖。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”多用于水、天空等，不用来形容幕墙或太阳能装置。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”与前文“未来能源图景”的超前构想矛盾。"}], "explanations": {"透明": "“建筑幕墙”要让光线穿过才能收集太阳能，这里只能用“透明”。", "不透明": "语义：幕墙不透光就无法收集太阳能，与“能源图景”的设想相悖。", "清澈": "搭配：“清澈”多用于水、天空等，不用来形容幕墙或太阳能装置。", "陈旧": "语义：“陈旧”与前文“未来能源图景”的超前构想矛盾。"}, "sentence_index": 0, "correct_answer": "透明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张照片拍得很透明。", "explanation": "这里应该用〈清楚〉。“透明”指物体能让光穿过、看清后面，不用来说照片清不清楚。"}, {"text": "这堵墙很透明，后面的人全都看不见。", "explanation": "这里应该用〈厚〉。透明的东西能让光线穿过、看清后面，句中却说看不见，应该用〈厚〉。"}, {"text": "她的袜子很透明，把脚挡得严严实实。", "explanation": "这里应该用〈厚〉。透明的东西让光线穿过，挡不住脚；把脚挡严要用厚的袜子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13775, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透明", "is_correct": true, "explanation": "“又薄又”后接表示光学性质的形容词，“透明”与“像空气一样”相合。"}, {"text": "厚", "is_correct": false, "explanation": "语义：与前文“又薄”直接矛盾。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“像空气一样”说明很轻，“沉重”与之相悖。"}, {"text": "粗糙", "is_correct": false, "explanation": "体貌：“粗糙”说表面质地，与“像空气一样”的轻薄外观不合。"}], "explanations": {"透明": "“又薄又”后接表示光学性质的形容词，“透明”与“像空气一样”相合。", "厚": "语义：与前文“又薄”直接矛盾。", "沉重": "语义：“像空气一样”说明很轻，“沉重”与之相悖。", "粗糙": "体貌：“粗糙”说表面质地，与“像空气一样”的轻薄外观不合。"}, "sentence_index": 6, "correct_answer": "透明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜空中的星星很透明。", "explanation": "这里应该用〈闪亮〉。“闪亮”说光的闪耀，“透明”说物体能让光穿过，不用来形容星星。"}, {"text": "这块木板很透明，把后面的东西全挡住了。", "explanation": "这里应该用〈厚〉。透明的东西能让光线穿过、看清后面，挡住后面的东西应该用〈厚〉。"}, {"text": "这个苹果很透明。", "explanation": "这里应该用〈清脆〉。“清脆”形容苹果咬起来的声音和口感，“透明”不用来形容苹果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13775, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块玻璃很很透明。", "corrected_sentence": "这块玻璃很透明。", "error_description": "重复错误：程度副词“很”只用一个，应说“这块玻璃很透明”，不能说“很很透明”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13775, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块冰是透明。", "corrected_sentence": "这块冰是透明的。", "error_description": "漏掉“的”：“是”字句中形容词作谓语时通常要带“的”，应说“是透明的”，不说“是透明”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
