INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13777, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "涂层是指为保护、装饰或实现特定功能而涂覆在物体表面的薄层材料。", "primary_collocate": null, "pronunciation": "tú céng", "ipa": "tʰu˧˥ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "未来能源图景或将超越“发电”本身——建筑幕墙成为透明太阳能收集器，道路涂层集成压电发电单元，甚至人工光合作用系统直接将二氧化碳转化为燃料。", "target_word": "涂层", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这辆车的表面有一层特殊的涂层。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅里的涂层掉了，不能再用了。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人给钢铁桥涂上了防锈涂层。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种涂层能防水，也能防火。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕上有一层保护涂层。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "涂层太薄，保护作用不好。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用小刀刮掉了墙上旧的涂层。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新涂层干了以后，颜色很漂亮。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种涂层的价格不便宜。", "target_word": "涂层", "complexity_tier": "T3", "furigana": "zhè zhǒng tú céng de jià gé bù pián yi", "sentence_source": "generated"}], "morphological_forms": [{"form": "层", "label": "量词"}, {"form": "防锈涂层", "label": "复合"}, {"form": "塗層", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为保护或装饰而涂在物体表面的薄层材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e92c63b-3679-442a-a17d-628878172573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13777, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "涂层", "is_correct": true, "explanation": "正确：道路表面的薄层材料可以集成压电发电单元，与前文“建筑幕墙”的并列结构相符。"}, {"text": "幕墙", "is_correct": false, "explanation": "语义：幕墙是建筑的外立面，道路上不用幕墙，句中“道路”与之不符。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯铺在室内地面，不能用于道路，也无法集成发电单元。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“道路”不与“窗帘”组合，道路上需要的是路面材料。"}], "explanations": {"涂层": "正确：道路表面的薄层材料可以集成压电发电单元，与前文“建筑幕墙”的并列结构相符。", "幕墙": "语义：幕墙是建筑的外立面，道路上不用幕墙，句中“道路”与之不符。", "地毯": "语义：地毯铺在室内地面，不能用于道路，也无法集成发电单元。", "窗帘": "搭配：“道路”不与“窗帘”组合，道路上需要的是路面材料。"}, "sentence_index": 0, "correct_answer": "涂层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去超市买了一桶涂层。", "explanation": "这里应该用〈涂料〉。涂料是涂之前的液体，涂层是涂好后附着在表面的一层，不能按桶来买。"}, {"text": "这颗鸡蛋的涂层很脆。", "explanation": "这里应该用〈外壳〉。鸡蛋的硬壳是天生的，不是人工涂上去的，不说涂层。"}, {"text": "我买了一只涂层。", "explanation": "这里应该用〈层〉。涂层是薄薄的一层，量词用“层”，不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13777, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "涂层", "is_correct": true, "explanation": "正确：薄层材料本身太薄，就会影响保护作用，与后半句相符。"}, {"text": "色彩", "is_correct": false, "explanation": "语义：色彩不具有保护作用，句中的“保护作用不好”无法由它来说明。"}, {"text": "外观", "is_correct": false, "explanation": "搭配：“外观”不说厚薄，“外观太薄”搭配不当。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道与保护作用无关，句子的因果关系不成立。"}], "explanations": {"涂层": "正确：薄层材料本身太薄，就会影响保护作用，与后半句相符。", "色彩": "语义：色彩不具有保护作用，句中的“保护作用不好”无法由它来说明。", "外观": "搭配：“外观”不说厚薄，“外观太薄”搭配不当。", "味道": "语义：味道与保护作用无关，句子的因果关系不成立。"}, "sentence_index": 6, "correct_answer": "涂层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个礼物的涂层很漂亮。", "explanation": "这里应该用〈包装〉。涂层是涂在物体表面的薄层，礼物外面包着的纸或盒子不叫涂层。"}, {"text": "他的涂层很干燥，一直在脱皮。", "explanation": "这里应该用〈皮肤〉。涂层是人工涂覆的材料，不指人身上的皮肤。"}, {"text": "他脱下了涂层。", "explanation": "这里应该用〈外衣〉。涂层是附着在表面的薄层，不能当作衣服脱下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13777, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块木板上刷了一只新涂层。", "corrected_sentence": "这块木板上刷了一层新涂层。", "error_description": "量词用错：“只”用于动物或单个器物，涂层是一层一层涂上去的，应说“一层新涂层”，不说“一只新涂层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13777, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙上的涂层没厚。", "corrected_sentence": "墙上的涂层不厚。", "error_description": "否定词用错：形容词前应用“不”，不用“没”，应说“不厚”，不能说“没厚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
