INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13780, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "植物利用光能，把二氧化碳和水变成有机物，同时放出氧气的过程。", "primary_collocate": null, "pronunciation": "guāng hé zuò yòng", "ipa": "kwaŋ˥ xɤ˧˥ tswo˥˩ jʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "未来能源图景或将超越“发电”本身——建筑幕墙成为透明太阳能收集器，道路涂层集成压电发电单元，甚至人工光合作用系统直接将二氧化碳转化为燃料。", "target_word": "光合作用", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "植物靠光合作用制造养分。", "target_word": "光合作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光合作用需要阳光、水和二氧化碳。", "target_word": "光合作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "叶子是植物进行光合作用的地方。", "target_word": "光合作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光合作用会放出氧气。", "target_word": "光合作用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "晚上没有阳光，植物不能进行光合作用。", "target_word": "光合作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了光合作用的过程。", "target_word": "光合作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有光合作用，地球上就不会有氧气。", "target_word": "光合作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海里的小藻类也能进行光合作用。", "target_word": "光合作用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光合作用把二氧化碳和水变成养分。", "target_word": "光合作用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "光合作用：植物利用光能把二氧化碳和水变成有机物并放出氧气的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bb63fc-9d85-45b8-839d-46c1b0107726') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13780, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "光合作用", "is_correct": true, "explanation": "光合作用是植物把二氧化碳和水变成养分的过程，人工光合作用系统可以把二氧化碳转化为燃料，与句意相符。"}, {"text": "核聚变", "is_correct": false, "explanation": "语义：核聚变是原子核的反应，不能把二氧化碳转化为燃料。"}, {"text": "电池", "is_correct": false, "explanation": "语义：电池是储存电能的装置，不能直接把二氧化碳转化为燃料。"}, {"text": "发动机", "is_correct": false, "explanation": "语义：发动机是把燃料转化为动力的装置，不能把二氧化碳转化为燃料。"}], "explanations": {"光合作用": "光合作用是植物把二氧化碳和水变成养分的过程，人工光合作用系统可以把二氧化碳转化为燃料，与句意相符。", "核聚变": "语义：核聚变是原子核的反应，不能把二氧化碳转化为燃料。", "电池": "语义：电池是储存电能的装置，不能直接把二氧化碳转化为燃料。", "发动机": "语义：发动机是把燃料转化为动力的装置，不能把二氧化碳转化为燃料。"}, "sentence_index": 0, "correct_answer": "光合作用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "植物靠光合作用消耗养分。", "explanation": "这里应该用〈呼吸作用〉。光合作用是制造有机物、放出氧气的过程，消耗养分要用呼吸作用。"}, {"text": "光合作用让水分从叶子散发出去。", "explanation": "这里应该用〈蒸腾作用〉。光合作用是制造有机物的过程，水分从叶子散发出去要用蒸腾作用。"}, {"text": "酵母靠光合作用产生酒精。", "explanation": "这里应该用〈发酵〉。酒精靠酵母的发酵产生，光合作用是植物利用光能制造有机物的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光合作用", "is_correct": true, "explanation": "老师讲的是光合作用的过程，与句意相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地点，不是可以讲述的过程，“讲了厨房的过程”说不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是过程，“讲了时间的过程”说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“讲”的宾语应是可讲述的内容，“桌子”是具体物体，不能被讲。"}], "explanations": {"光合作用": "老师讲的是光合作用的过程，与句意相符。", "厨房": "语义：厨房是地点，不是可以讲述的过程，“讲了厨房的过程”说不通。", "时间": "语义：时间不是过程，“讲了时间的过程”说不通。", "桌子": "配价：“讲”的宾语应是可讲述的内容，“桌子”是具体物体，不能被讲。"}, "sentence_index": 6, "correct_answer": "光合作用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "食物在胃里经过光合作用变成养分。", "explanation": "这里应该用〈消化〉。食物在胃里分解成养分叫消化；光合作用是植物利用光能制造有机物的过程。"}, {"text": "孩子每天光合作用长高。", "explanation": "这里应该用〈发育〉。人体长身体、逐步成熟叫发育；光合作用是植物制造有机物的过程，不能指人长高。"}, {"text": "植物通过光合作用产生后代。", "explanation": "这里应该用〈繁殖〉。生物产生后代的过程叫繁殖；光合作用是植物制造有机物、放出氧气的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天，植物的光合作用进行的很快。", "corrected_sentence": "夏天，植物的光合作用进行得很快。", "error_description": "表示动作程度的补语前要用“得”，不能用“的”；应为“进行得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天黑以后，植物不进行了光合作用。", "corrected_sentence": "天黑以后，植物不进行光合作用。", "error_description": "否定句中“不”后不能加“了”，“不进行了光合作用”不成立，应为“不进行光合作用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
