INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13782, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指完成建造，例如房子、桥梁等建筑物或设施已经完工。", "primary_collocate": null, "pronunciation": "jiàn chéng", "ipa": "tɕjɛn˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这些前沿探索预示着：清洁能源的终极形态，或是将整个建成环境转化为无感而持续的能量代谢网络。", "target_word": "建成", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这座桥去年已经建成了。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新学校明年夏天就能建成。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条高速公路用了三年才建成。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座塔建成以后，成了城市的标志。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的小房子终于建成了。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "体育馆还没有建成，比赛要等一等。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个公园建成后，很多人来玩。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的图书馆是十年前建成的。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一座新机场在海边建成了。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "建成了", "label": "完成体"}], "register": "书面", "sense_fingerprint": "建成·动词·建筑物或设施完工", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '385e789d-21ea-49b5-b03e-4cf712cdbae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13782, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "建成", "is_correct": true, "explanation": "建成 jiàn chéng：指建筑物或设施完工，是正确答案。"}, {"text": "坚称", "is_correct": false, "explanation": "jiānchēng 与 jiàn chéng 的首字声调不同（第一声与第四声），意思是坚称（坚决地说）。"}, {"text": "简称", "is_correct": false, "explanation": "jiǎnchēng 与 jiàn chéng 的首字声调不同（第三声与第四声），意思是简称（简略的名称）。"}, {"text": "现成", "is_correct": false, "explanation": "xiànchéng 与 jiànchéng 的声母不同（x 与 j），意思是现成（现有的、不用加工的）。"}], "explanations": {"建成": "建成 jiàn chéng：指建筑物或设施完工，是正确答案。", "坚称": "jiānchēng 与 jiàn chéng 的首字声调不同（第一声与第四声），意思是坚称（坚决地说）。", "简称": "jiǎnchēng 与 jiàn chéng 的首字声调不同（第三声与第四声），意思是简称（简略的名称）。", "现成": "xiànchéng 与 jiànchéng 的声母不同（x 与 j），意思是现成（现有的、不用加工的）。"}, "sentence_index": null, "correct_answer": "建成"}, "level_3": {"options": [{"text": "建成", "is_correct": true, "explanation": "建成：修饰“环境”，指已建成的人工环境，符合句意。"}, {"text": "语言", "is_correct": false, "explanation": "搭配：“语言环境”指语言使用的场景，与清洁能源转化为能量网络的语境不符。"}, {"text": "孤独", "is_correct": false, "explanation": "搭配：“孤独”多形容人的心情，不修饰“环境”。"}, {"text": "自由", "is_correct": false, "explanation": "搭配：“自由”修饰“环境”不自然，且与句中的建设义无关。"}], "explanations": {"建成": "建成：修饰“环境”，指已建成的人工环境，符合句意。", "语言": "搭配：“语言环境”指语言使用的场景，与清洁能源转化为能量网络的语境不符。", "孤独": "搭配：“孤独”多形容人的心情，不修饰“环境”。", "自由": "搭配：“自由”修饰“环境”不自然，且与句中的建设义无关。"}, "sentence_index": 0, "correct_answer": "建成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用了三年才建成这部书。", "explanation": "这里应该用〈完成〉。建成只用于房屋、桥梁、设施等建筑物，不用于书。"}, {"text": "这台电脑终于建成了。", "explanation": "这里应该用〈修好〉。建成指建筑物或设施完工，电脑是修好的，不说建成。"}, {"text": "他终于建成了一个好习惯。", "explanation": "这里应该用〈养成〉。建成用于建筑物或设施的完工，不用于习惯；习惯要说〈养成〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建成", "is_correct": true, "explanation": "建成：指体育馆完工，与“比赛要等一等”的语境相符。"}, {"text": "开学", "is_correct": false, "explanation": "搭配：“开学”只用于学校，不用于体育馆。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”需要人作施事，体育馆不能作“参观”的主语。"}, {"text": "倒塌", "is_correct": false, "explanation": "语义：体育馆“倒塌”与“比赛要等一等”的因果关系不通。"}], "explanations": {"建成": "建成：指体育馆完工，与“比赛要等一等”的语境相符。", "开学": "搭配：“开学”只用于学校，不用于体育馆。", "参观": "配价：“参观”需要人作施事，体育馆不能作“参观”的主语。", "倒塌": "语义：体育馆“倒塌”与“比赛要等一等”的因果关系不通。"}, "sentence_index": 6, "correct_answer": "建成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台空调终于建成了。", "explanation": "这里应该用〈装好〉。建成用于建筑物或设施，空调是安装好的，不说建成。"}, {"text": "他终于建成了那篇论文。", "explanation": "这里应该用〈写完〉。建成不用于文章，写完论文要说〈写完〉。"}, {"text": "这辆车是去年建成的。", "explanation": "这里应该用〈造好〉。建成指建筑物或设施完工，车辆是制造出来的，不说建成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座新馆下个月就建成着。", "corrected_sentence": "这座新馆下个月就建成了。", "error_description": "错误在于动态助词：表示“建成”这一完工结果要用“了”，用“着”表示持续状态，与句意不符。应把“着”改为“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这栋楼明年才会建成了。", "corrected_sentence": "这栋楼明年才会建成。", "error_description": "错误在于多加了“了”：“明年”指将来，“才会”表示尚未发生，“建成”的完成不能用“了”表示。应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
