INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13783, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指没有感觉或不在意，对某事物不产生情绪或身体上的反应。", "primary_collocate": null, "pronunciation": "wú gǎn", "ipa": "u˧˥ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "他对周围的一切都无感，好像什么也没听见。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这部电影很无感，看到一半就睡着了。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都爱吃辣，可我对辣味无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对流行音乐一直很无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了半天，我对这个笑话完全无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的年轻人对广告越来越无感了。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对名牌包包无感，从来不买。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于别人的评价，他似乎无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛太无聊，我看着也无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了很多遍，学生们还是无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "对事物没有感觉、不在意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e92c63b-3679-442a-a17d-628878172573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13783, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无感", "is_correct": true, "explanation": "正确：wú gǎn，意思是没有感觉或不在意。"}, {"text": "五感", "is_correct": false, "explanation": "wǔ gǎn（第三声）与 wú gǎn（第二声）声调不同，意思是五种感觉。"}, {"text": "武干", "is_correct": false, "explanation": "声调：wǔ gàn 与 wú gǎn 只是声调不同，意思是武艺与才干。"}, {"text": "无干", "is_correct": false, "explanation": "gān（第一声）与 gǎn（第三声）声调不同，意思是没有关系。"}], "explanations": {"无感": "正确：wú gǎn，意思是没有感觉或不在意。", "五感": "wǔ gǎn（第三声）与 wú gǎn（第二声）声调不同，意思是五种感觉。", "武干": "声调：wǔ gàn 与 wú gǎn 只是声调不同，意思是武艺与才干。", "无干": "gān（第一声）与 gǎn（第三声）声调不同，意思是没有关系。"}, "sentence_index": null, "correct_answer": "无感"}, "level_3": {"options": [{"text": "无感", "is_correct": true, "explanation": "正确：对周围的一切都没有反应，正合“好像什么也没听见”的意思。"}, {"text": "显眼", "is_correct": false, "explanation": "语义：“显眼”指引人注意，与“什么也没听见”的麻木状态相反。"}, {"text": "喧闹", "is_correct": false, "explanation": "搭配：“喧闹”形容声音或场面，不用来形容人对周围一切的态度。"}, {"text": "笨重", "is_correct": false, "explanation": "语义：“笨重”形容体积或动作，与人的感受无关，“对一切都笨重”说不通。"}], "explanations": {"无感": "正确：对周围的一切都没有反应，正合“好像什么也没听见”的意思。", "显眼": "语义：“显眼”指引人注意，与“什么也没听见”的麻木状态相反。", "喧闹": "搭配：“喧闹”形容声音或场面，不用来形容人对周围一切的态度。", "笨重": "语义：“笨重”形容体积或动作，与人的感受无关，“对一切都笨重”说不通。"}, "sentence_index": 0, "correct_answer": "无感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我被他的故事感动得哭了起来，对此完全无感。", "explanation": "这里应该用〈感动〉。无感表示没有情绪反应，与“感动得哭了起来”矛盾，应该用“感动”。"}, {"text": "比赛获胜后，我激动得跳了起来，对此完全无感。", "explanation": "这里应该用〈激动〉。无感表示没有情绪反应，与“激动得跳了起来”矛盾，应该用“激动”。"}, {"text": "他对身边的朋友很无感，每天都热情地关心大家。", "explanation": "这里应该用〈在意〉。无感表示不在意，与“每天都热情地关心大家”矛盾，应该用“在意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13783, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无感", "is_correct": true, "explanation": "正确：对名牌包包没有兴趣，与“从来不买”前后一致。"}, {"text": "狂热", "is_correct": false, "explanation": "语义：狂热的人往往想买，与“从来不买”相矛盾。"}, {"text": "痴迷", "is_correct": false, "explanation": "语义：痴迷多指一心想拥有，与“从来不买”前后矛盾。"}, {"text": "热切", "is_correct": false, "explanation": "搭配：“热切”多用于期盼、眼神，不说“对包包热切”。"}], "explanations": {"无感": "正确：对名牌包包没有兴趣，与“从来不买”前后一致。", "狂热": "语义：狂热的人往往想买，与“从来不买”相矛盾。", "痴迷": "语义：痴迷多指一心想拥有，与“从来不买”前后矛盾。", "热切": "搭配：“热切”多用于期盼、眼神，不说“对包包热切”。"}, "sentence_index": 6, "correct_answer": "无感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每次见到妈妈，我都很无感，一头扑进她怀里撒娇。", "explanation": "这里应该用〈亲近〉。无感表示不在意、没有反应，与“一头扑进她怀里撒娇”的亲昵反应矛盾，应该用“亲近”。"}, {"text": "得知考试通过，他高兴得大笑起来，对此很无感。", "explanation": "这里应该用〈高兴〉。无感表示没有情绪反应，与“高兴得大笑起来”矛盾，应该用“高兴”。"}, {"text": "这场演唱会我全程都很无感，一直跟着歌声尖叫。", "explanation": "这里应该用〈投入〉。无感表示不在意，与“一直跟着歌声尖叫”矛盾，应该用“投入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13783, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我跟这场比赛一直很无感，没看进去。", "corrected_sentence": "我对这场比赛一直很无感，没看进去。", "error_description": "介词用错：“无感”的对象要用介词“对”，不能说“跟这场比赛”，应说“对这场比赛一直很无感”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13783, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈对手机游戏很完全无感，从来不玩。", "corrected_sentence": "妈妈对手机游戏完全无感，从来不玩。", "error_description": "副词叠用：“很”和“完全”都修饰“无感”，不能同时使用，应说“对手机游戏完全无感”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
