INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13784, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "系统持续转换和传输能量的过程，如同生物的新陈代谢。", "primary_collocate": null, "pronunciation": "néng liàng dài xiè", "ipa": "nɤŋ˧˥ ljɑŋ˥˩ taɪ˥˩ ɕjɛ˥˩", "syllable_count": 4, "sentences": [{"text": "这些前沿探索预示着：清洁能源的终极形态，或是将整个建成环境转化为无感而持续的能量代谢网络。", "target_word": "能量代谢", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这套系统的能量代谢效率很高。", "target_word": "能量代谢", "complexity_tier": "T3", "furigana": "néng liàng dài xiè", "sentence_source": "generated"}, {"text": "这个能源系统依靠能量代谢持续运转。", "target_word": "能量代谢", "complexity_tier": "T3", "furigana": "néng liàng dài xiè", "sentence_source": "generated"}, {"text": "科学家研究城市的能量代谢，希望少用电。", "target_word": "能量代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系统的能量代谢决定了运行成本。", "target_word": "能量代谢", "complexity_tier": "T3", "furigana": "néng liàng dài xiè", "sentence_source": "generated"}, {"text": "这个小区的能量代谢网络已经建好了。", "target_word": "能量代谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在研究大楼的能量代谢。", "target_word": "能量代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳能让这个村子的能量代谢更稳定。", "target_word": "能量代谢", "complexity_tier": "T3", "furigana": "néng liàng dài xiè", "sentence_source": "generated"}, {"text": "老师说，城市也有自己的能量代谢。", "target_word": "能量代谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "能量代谢不好，整个系统就会变慢。", "target_word": "能量代谢", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "能量代谢·名词·系统转换传输能量的过程(比喻)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '385e789d-21ea-49b5-b03e-4cf712cdbae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "语言", "is_correct": false, "explanation": "语义：句中讲的是清洁能源的转化与传输，“语言网络”与能源系统无关。"}, {"text": "能量代谢", "is_correct": true, "explanation": "能量代谢：指系统持续转换和传输能量的过程，与“无感而持续”和“网络”的语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”与“网络”不构成搭配，句中“网络”指的是能源转换网络。"}, {"text": "时尚", "is_correct": false, "explanation": "语义：时尚没有能量转换的含义，“时尚网络”无法描述清洁能源与建成环境的关系。"}], "explanations": {"语言": "语义：句中讲的是清洁能源的转化与传输，“语言网络”与能源系统无关。", "能量代谢": "能量代谢：指系统持续转换和传输能量的过程，与“无感而持续”和“网络”的语境相符。", "颜色": "搭配：“颜色”与“网络”不构成搭配，句中“网络”指的是能源转换网络。", "时尚": "语义：时尚没有能量转换的含义，“时尚网络”无法描述清洁能源与建成环境的关系。"}, "sentence_index": 0, "correct_answer": "能量代谢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "能量代谢是指能量既不会凭空产生，也不会凭空消失。", "explanation": "这里应该用〈能量守恒〉。能量守恒强调能量总量不变，能量代谢指系统持续转换和传输能量的过程，二者不能互换。"}, {"text": "这块太阳能电池板能把光转换成能量代谢。", "explanation": "这里应该用〈电能〉。光转换成的是电能，能量代谢指系统转换和传输能量的过程，本身不是可以产生出来的能量形式，不能作为转换的结果。"}, {"text": "我们要节约能量代谢。", "explanation": "这里应该用〈能源〉。能源是可利用的能量来源，能量代谢是能量转换的过程，不能被“节约”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学历", "is_correct": false, "explanation": "语义：大楼没有学历，“研究大楼的学历”说不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“大楼”与“歌曲”不搭配，“研究大楼的歌曲”不成立。"}, {"text": "能量代谢", "is_correct": true, "explanation": "能量代谢：指系统持续转换和传输能量的过程，与“研究大楼”的语境相符。"}, {"text": "爱好", "is_correct": false, "explanation": "语义：“爱好”指人的兴趣，大楼不会有爱好，句子无法成立。"}], "explanations": {"学历": "语义：大楼没有学历，“研究大楼的学历”说不通。", "歌曲": "搭配：“大楼”与“歌曲”不搭配，“研究大楼的歌曲”不成立。", "能量代谢": "能量代谢：指系统持续转换和传输能量的过程，与“研究大楼”的语境相符。", "爱好": "语义：“爱好”指人的兴趣，大楼不会有爱好，句子无法成立。"}, "sentence_index": 6, "correct_answer": "能量代谢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "焦耳是能量代谢的单位。", "explanation": "这里应该用〈能量〉。焦耳计量的是能量，能量代谢指系统转换和传输能量的过程，不是可以计量的量。"}, {"text": "漏电会造成能量代谢。", "explanation": "这里应该用〈能量流失〉。“造成”后面接的是结果，能量代谢是能量转换的过程，不是能量损失的结果。"}, {"text": "太阳是地球的能量代谢。", "explanation": "这里应该用〈能量来源〉。能量代谢是转换和传输能量的过程，本身不是能量来源，太阳才是地球的能量来源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套系统的能量代谢的很快。", "corrected_sentence": "这套系统的能量代谢很快。", "error_description": "错误在于多加了“的”：“很快”作谓语，直接接在“能量代谢”之后，不能再加“的”。正确：“这套系统的能量代谢很快。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个能源站的一台能量代谢需要定期检查。", "corrected_sentence": "这个能源站的一种能量代谢需要定期检查。", "error_description": "错误在于量词：“能量代谢”指系统转换能量的过程，应用量词“种”，不能用“台”（台多用于机器）。应改为“一种能量代谢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '534a9936-e36e-47c4-b1f3-4df982f12e37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
