INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13789, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指在集体中最受欢迎、最引人注目的人，常带有赞美之意。", "primary_collocate": null, "pronunciation": "bāng huā", "ipa": "pɑŋ˥ xu̯ɑ˥", "syllable_count": 2, "sentences": [{"text": "她长得漂亮又爱笑，是我们舞蹈队的帮花。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都喜欢小林，他是办公室的帮花。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的帮花今天又上台唱歌了。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队的帮花一出场，大家就大声鼓掌。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁是你们公司的帮花？", "target_word": "帮花", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小美性格好，朋友多，自然成了帮花。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是篮球队的帮花，每个人都想认识他。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都叫她帮花，因为她最受欢迎。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组的帮花今天穿了红色的裙子。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想当帮花，只想安静地工作。", "target_word": "帮花", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幫花", "label": "繁体"}, {"form": "一位帮花", "label": "量词"}], "register": "口语", "sense_fingerprint": "帮花|名词|集体中最受欢迎、最引人注目的人（赞美）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '075e48bb-16bc-4c85-a794-089c95f7240f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13789, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哭包", "is_correct": false, "explanation": "语义：“哭包”指爱哭的人，与句中的“爱笑”相反，不能用来赞美她。"}, {"text": "帮花", "is_correct": true, "explanation": "正确。“帮花”指集体中最受欢迎、最引人注目的人，与“漂亮又爱笑”的赞美相合。"}, {"text": "丑八怪", "is_correct": false, "explanation": "语义：“丑八怪”指难看，与前面的“长得漂亮”正相反。"}, {"text": "篮球", "is_correct": false, "explanation": "搭配：“舞蹈队的”后应接人，不能接球类，“舞蹈队的篮球”说不通。"}], "explanations": {"哭包": "语义：“哭包”指爱哭的人，与句中的“爱笑”相反，不能用来赞美她。", "帮花": "正确。“帮花”指集体中最受欢迎、最引人注目的人，与“漂亮又爱笑”的赞美相合。", "丑八怪": "语义：“丑八怪”指难看，与前面的“长得漂亮”正相反。", "篮球": "搭配：“舞蹈队的”后应接人，不能接球类，“舞蹈队的篮球”说不通。"}, "sentence_index": 0, "correct_answer": "帮花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是网上的帮花，粉丝很多。", "explanation": "这里应该用〈红人〉。帮花指同一集体中最受欢迎的人，指网上走红的公众人物应说红人。"}, {"text": "这次考试的帮花是小李，他考了全校第一。", "explanation": "这里应该用〈冠军〉。帮花指在集体中最受欢迎的人，不指成绩第一的人。"}, {"text": "我最崇拜的帮花是居里夫人。", "explanation": "这里应该用〈偶像〉。帮花指在集体中最受欢迎的人，个人崇拜的对象应说偶像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13789, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隐士", "is_correct": false, "explanation": "语义：“隐士”不与人往来，与“每个人都想认识他”矛盾。"}, {"text": "帮花", "is_correct": true, "explanation": "正确。“帮花”指集体中最受欢迎的人，与“每个人都想认识他”相合。"}, {"text": "局外人", "is_correct": false, "explanation": "语义：“局外人”指不属于某个群体的人，与“篮球队的”身份矛盾。"}, {"text": "车票", "is_correct": false, "explanation": "搭配：“篮球队的”后接人，不能接“车票”。"}], "explanations": {"隐士": "语义：“隐士”不与人往来，与“每个人都想认识他”矛盾。", "帮花": "正确。“帮花”指集体中最受欢迎的人，与“每个人都想认识他”相合。", "局外人": "语义：“局外人”指不属于某个群体的人，与“篮球队的”身份矛盾。", "车票": "搭配：“篮球队的”后接人，不能接“车票”。"}, "sentence_index": 6, "correct_answer": "帮花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班上新来的一张帮花很爱说话。", "explanation": "这里量词应改为〈位〉或〈个〉。“张”用于纸张、平面的东西，帮花指人，不能用“张”。"}, {"text": "他是电视里的帮花，很多人都看他的节目。", "explanation": "这里应该用〈明星〉。帮花指在同一集体中最受欢迎的人，电视上的明星不属于这个用法。"}, {"text": "她是我们班的一座帮花。", "explanation": "这里量词应改为〈位〉或〈个〉。“座”用于山、楼等大型固定的东西，不能用来数指人的帮花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13789, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班有一只帮花，大家都喜欢她。", "corrected_sentence": "我们班有一位帮花，大家都喜欢她。", "error_description": "量词错误：“帮花”指人，应用“位”或“个”，不能用“只”。改为“一位帮花”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13789, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是我们班帮花，大家都想跟她做朋友。", "corrected_sentence": "她是我们班的帮花，大家都想跟她做朋友。", "error_description": "“的”漏掉：“我们班”修饰“帮花”时要加“的”，应说“我们班的帮花”，不能说“我们班帮花”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
