INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13790, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在某单位或岗位上从事工作。", "primary_collocate": null, "pronunciation": "zuò shì", "ipa": "tswo˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他在银行做事，已经五年了。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在公司做事一向很有条理。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你在哪儿做事？离家远不远？", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在公司做事不拖拉，老板很满意。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥在一家公司做事。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚毕业，想先找个地方做事。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚上班，做事要有计划，才不会乱。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她在医院做事很稳重，大家都信任她。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸为了养家，每天辛苦做事。", "target_word": "做事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在工厂做事小心，从来不出错。", "target_word": "做事", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "做了事", "label": "体标（了）"}, {"form": "做过事", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "做事：在某单位或岗位上工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94fd5d6a-ee47-45b7-8109-ed74731efdc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13790, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "做事", "is_correct": true, "explanation": "正确。做事在此指在某处从事工作。"}, {"text": "错事", "is_correct": false, "explanation": "cuò（第四声）与 zuò 声母不同（c 与 z），意思是做错的事。"}, {"text": "作诗", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是写诗。"}, {"text": "坐实", "is_correct": false, "explanation": "shí（第二声）与 shì 声调不同，意思是证实、确定。"}], "explanations": {"做事": "正确。做事在此指在某处从事工作。", "错事": "cuò（第四声）与 zuò 声母不同（c 与 z），意思是做错的事。", "作诗": "shī（第一声）与 shì（第四声）声调不同，意思是写诗。", "坐实": "shí（第二声）与 shì 声调不同，意思是证实、确定。"}, "sentence_index": null, "correct_answer": "做事"}, "level_3": {"options": [{"text": "做事", "is_correct": true, "explanation": "正确。“在银行做事”指在银行工作，与“已经五年了”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：在银行游泳不合常理，与工作语境不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：在银行睡觉不是工作，与“在银行”的语境矛盾。"}, {"text": "跑步", "is_correct": false, "explanation": "搭配：“在……”后接地点时，多接工作或办事的动词，“在银行跑步”搭配不当。"}], "explanations": {"做事": "正确。“在银行做事”指在银行工作，与“已经五年了”相符。", "游泳": "语义：在银行游泳不合常理，与工作语境不符。", "睡觉": "语义：在银行睡觉不是工作，与“在银行”的语境矛盾。", "跑步": "搭配：“在……”后接地点时，多接工作或办事的动词，“在银行跑步”搭配不当。"}, "sentence_index": 0, "correct_answer": "做事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去电影院做事，看了一场电影。", "explanation": "这里应该用〈看电影〉。去电影院看电影要说“看电影”，“做事”不指观看。"}, {"text": "周末他去超市做事，买了很多东西。", "explanation": "这里应该用〈购物〉。去超市买东西要说“购物”，“做事”不指购买。"}, {"text": "我去公园做事，拍了一组照片。", "explanation": "这里应该用〈拍照〉。在公园拍照要说“拍照”，“做事”不指拍摄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做事", "is_correct": true, "explanation": "正确。“做事要有计划”指工作需要事先安排，与“才不会乱”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉一般不需要“要有计划才不会乱”的安排，句意不合语境。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：发呆不需要计划，与“要有计划”的语义相矛盾。"}, {"text": "闲逛", "is_correct": false, "explanation": "搭配：“闲逛”强调随意，与“要有计划”的语义相反。"}], "explanations": {"做事": "正确。“做事要有计划”指工作需要事先安排，与“才不会乱”相符。", "睡觉": "语义：睡觉一般不需要“要有计划才不会乱”的安排，句意不合语境。", "发呆": "语义：发呆不需要计划，与“要有计划”的语义相矛盾。", "闲逛": "搭配：“闲逛”强调随意，与“要有计划”的语义相反。"}, "sentence_index": 6, "correct_answer": "做事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房做事，做了一桌好菜。", "explanation": "这里应该用〈做饭〉。做菜、做饭要说“做饭”，“做事”不用于烹饪。"}, {"text": "我去药店做事，买了一盒感冒药。", "explanation": "这里应该用〈买药〉。去药店买药要说“买药”，“做事”不指购买。"}, {"text": "我们去河边做事，钓了一条大鱼。", "explanation": "这里应该用〈钓鱼〉。去河边钓鱼要说“钓鱼”，“做事”不指钓鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直在银行做了事，从没换过工作。", "corrected_sentence": "他一直在银行做事，从没换过工作。", "error_description": "“做事”的“了”位置错误。“一直在……”表示进行中，不能接“了”，应说“一直在银行做事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做事得很快，效率很高。", "corrected_sentence": "他做事做得很快，效率很高。", "error_description": "补语结构错误。“做事”后的补语要用“做得……”，缺少“做”会使句子不通，应说“做事做得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ff1ad4b-d103-4ed5-be14-625f43a7f944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13792, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "留下", "is_correct": true, "explanation": "正确。“留下”与“带走”相反，指离开时把东西留在原处。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”指把东西收拾得有条理，与“带走”不构成反义关系。"}, {"text": "修补", "is_correct": false, "explanation": "“修补”指修理破损的东西，与“带走”没有反义关系。"}, {"text": "聊天", "is_correct": false, "explanation": "“聊天”指交谈，与“带走”没有反义关系。"}], "correct_answer": "留下", "explanations": {"留下": "正确。“留下”与“带走”相反，指离开时把东西留在原处。", "整理": "“整理”指把东西收拾得有条理，与“带走”不构成反义关系。", "修补": "“修补”指修理破损的东西，与“带走”没有反义关系。", "聊天": "“聊天”指交谈，与“带走”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13792, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "留下", "is_correct": true, "explanation": "正确。“留下”与“带走”相反，指离开时把东西留在原处。"}, {"text": "吃饭", "is_correct": false, "explanation": "“吃饭”指进食，与“带走”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”指休息入睡，与“带走”没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "“写字”指用笔写字，与“带走”没有反义关系。"}], "correct_answer": "留下", "explanations": {"留下": "正确。“留下”与“带走”相反，指离开时把东西留在原处。", "吃饭": "“吃饭”指进食，与“带走”没有反义关系。", "睡觉": "“睡觉”指休息入睡，与“带走”没有反义关系。", "写字": "“写字”指用笔写字，与“带走”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13792, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "携带（某人或某物）一起离开。", "primary_collocate": null, "pronunciation": "dài zǒu", "ipa": "tai̯˥˩ tsou̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "花有粉，蜜蜂带走粉。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "下课了，请把你的书带走。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明离开时把雨伞带走了。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开房间时，别带走别人的东西。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家那天，妈妈带走了她的小狗。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花很漂亮，你可以带走。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走的时候带走了所有的衣服。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子是公司的，你不能带走。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出国前想带走一张全家的照片。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟走的时候，把我的帽子也带走了。", "target_word": "带走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带走了", "label": "体标（完成）"}, {"form": "带走过", "label": "体标（经历）"}, {"form": "带不走", "label": "可能补语（否定）"}, {"form": "带得走", "label": "可能补语（肯定）"}], "register": "中性", "sense_fingerprint": "离开时随身携带某人或某物一起走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '075e48bb-16bc-4c85-a794-089c95f7240f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13792, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "带走", "is_correct": true, "explanation": "正确。带走 dài zǒu，指携带人或物一起离开。"}, {"text": "抬走", "is_correct": false, "explanation": "tái（第二声）与 dài（第四声）声母与声调都不同，意思是用手抬起来搬走。"}, {"text": "再走", "is_correct": false, "explanation": "zài 与 dài 声母不同（z 与 d），意思是再走一次或稍后再走。"}, {"text": "得走", "is_correct": false, "explanation": "děi（第三声）与 dài（第四声）韵母与声调不同，意思是不得不离开。"}], "explanations": {"带走": "正确。带走 dài zǒu，指携带人或物一起离开。", "抬走": "tái（第二声）与 dài（第四声）声母与声调都不同，意思是用手抬起来搬走。", "再走": "zài 与 dài 声母不同（z 与 d），意思是再走一次或稍后再走。", "得走": "děi（第三声）与 dài（第四声）韵母与声调不同，意思是不得不离开。"}, "sentence_index": null, "correct_answer": "带走"}, "level_3": {"options": [{"text": "制造", "is_correct": false, "explanation": "语义：花粉是花本来就有的，蜜蜂不会制造粉，与“花有粉”矛盾。"}, {"text": "带走", "is_correct": true, "explanation": "正确。“带走”表示把粉随身携带离开，与句子的语境相合。"}, {"text": "挥霍", "is_correct": false, "explanation": "搭配：“挥霍”多接钱财、时间，不接花粉。"}, {"text": "研究", "is_correct": false, "explanation": "语义：“研究”需要人的思考，蜜蜂不做研究，句子语境不合。"}], "explanations": {"制造": "语义：花粉是花本来就有的，蜜蜂不会制造粉，与“花有粉”矛盾。", "带走": "正确。“带走”表示把粉随身携带离开，与句子的语境相合。", "挥霍": "搭配：“挥霍”多接钱财、时间，不接花粉。", "研究": "语义：“研究”需要人的思考，蜜蜂不做研究，句子语境不合。"}, "sentence_index": 0, "correct_answer": "带走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从北京给你带走了一件礼物，你看看喜不喜欢。", "explanation": "这里应该用〈带来〉。带走指离开某处时把东西一起拿走，把东西送到对方身边要用带来。"}, {"text": "他把房子带走了。", "explanation": "这里不能用〈带走〉。带走的东西要能随人离开，房子固定不动，不能被带走。"}, {"text": "朋友给我带走了一箱水果，我很高兴。", "explanation": "这里应该用〈送来〉。带走是离开时拿走，把水果送到说话人这里要用送来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”针对来客，与“所有的衣服”搭配不当，也与“走的时候”的语境矛盾。"}, {"text": "带走", "is_correct": true, "explanation": "正确。“带走”表示离开时把衣服一起拿走，与“走的时候”相合。"}, {"text": "挤压", "is_correct": false, "explanation": "搭配：“挤压”多接物体或空间，不说挤压所有的衣服。"}, {"text": "咬", "is_correct": false, "explanation": "语义：人不会咬下所有衣服，与句子的语境不合。"}], "explanations": {"迎接": "语义：“迎接”针对来客，与“所有的衣服”搭配不当，也与“走的时候”的语境矛盾。", "带走": "正确。“带走”表示离开时把衣服一起拿走，与“走的时候”相合。", "挤压": "搭配：“挤压”多接物体或空间，不说挤压所有的衣服。", "咬": "语义：人不会咬下所有衣服，与句子的语境不合。"}, "sentence_index": 6, "correct_answer": "带走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我带走了一碗汤，我很感动。", "explanation": "这里应该用〈端来〉。带走表示离开时拿走，“给我”的东西是送到说话人身边，要用端来。"}, {"text": "他把这座山带走了。", "explanation": "这里不能用〈带走〉。山太大、固定不动，不能随人离开，不能说带走。"}, {"text": "老师给我带走了一本书，我很高兴。", "explanation": "这里应该用〈拿来〉。带走指离开时拿走，把书交到说话人手里要用拿来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下课以后，我书把带走了。", "corrected_sentence": "下课以后，我把书带走了。", "error_description": "语序错误：“把”字结构中，“把”应放在宾语“书”之前，说“我把书带走了”，不能把“书”放在“把”的前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下课以后，我把书带走了过。", "corrected_sentence": "下课以后，我把书带走了。", "error_description": "体标错误：“了”与“过”不能同时用在同一个动词后，应只保留“了”，说“我把书带走了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13793, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b533e9e5-d566-4853-ac6c-d6663c12298b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
