INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13797, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指蜜蜂从花朵中采集花蜜。", "primary_collocate": null, "pronunciation": "cǎi mì", "ipa": "tsʰai˨˩ mi˥˩", "syllable_count": 2, "sentences": [{"text": "蜜蜂从花里采蜜，身上会沾上花粉。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "春天到了，小蜜蜂飞到花园里采蜜。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂每天早上都出去采蜜。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨的时候，蜜蜂不能出去采蜜。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花开了，蜜蜂忙着采蜜。", "target_word": "采蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂采蜜时，会在花间飞来飞去。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂采蜜回来，就把花蜜放进蜂巢。", "target_word": "采蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小蜜蜂采蜜回来了。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂为什么要采蜜？因为它们要做蜂蜜。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂最喜欢在晴天采蜜。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "采了蜜", "label": "体标（了）"}, {"form": "采过蜜", "label": "体标（过）"}, {"form": "採蜜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "蜜蜂从花朵中采集花蜜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '774c926e-fb1f-4488-8915-497812d93261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13797, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修剪", "is_correct": false, "explanation": "语义：「修剪」指修整花木，与蜜蜂从花里取蜜的语境不符。"}, {"text": "采蜜", "is_correct": true, "explanation": "正确：「采蜜」指蜜蜂从花朵中采集花蜜，与「从花里」相符。"}, {"text": "喂", "is_correct": false, "explanation": "配价：「喂」需要带被喂对象的宾语，「蜜蜂从花里喂」缺少宾语。"}, {"text": "挖", "is_correct": false, "explanation": "搭配：「挖」用于挖土、挖洞，不说从花里挖。"}], "explanations": {"修剪": "语义：「修剪」指修整花木，与蜜蜂从花里取蜜的语境不符。", "采蜜": "正确：「采蜜」指蜜蜂从花朵中采集花蜜，与「从花里」相符。", "喂": "配价：「喂」需要带被喂对象的宾语，「蜜蜂从花里喂」缺少宾语。", "挖": "搭配：「挖」用于挖土、挖洞，不说从花里挖。"}, "sentence_index": 0, "correct_answer": "采蜜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蜜蜂整天待在蜂巢里采蜜。", "explanation": "这里应该用〈酿蜜〉。采蜜指蜜蜂到花朵上采集花蜜，在蜂巢里把花蜜加工成蜂蜜要说〈酿蜜〉。"}, {"text": "小鸟每天飞到花园里采蜜。", "explanation": "这里不应该用〈采蜜〉。采蜜专指蜜蜂从花中采集花蜜，小鸟吸食花蜜应说〈吸食〉。"}, {"text": "小猫每天在花园里采蜜，吃得很饱。", "explanation": "这里不应该用〈采蜜〉。采蜜的主体是蜜蜂，猫不采蜜，此句主语错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放", "is_correct": false, "explanation": "配价：「放」需要带宾语，「蜜蜂放回来」缺少被放的对象。"}, {"text": "缝", "is_correct": false, "explanation": "语义：「缝」指缝合布料，蜜蜂不能缝回来。"}, {"text": "采蜜", "is_correct": true, "explanation": "正确：「采蜜回来」说明蜜蜂外出采集后返回，与后句「把花蜜放进蜂巢」相承。"}, {"text": "睡", "is_correct": false, "explanation": "语义：「睡」指睡觉，「蜜蜂睡回来」与后句放花蜜进蜂巢的动作不衔接。"}], "explanations": {"放": "配价：「放」需要带宾语，「蜜蜂放回来」缺少被放的对象。", "缝": "语义：「缝」指缝合布料，蜜蜂不能缝回来。", "采蜜": "正确：「采蜜回来」说明蜜蜂外出采集后返回，与后句「把花蜜放进蜂巢」相承。", "睡": "语义：「睡」指睡觉，「蜜蜂睡回来」与后句放花蜜进蜂巢的动作不衔接。"}, "sentence_index": 6, "correct_answer": "采蜜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小狗每天在河边采蜜，吃得很饱。", "explanation": "这里不应该用〈采蜜〉。采蜜的主体是蜜蜂，小狗不采蜜，此句主语错误。"}, {"text": "蜜蜂整天在河里采蜜。", "explanation": "这里不应该用〈采蜜〉，应说〈取水〉。采蜜专指蜜蜂在花朵上采集花蜜，蜜蜂到河边取水要说〈取水〉。"}, {"text": "我们在山坡上采蜜，回家做汤。", "explanation": "这里应该用〈摘〉。采蜜专指蜜蜂采集花蜜，人摘野菜要说〈摘〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13797, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蜜蜂一大早就勤快的采蜜。", "corrected_sentence": "蜜蜂一大早就勤快地采蜜。", "error_description": "状语标记错误：修饰动词「采蜜」的「勤快」是状语，要用「地」，不能用「的」，应说「勤快地采蜜」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13797, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜜蜂明天就去采蜜过。", "corrected_sentence": "蜜蜂明天就去采蜜。", "error_description": "体标错误：「过」表示已经发生过的经历，不能用于将来的「明天」，应说「明天就去采蜜」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa1a658-c081-407b-9ee9-8da0ced2891d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
