INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13803, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "动植物是动物和植物的总称，包括所有生物中的动物界和植物界。", "primary_collocate": null, "pronunciation": "dòng zhí wù", "ipa": "tʊŋ˥˩ ʈʂɨ˧˥ u˥˩", "syllable_count": 3, "sentences": [{"text": "如果蜜蜂变少了，其他动植物也会受影响。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个公园里有很多动植物。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要保护动植物。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的动植物很丰富。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去看动植物。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里住着很多动植物。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了海边的动植物。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，有些动植物活不下去。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对动植物很感兴趣。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水脏了，河里的动植物都少了。", "target_word": "动植物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种动植物", "label": "量词"}, {"form": "動植物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动物和植物的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e245a58-1dc2-40c3-b6f0-b46e940614ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13803, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”是人造的交通工具，不属于会受蜜蜂数量影响的生态群体，与生态语境不符。"}, {"text": "动植物", "is_correct": true, "explanation": "正确：“动植物”指动物和植物的总称，与“其他动植物也会受影响”相符。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“天空”是整体概念，不说“其他天空”。"}, {"text": "家具", "is_correct": false, "explanation": "语义：“家具”是人造物，不在蜜蜂所在的生态系统中，与句意不符。"}], "explanations": {"汽车": "语义：“汽车”是人造的交通工具，不属于会受蜜蜂数量影响的生态群体，与生态语境不符。", "动植物": "正确：“动植物”指动物和植物的总称，与“其他动植物也会受影响”相符。", "天空": "搭配：“天空”是整体概念，不说“其他天空”。", "家具": "语义：“家具”是人造物，不在蜜蜂所在的生态系统中，与句意不符。"}, "sentence_index": 0, "correct_answer": "动植物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在森林里发现了一只动植物。", "explanation": "这里应该用〈种〉。动植物是总称，不能用“只”来数，要说“一种动植物”。"}, {"text": "这片草地上长满了动植物。", "explanation": "这里应该用〈植物〉。“长满”说的是植物，动植物里有动物，动物不会长在草地上。"}, {"text": "山上种了很多动植物。", "explanation": "这里应该用〈树〉。“种”说的是植物，动植物里有动物，动物不能种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13803, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "螺丝钉", "is_correct": false, "explanation": "语义：“螺丝钉”是机械零件，不是书中介绍海边事物的对象，与句意不符。"}, {"text": "动植物", "is_correct": true, "explanation": "正确：“动植物”指海边的动物和植物，与“这本书介绍了海边的动植物”相符。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是城市交通设施，不是书中介绍海边动植物的对象，与句意不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，海边的冰箱不是书中介绍的内容。"}], "explanations": {"螺丝钉": "语义：“螺丝钉”是机械零件，不是书中介绍海边事物的对象，与句意不符。", "动植物": "正确：“动植物”指海边的动物和植物，与“这本书介绍了海边的动植物”相符。", "地铁": "语义：地铁是城市交通设施，不是书中介绍海边动植物的对象，与句意不符。", "冰箱": "语义：“冰箱”是家用电器，海边的冰箱不是书中介绍的内容。"}, "sentence_index": 6, "correct_answer": "动植物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一条动植物。", "explanation": "这里应该用〈种〉。动植物是总称，“条”用于细长的东西，不能用来数动植物。"}, {"text": "花园里种满了动植物。", "explanation": "这里应该用〈植物〉。“种满”说的是植物，动植物里有动物，动物不能种。"}, {"text": "草地上长着很多动植物。", "explanation": "这里应该用〈植物〉。“长着”说的是植物，动植物里的动物不会长在草地上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13803, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片保护区里有很多动植物们。", "corrected_sentence": "这片保护区里有很多动植物。", "error_description": "“们”只用于指人，动植物是总称，不能加“们”，应说“动植物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13803, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该尊重这个动植物。", "corrected_sentence": "我们应该尊重这些动植物。", "error_description": "“动植物”是总称，指多种生物，不能用量词“个”来限定，应说“这些动植物”，不说“这个动植物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13806, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13806, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13806, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指雄蕊的花粉传到雌蕊柱头上的过程。", "primary_collocate": null, "pronunciation": "shòu fěn", "ipa": "ʂoʊ˥˩ fən˨˩˦", "syllable_count": 2, "sentences": [{"text": "在地球错综复杂的生态系统中，蜜蜂作为最为关键的授粉昆虫之一，其存在远不止于生产蜂蜜这一表层价值。", "target_word": "授粉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "事实上，全球约75%的农作物种类在不同程度上依赖动物授粉，而蜜蜂正是其中占比最高的传粉媒介。", "target_word": "授粉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这些研究揭示了一个令人警觉的事实：当某一区域的授粉昆虫丰度下降时，不仅植物结实率显著降低，连锁效应还会波及依赖这些植物生存的鸟类、哺乳动物及其他无脊椎动物，从而引发生态系统服务功能的级联式崩溃。", "target_word": "授粉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "例如，在某些高原农业区，野生蜂类数量锐减已导致本地果树坐果率不足三成，迫使农民转向成本高昂的人工授粉，这不仅增加了农业生产的经济负担，也暴露了食物供应链的脆弱性。", "target_word": "授粉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "部分前沿研究指出，建立生态廊道、恢复原生植被、实施精准农业管理以及制定跨区域的授粉保护政策，可能是缓解危机的有效路径。", "target_word": "授粉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "某些国家已启动保护授粉昆虫的计划，通过立法限制特定神经毒性农药的使用，并鼓励农场主采用生态友好型耕作方式。", "target_word": "授粉", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "许多植物需要授粉才能结果，而蜜蜂在采集花蜜时，会把花粉从一朵花带到另一朵花。", "target_word": "授粉", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "农业非常依赖蜜蜂的授粉服务。", "target_word": "授粉", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "科学家估计，全球大约三分之一的粮食生产与蜜蜂授粉有关。", "target_word": "授粉", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "春天花开了，蜜蜂飞来飞去帮花授粉。", "target_word": "授粉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "授粉了", "label": "体标"}, {"form": "人工授粉", "label": "复合"}], "register": "中性", "sense_fingerprint": "授粉：花粉从雄蕊传到雌蕊柱头的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43fcd651-f37e-4c54-87ee-af7602635d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "授粉", "is_correct": true, "explanation": "正确：修饰“昆虫”，指蜜蜂传递花粉的作用，与“最为关键”的生态角色相符。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：“生产”的对象应是蜂蜜、粮食等产品，不能用来修饰“昆虫”。"}, {"text": "冬眠", "is_correct": false, "explanation": "语义：冬眠是动物的静止休眠，与“最为关键”的生态作用相悖。"}, {"text": "叮咬", "is_correct": false, "explanation": "语义：叮咬是伤害行为，与句中“生态系统”的正面作用相悖。"}], "explanations": {"授粉": "正确：修饰“昆虫”，指蜜蜂传递花粉的作用，与“最为关键”的生态角色相符。", "生产": "搭配：“生产”的对象应是蜂蜜、粮食等产品，不能用来修饰“昆虫”。", "冬眠": "语义：冬眠是动物的静止休眠，与“最为关键”的生态作用相悖。", "叮咬": "语义：叮咬是伤害行为，与句中“生态系统”的正面作用相悖。"}, "sentence_index": 0, "correct_answer": "授粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老师每天在课堂上认真授粉，学生都很喜欢。", "explanation": "这里应该用〈授课〉。授粉指花粉传到雌蕊柱头，只用于植物的花；老师讲课要说授课。"}, {"text": "我昨天给新买的书架授粉了。", "explanation": "这里应该用〈粉刷〉。授粉指花粉传到雌蕊柱头，只用于植物的花；给书架涂色、上漆要说粉刷。"}, {"text": "妈妈每天早上都给我授粉。", "explanation": "这里应该用〈照顾〉。授粉只指植物花粉的传递，只用于植物；妈妈照顾孩子要说照顾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "授粉", "is_correct": true, "explanation": "正确：作“需要”的宾语，指植物结果前必需的传粉过程。"}, {"text": "迁徙", "is_correct": false, "explanation": "语义：植物不会迁徙，与“需要……才能结果”的语境不符。"}, {"text": "睡眠", "is_correct": false, "explanation": "语义：睡眠与植物结果无关，句意说的是结果所需的条件。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“需要……才能结果”不搭配“唱歌”，二者没有因果关系。"}], "explanations": {"授粉": "正确：作“需要”的宾语，指植物结果前必需的传粉过程。", "迁徙": "语义：植物不会迁徙，与“需要……才能结果”的语境不符。", "睡眠": "语义：睡眠与植物结果无关，句意说的是结果所需的条件。", "唱歌": "搭配：“需要……才能结果”不搭配“唱歌”，二者没有因果关系。"}, "sentence_index": 6, "correct_answer": "授粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子每天都在授粉，很忙。", "explanation": "这里应该用〈工作〉。授粉只指花粉传到雌蕊柱头，主体是传粉的花或昆虫；桌子办公、干活要说工作。"}, {"text": "农民每天都给小猪授粉。", "explanation": "这里应该用〈喂〉。授粉只用于植物的花；给小猪吃食要说喂。"}, {"text": "他很喜欢给理想授粉。", "explanation": "这里应该用〈追求〉。授粉只用于植物的花；对理想的努力要说追求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蜜蜂正在被苹果花授粉。", "corrected_sentence": "蜜蜂正在给苹果花授粉。", "error_description": "介词错误：引出授粉对象“苹果花”要用“给”，不能用“被”；“被苹果花授粉”会使苹果花变成施动者，与句意相反。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜜蜂在草莓花上授粉了一个。", "corrected_sentence": "蜜蜂在草莓花上授粉了一次。", "error_description": "量词错误：“授粉”是动作，计量要用“次”，“个”用于事物，不能用来计量动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
