INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13808, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "收集、拾取或采摘，例如采集植物、数据或样本。", "primary_collocate": null, "pronunciation": "cǎi jí", "ipa": "tsʰai˨˩˦ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "许多植物需要授粉才能结果，而蜜蜂在采集花蜜时，会把花粉从一朵花带到另一朵花，这个过程叫做授粉。", "target_word": "采集", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "农民们一早就上山采集野生蘑菇。", "target_word": "采集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家去河边采集水样，带回实验室检查。", "target_word": "采集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们在公园里采集树叶做标本。", "target_word": "采集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员正在采集病人的血液样本。", "target_word": "采集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件可以自动采集天气数据。", "target_word": "采集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们已经采集了三百份土壤样本。", "target_word": "采集", "complexity_tier": "T3", "furigana": "wǒ men yǐ jīng cǎi jí le sān bǎi fèn tǔ rǎng yàng běn", "sentence_source": "generated"}, {"text": "他在山里采集过很多种草药。", "target_word": "采集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把采集到的数据放进表格里。", "target_word": "采集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在森林里采集昆虫标本。", "target_word": "采集", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "采集了", "label": "完成体"}, {"form": "采集过", "label": "经历体"}, {"form": "采集者", "label": "复合词"}], "register": "中性", "sense_fingerprint": "采集：收集或采摘植物、样本、数据等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '048066ef-e0c6-43cd-971f-4df52a6c6dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13808, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拍摄", "is_correct": false, "explanation": "语义：拍摄是用相机记录影像，蜜蜂不会拍摄，与“采集花蜜”的句意不符。"}, {"text": "采集", "is_correct": true, "explanation": "正确：蜜蜂在采集花蜜时会带走花粉，与句中的“授粉”过程相符。"}, {"text": "研究", "is_correct": false, "explanation": "语义：蜜蜂不会研究，句子描述的是蜜蜂的自然行为。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”的对象是文件、文字，不能说“打印花蜜”。"}], "explanations": {"拍摄": "语义：拍摄是用相机记录影像，蜜蜂不会拍摄，与“采集花蜜”的句意不符。", "采集": "正确：蜜蜂在采集花蜜时会带走花粉，与句中的“授粉”过程相符。", "研究": "语义：蜜蜂不会研究，句子描述的是蜜蜂的自然行为。", "打印": "搭配：“打印”的对象是文件、文字，不能说“打印花蜜”。"}, "sentence_index": 0, "correct_answer": "采集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在银行采集了一笔贷款。", "explanation": "这里应该用〈申请〉。采集指收集、拾取或采摘，贷款要说申请，不能说采集。"}, {"text": "他在饭店采集了一顿晚饭。", "explanation": "这里应该用〈吃〉或〈点〉。采集指从自然环境中收集、拾取或采摘，吃饭、点菜不能说采集。"}, {"text": "他在公司采集了一份工作。", "explanation": "这里应该用〈应聘〉。采集指收集、拾取或采摘，找工作要说应聘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做菜，与土壤样本无关，句意不通。"}, {"text": "设计", "is_correct": false, "explanation": "搭配：“设计”多用于方案、产品，不说“设计了三百份土壤样本”。"}, {"text": "采集", "is_correct": true, "explanation": "正确：采集土壤样本是取样分析的常见做法，与“已经……了”的完成语气一致。"}, {"text": "印刷", "is_correct": false, "explanation": "搭配：“印刷”的对象是书刊、文件，不能说印刷土壤样本。"}], "explanations": {"烹饪": "语义：烹饪是做菜，与土壤样本无关，句意不通。", "设计": "搭配：“设计”多用于方案、产品，不说“设计了三百份土壤样本”。", "采集": "正确：采集土壤样本是取样分析的常见做法，与“已经……了”的完成语气一致。", "印刷": "搭配：“印刷”的对象是书刊、文件，不能说印刷土壤样本。"}, "sentence_index": 6, "correct_answer": "采集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在超市采集了很多蔬菜。", "explanation": "这里应该用〈购买〉。采集指从自然环境中获取，在超市买菜要说购买。"}, {"text": "工人在矿山采集煤炭。", "explanation": "这里应该用〈开采〉。采集多用于少量的植物、样本，大规模挖掘矿物要说开采。"}, {"text": "农民在田里采集麦子。", "explanation": "这里应该用〈收割〉。收割是大批量收获成熟的农作物，采集指零星获取样本或植物，不说“采集麦子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在森林里采集了很多了标本。", "corrected_sentence": "他们在森林里采集了很多标本。", "error_description": "了的位置错误：完成体“了”应紧跟动词“采集”，“很多”后面不能再加“了”。写成“采集了很多了标本”是错误的，应为“采集了很多标本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经采集好了三份了样本。", "corrected_sentence": "他已经采集好了三份样本。", "error_description": "了的位置错误：“了”只需出现一次，应紧跟动词或补语之后。“三份”后面的“了”是多余的，写成“三份了样本”是错误的，应为“采集好了三份样本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
