INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13809, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "花蜜是植物花朵中蜜腺分泌的甜味液体，吸引昆虫来采蜜并帮助传播花粉。", "primary_collocate": null, "pronunciation": "huā mì", "ipa": "xua˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "许多植物需要授粉才能结果，而蜜蜂在采集花蜜时，会把花粉从一朵花带到另一朵花，这个过程叫做授粉。", "target_word": "花蜜", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "蝴蝶停在花上吸花蜜。", "target_word": "花蜜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "养蜂人说，今年花蜜多，蜂蜜也多。", "target_word": "花蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种花的花蜜特别甜。", "target_word": "花蜜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天花开了，蜜蜂忙着找花蜜。", "target_word": "花蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟用长长的嘴喝花蜜。", "target_word": "花蜜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "花蜜是植物送给昆虫的礼物。", "target_word": "花蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工蜂把花蜜运回蜂巢，再酿成蜂蜜。", "target_word": "花蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜂鸟靠吸食花蜜活着。", "target_word": "花蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光好的时候，花会分泌更多花蜜。", "target_word": "花蜜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "滴", "label": "量词"}, {"form": "点", "label": "量词"}], "register": "中性", "sense_fingerprint": "花蜜：花的蜜腺分泌的甜液，吸引昆虫传粉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '048066ef-e0c6-43cd-971f-4df52a6c6dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13809, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "树叶", "is_correct": false, "explanation": "语义：蜜蜂不采集树叶，与“把花粉从一朵花带到另一朵花”的语境不符。"}, {"text": "花蜜", "is_correct": true, "explanation": "正确：蜜蜂采集的是花朵中的甜液，与授粉的语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：蜜蜂不采集石头，与授粉的语境矛盾。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“花园”是场所，不能作为“采集”的对象。"}], "explanations": {"树叶": "语义：蜜蜂不采集树叶，与“把花粉从一朵花带到另一朵花”的语境不符。", "花蜜": "正确：蜜蜂采集的是花朵中的甜液，与授粉的语境相符。", "石头": "语义：蜜蜂不采集石头，与授粉的语境矛盾。", "花园": "搭配：“花园”是场所，不能作为“采集”的对象。"}, "sentence_index": 0, "correct_answer": "花蜜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶每天早上用花蜜刷牙。", "explanation": "这里应该用〈牙膏〉。花蜜是植物的甜液，不能用来刷牙。"}, {"text": "花蜜飘满了整个院子。", "explanation": "这里应该用〈花香〉。液体的花蜜不会飘散在空中，飘满院子的是花香。"}, {"text": "院子里的花蜜开得很美。", "explanation": "这里应该用〈花朵〉。开放的是花朵，花蜜是液体，不能说开得很美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13809, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阴影", "is_correct": false, "explanation": "语义：阴影不是植物能送给昆虫的东西，与“礼物”不符。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图不是植物送给昆虫的食物或礼物，与语境不符。"}, {"text": "花蜜", "is_correct": true, "explanation": "正确：花蜜是植物分泌、吸引昆虫的甜液，可以看作植物送给昆虫的礼物。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“天空”是场所，不是可以赠送的东西，不能作“礼物”的主语。"}], "explanations": {"阴影": "语义：阴影不是植物能送给昆虫的东西，与“礼物”不符。", "地图": "语义：地图不是植物送给昆虫的食物或礼物，与语境不符。", "花蜜": "正确：花蜜是植物分泌、吸引昆虫的甜液，可以看作植物送给昆虫的礼物。", "天空": "搭配：“天空”是场所，不是可以赠送的东西，不能作“礼物”的主语。"}, "sentence_index": 6, "correct_answer": "花蜜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这朵花的花蜜很硬，用手一捏就碎了。", "explanation": "这里应该用〈花瓣〉。花蜜是液体，不会很硬、一捏就碎，这类描述用于花瓣。"}, {"text": "妈妈用花蜜洗了衣服，很干净。", "explanation": "这里应该用〈洗衣粉〉。花蜜是植物的甜液，不能用来去污洗衣。"}, {"text": "花蜜越长越高，弯下了腰。", "explanation": "这里应该用〈花枝〉。花蜜是液体，不会长高或弯腰，这类描述用于花枝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蜜蜂在花上吸到了一只花蜜。", "corrected_sentence": "蜜蜂在花上吸到了一点花蜜。", "error_description": "错误：量词“只”用于动物或个体物件，不能修饰液体“花蜜”。正确说法是“一点花蜜”，液体可用“点”或“滴”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天气暖和的时候，花会产生更多个花蜜。", "corrected_sentence": "天气暖和的时候，花会产生更多花蜜。", "error_description": "错误：量词“个”用于个体事物，不能修饰液体“花蜜”，“更多”后直接接名词即可。正确说法是“更多花蜜”，去掉“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
