INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13810, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13810, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "携带或引导到某处。", "primary_collocate": null, "pronunciation": "dài dào", "ipa": "tai˥˩ tau˥˩", "syllable_count": 2, "sentences": [{"text": "许多植物需要授粉才能结果，而蜜蜂在采集花蜜时，会把花粉从一朵花带到另一朵花，这个过程叫做授粉。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "风把花粉带到很远的地方。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这本书带到教室。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水把小船带到了海边。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把朋友带到自己家里。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把学生带到图书馆去看书。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟儿把种子带到别的山上。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这封信带到邮局。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把我带到公园玩。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路能把我们带到山顶。", "target_word": "带到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带到了", "label": "体标"}, {"form": "带到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "带到：携带或引导到某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70f80afb-2f40-4b32-8524-5af00f94cd49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13810, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "带到", "is_correct": true, "explanation": "正确：带到，dài dào，意思是把人或东西带往某处。"}, {"text": "带刀", "is_correct": false, "explanation": "dāo（第一声）与 dào（第四声）声调不同，“带刀”的意思是携带刀子，与“带到”的第二个音节不同。"}, {"text": "逮到", "is_correct": false, "explanation": "dǎi（第三声）与 dài（第四声）声调不同，“逮到”的意思是抓住，与“带到”的第一个音节不同。"}, {"text": "大道", "is_correct": false, "explanation": "dà 与 dài 的韵母不同（a 与 ai），“大道”的意思是大路，与“带到”的第一个音节不同。"}], "explanations": {"带到": "正确：带到，dài dào，意思是把人或东西带往某处。", "带刀": "dāo（第一声）与 dào（第四声）声调不同，“带刀”的意思是携带刀子，与“带到”的第二个音节不同。", "逮到": "dǎi（第三声）与 dài（第四声）声调不同，“逮到”的意思是抓住，与“带到”的第一个音节不同。", "大道": "dà 与 dài 的韵母不同（a 与 ai），“大道”的意思是大路，与“带到”的第一个音节不同。"}, "sentence_index": null, "correct_answer": "带到"}, "level_3": {"options": [{"text": "带到", "is_correct": true, "explanation": "正确：“把花粉从一朵花带到另一朵花”，表示把花粉携带到另一朵花上。"}, {"text": "飞到", "is_correct": false, "explanation": "配价：“飞”是不及物动词，不能带“把”字宾语，不能说“把花粉飞到另一朵花”。"}, {"text": "跳到", "is_correct": false, "explanation": "配价：“跳”没有使物体转移的用法，不能说“把花粉跳到另一朵花”。"}, {"text": "摘到", "is_correct": false, "explanation": "语义：“摘”是从植株上取下，不表示把花粉转移到另一朵花。"}], "explanations": {"带到": "正确：“把花粉从一朵花带到另一朵花”，表示把花粉携带到另一朵花上。", "飞到": "配价：“飞”是不及物动词，不能带“把”字宾语，不能说“把花粉飞到另一朵花”。", "跳到": "配价：“跳”没有使物体转移的用法，不能说“把花粉跳到另一朵花”。", "摘到": "语义：“摘”是从植株上取下，不表示把花粉转移到另一朵花。"}, "sentence_index": 0, "correct_answer": "带到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项政策带到了很大的变化。", "explanation": "这里应该用〈带来〉。带到指把人或东西送往某处，引起变化、结果要用〈带来〉。"}, {"text": "我终于带到了那份奖学金。", "explanation": "这里应该用〈拿到〉。带到表示携带到某处，获得奖学金要用〈拿到〉。"}, {"text": "这次大雨带到了很多损失。", "explanation": "这里应该用〈造成〉。带到不能引出“损失”这类结果，产生损失要用〈造成〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带到", "is_correct": true, "explanation": "正确：“鸟儿把种子带到别的山上”，表示种子随鸟转移到别处。"}, {"text": "寄到", "is_correct": false, "explanation": "搭配：“寄”指通过邮递发送，不能说鸟儿“寄”种子。"}, {"text": "扛到", "is_correct": false, "explanation": "语义：“扛”需要用肩膀负重，鸟儿不能扛种子。"}, {"text": "押到", "is_correct": false, "explanation": "语义：“押”指押送或扣押，带有强制意味，不符合鸟儿运送种子的情境。"}], "explanations": {"带到": "正确：“鸟儿把种子带到别的山上”，表示种子随鸟转移到别处。", "寄到": "搭配：“寄”指通过邮递发送，不能说鸟儿“寄”种子。", "扛到": "语义：“扛”需要用肩膀负重，鸟儿不能扛种子。", "押到": "语义：“押”指押送或扣押，带有强制意味，不符合鸟儿运送种子的情境。"}, "sentence_index": 6, "correct_answer": "带到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个消息带到了大家的关注。", "explanation": "这里应该用〈引起〉。带到表示携带到某处，引发关注要用〈引起〉。"}, {"text": "这份坚持带到了应有的回报。", "explanation": "这里应该用〈得到〉。带到不用于获得回报，获得回报要用〈得到〉。"}, {"text": "这次比赛带到了好成绩。", "explanation": "这里应该用〈取得〉。带到表示携带，不表示获得成绩，取得成绩要用〈取得〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下课后请把作业带到了办公室。", "corrected_sentence": "下课后请把作业带到办公室。", "error_description": "错误在于“带到”后面多加了“了”。“请”表示祈使，要求对方将来去做，“了”表示动作已经完成，二者矛盾；应说“下课后请把作业带到办公室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天妈妈我带到了医院。", "corrected_sentence": "昨天妈妈把我带到了医院。", "error_description": "错误在于漏掉“把”：把字句中“把”须放在宾语“我”前，漏掉后“妈妈我带到了医院”不成句，应为“昨天妈妈把我带到了医院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
