INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13812, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指杏子核仁或杏仁树的种子，可食用或药用。", "primary_collocate": null, "pronunciation": "xìng rén", "ipa": "ɕiŋ˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "从苹果、杏仁到咖啡与可可，这些人类饮食结构中的重要组成部分，其产量与质量皆深刻受制于蜂类活动的稳定性。", "target_word": "杏仁", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "例如，苹果、杏仁和蓝莓等作物，大部分都要靠蜜蜂来帮助繁殖。", "target_word": "杏仁", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "我早上喝牛奶，吃了几颗杏仁。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在蛋糕上放了很多杏仁。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中医说，杏仁可以当药，能帮助止咳。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杏仁有点苦，不能多吃。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对杏仁过敏，一吃就会难受。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里卖的杏仁，是用来当零食的。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把杏仁放进热水里，皮就很容易剥下来。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杏子里面的核打开以后，就能看到杏仁。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一颗杏仁", "label": "量词"}, {"form": "甜杏仁", "label": "复合"}], "register": "中性", "sense_fingerprint": "杏仁：杏核里的种子，可食用或入药", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43fcd651-f37e-4c54-87ee-af7602635d98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13812, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杏仁", "is_correct": true, "explanation": "杏仁：杏核里的种子，可食用或入药。"}, {"text": "行人", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，行人指步行的人。"}, {"text": "新人", "is_correct": false, "explanation": "xīn（第一声）与 xìng 的韵尾（-n 与 -ng）和声调都不同，新人指新加入或新婚的人。"}, {"text": "杏林", "is_correct": false, "explanation": "杏林与杏仁只差第二音节（l 与 r 声母不同，声调相同），杏林指杏树林，也比喻医学界。"}], "explanations": {"杏仁": "杏仁：杏核里的种子，可食用或入药。", "行人": "xíng（第二声）与 xìng（第四声）声调不同，行人指步行的人。", "新人": "xīn（第一声）与 xìng 的韵尾（-n 与 -ng）和声调都不同，新人指新加入或新婚的人。", "杏林": "杏林与杏仁只差第二音节（l 与 r 声母不同，声调相同），杏林指杏树林，也比喻医学界。"}, "sentence_index": null, "correct_answer": "杏仁"}, "level_3": {"options": [{"text": "杏仁", "is_correct": true, "explanation": "正确：与“苹果”“咖啡”“可可”并列，都是饮食中的食材。"}, {"text": "显微镜", "is_correct": false, "explanation": "语义：显微镜不是食材，与“饮食结构”的语境不符。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：地铁不能与苹果、咖啡并列作食物。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球不属于饮食结构，无法与前面的食物并列。"}], "explanations": {"杏仁": "正确：与“苹果”“咖啡”“可可”并列，都是饮食中的食材。", "显微镜": "语义：显微镜不是食材，与“饮食结构”的语境不符。", "地铁": "搭配：地铁不能与苹果、咖啡并列作食物。", "足球": "语义：足球不属于饮食结构，无法与前面的食物并列。"}, "sentence_index": 0, "correct_answer": "杏仁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶晒的杏仁软软的，酸酸甜甜，我最爱吃。", "explanation": "这里应该用〈杏干〉。杏仁是硬的种子；晒过后软软甜甜的果肉要说杏干。"}, {"text": "这棵杏仁长得很高，每年春天都开满白花。", "explanation": "这里应该用〈杏树〉。杏仁是种子，不会长成高树，也不会开花。"}, {"text": "我吃完杏子，把杏仁扔进了垃圾桶，嫌它又硬又大。", "explanation": "这里应该用〈杏核〉。杏核是包着杏仁的硬壳，又硬又大要说杏核；杏仁是核里的种子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杏仁", "is_correct": true, "explanation": "正确：“对……过敏，一吃就会难受”的对象应是可食用的东西。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能吃，“一吃就会难受”与它的性质相悖。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“一吃”要求对象可食用，钢琴不能与之搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能食用，与“一吃就会难受”的语境矛盾。"}], "explanations": {"杏仁": "正确：“对……过敏，一吃就会难受”的对象应是可食用的东西。", "汽车": "语义：汽车不能吃，“一吃就会难受”与它的性质相悖。", "钢琴": "搭配：“一吃”要求对象可食用，钢琴不能与之搭配。", "石头": "语义：石头不能食用，与“一吃就会难受”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "杏仁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "杏仁正在枝头上盛开，香气很浓。", "explanation": "这里应该用〈杏花〉。杏仁是果核里的种子，不会在枝头盛开；枝头盛开、香气浓郁的是杏花。"}, {"text": "这颗杏仁又软又甜，刚从树上长出来。", "explanation": "这里应该用〈杏子〉。软甜、长在树上是果实的特点，杏仁指核里的种子。"}, {"text": "秋天到了，这些杏仁变黄了，可以收回家了。", "explanation": "这里应该用〈杏子〉。变黄和收获是果实的变化，杏仁不会这样变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天吃了一只杏仁。", "corrected_sentence": "我昨天吃了一颗杏仁。", "error_description": "错误形式：“吃了一只杏仁”；正确形式：“吃了一颗杏仁”。杏仁的量词应用“颗”，“只”一般用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈在蛋糕里放了一只杏仁。", "corrected_sentence": "妈妈在蛋糕里放了一颗杏仁。", "error_description": "错误形式：“一只杏仁”；正确形式：“一颗杏仁”。“只”一般用于动物，杏仁的量词应用“颗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3554da6b-4304-4a72-a8b9-2df7fb47d9ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
