INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13813, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蓝莓是一种浆果，果实呈蓝色或蓝紫色，味道酸甜，富含维生素和抗氧化物质。", "primary_collocate": null, "pronunciation": "lán méi", "ipa": "lan˧˥ mei˧˥", "syllable_count": 2, "sentences": [{"text": "例如，苹果、杏仁和蓝莓等作物，大部分都要靠蜜蜂来帮助繁殖。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这盒蓝莓又酸又甜，我很喜欢。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈早饭给我做了蓝莓面包。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蓝莓是蓝紫色的，里面有很多维生素。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在超市买了一盒新鲜的蓝莓。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把蓝莓放进酸奶里。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友摘下一颗蓝莓放进嘴里。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天农场里的蓝莓熟了，可以去摘。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蓝莓长在小树上，果实小小的。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶常说蓝莓对眼睛好。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一颗蓝莓", "label": "量词"}, {"form": "一盒蓝莓", "label": "量词"}, {"form": "蓝莓酱", "label": "复合"}, {"form": "藍莓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "蓝莓：蓝紫色酸甜的浆果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70f80afb-2f40-4b32-8524-5af00f94cd49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13813, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蓝莓", "is_correct": true, "explanation": "正确：蓝莓是作物，可与苹果、杏仁并列，靠蜜蜂授粉繁殖。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不是作物，不能与苹果、杏仁并列。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“等作物”指农作物，“手机”不能与苹果、杏仁并列作为作物。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是作物，不能靠蜜蜂帮助繁殖。"}], "explanations": {"蓝莓": "正确：蓝莓是作物，可与苹果、杏仁并列，靠蜜蜂授粉繁殖。", "老虎": "语义：老虎是动物，不是作物，不能与苹果、杏仁并列。", "手机": "搭配：“等作物”指农作物，“手机”不能与苹果、杏仁并列作为作物。", "石头": "语义：石头不是作物，不能靠蜜蜂帮助繁殖。"}, "sentence_index": 0, "correct_answer": "蓝莓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只蓝莓。", "explanation": "这里应该用〈颗〉。〈只〉多用于动物，蓝莓是小颗的水果，要说一颗。"}, {"text": "我买了一条蓝莓。", "explanation": "这里应该用〈颗〉或〈盒〉。〈条〉用于细长的东西，蓝莓是颗粒状水果，不能用〈条〉来数。"}, {"text": "我买了一头蓝莓。", "explanation": "这里应该用〈颗〉或〈盒〉。〈头〉用于大型牲畜，不能用来数蓝莓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13813, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蓝莓", "is_correct": true, "explanation": "正确：“小朋友摘下一颗蓝莓放进嘴里”，蓝莓是可以摘下来吃的果实。"}, {"text": "石子", "is_correct": false, "explanation": "搭配：“摘”用于果实、花朵等植物部分，石子不能摘。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是可以摘下来放进嘴里的东西，句子不通。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能摘下来放进嘴里，句子不通。"}], "explanations": {"蓝莓": "正确：“小朋友摘下一颗蓝莓放进嘴里”，蓝莓是可以摘下来吃的果实。", "石子": "搭配：“摘”用于果实、花朵等植物部分，石子不能摘。", "钥匙": "语义：钥匙不是可以摘下来放进嘴里的东西，句子不通。", "书": "语义：书不能摘下来放进嘴里，句子不通。"}, "sentence_index": 6, "correct_answer": "蓝莓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一根蓝莓。", "explanation": "这里应该用〈颗〉。〈根〉用于细长的东西，蓝莓是圆粒的水果，不能用〈根〉。"}, {"text": "花园里种着一座蓝莓。", "explanation": "这里应该用〈丛〉。〈座〉用于山、建筑等大型物体，灌木状的蓝莓应说〈丛〉。"}, {"text": "盘子里放着一张蓝莓。", "explanation": "这里应该用〈颗〉。〈张〉用于纸、桌子等扁平的东西，不能用来数蓝莓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13813, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我洗了一只蓝莓。", "corrected_sentence": "妈妈给我洗了一碗蓝莓。", "error_description": "错误在量词：蓝莓应配〈碗〉这类量词，“一只”用于动物，不能用来数蓝莓。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13813, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小朋友在树下吃了很多蓝莓们。", "corrected_sentence": "小朋友在树下吃了很多蓝莓。", "error_description": "错误在词尾：“们”只加在指人的名词后，蓝莓是事物，不能说“蓝莓们”，应为“很多蓝莓”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
