INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13814, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "根据某些情况，对事情的大小、多少或好坏做出大致的判断。", "primary_collocate": null, "pronunciation": "gū jì", "ipa": "ku˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "科学家估计，全球大约三分之一的粮食生产与蜜蜂授粉有关。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我估计明天会下雨。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师估计这次考试不难。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家估计今年的苹果会很多。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你估计一下这个箱子有多重。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司估计下个月能卖出一万本书。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生估计他三天后就能回家。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们估计参加会议的有五十人。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人估计这座桥一年内可以修好。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他估计错了路上要用的时间。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "估计了", "label": "体标"}, {"form": "估计过", "label": "体标"}], "register": "中性", "sense_fingerprint": "估计：根据情况对大小多少好坏做大致判断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70f80afb-2f40-4b32-8524-5af00f94cd49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13814, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "估计", "is_correct": true, "explanation": "估计（gū jì）是本题要听的词，意思是根据情况做大致判断。"}, {"text": "古迹", "is_correct": false, "explanation": "gǔ（第三声）与 gū（第一声）声调不同，意思是古迹（历史遗留下来的地方）。"}, {"text": "古籍", "is_correct": false, "explanation": "gǔ 与 gū、jí 与 jì 的声调都不同，意思是古代的书籍。"}, {"text": "估价", "is_correct": false, "explanation": "jià 比 jì 多一个韵母 a，意思是估定价格。"}], "explanations": {"估计": "估计（gū jì）是本题要听的词，意思是根据情况做大致判断。", "古迹": "gǔ（第三声）与 gū（第一声）声调不同，意思是古迹（历史遗留下来的地方）。", "古籍": "gǔ 与 gū、jí 与 jì 的声调都不同，意思是古代的书籍。", "估价": "jià 比 jì 多一个韵母 a，意思是估定价格。"}, "sentence_index": null, "correct_answer": "估计"}, "level_3": {"options": [{"text": "估计", "is_correct": true, "explanation": "估计：根据已有研究做出大致判断，符合科学家推断的语气。"}, {"text": "笑", "is_correct": false, "explanation": "语义：“笑”表示情绪反应，无法引出对粮食生产的客观论断。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”表示情绪，与后面的科学结论不相容。"}, {"text": "吹牛", "is_correct": false, "explanation": "语域：“吹牛”是口语且带贬义，不适合用在科学报道中。"}], "explanations": {"估计": "估计：根据已有研究做出大致判断，符合科学家推断的语气。", "笑": "语义：“笑”表示情绪反应，无法引出对粮食生产的客观论断。", "生气": "语义：“生气”表示情绪，与后面的科学结论不相容。", "吹牛": "语域：“吹牛”是口语且带贬义，不适合用在科学报道中。"}, "sentence_index": 0, "correct_answer": "估计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们估计了你的身份，你是李明。", "explanation": "这里应该用〈确认〉。估计只是对情况做大致判断，不能用来表示核实对方的身份。"}, {"text": "他一步一步地估计出了答案。", "explanation": "这里应该用〈计算〉。估计只是大致判断，不能用来一步一步地精确推算出答案，那要说“计算”。"}, {"text": "法院估计了这个案子的判决，结果是三年有期徒刑。", "explanation": "这里应该用〈作出〉。估计只是对情况的大致推断，不能用于法院的正式判决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "估计", "is_correct": true, "explanation": "估计：根据病情做出大致判断，与“三天后就能回家”的预测相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”指取笑别人，与医生对病人康复的正常判断不相符。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：“嫉妒”是对他人的忌恨，医生对病人出院的判断不能用它。"}, {"text": "叹息", "is_correct": false, "explanation": "语域：“叹息”偏书面抒情，用在医生的病情判断中不自然。"}], "explanations": {"估计": "估计：根据病情做出大致判断，与“三天后就能回家”的预测相符。", "嘲笑": "语义：“嘲笑”指取笑别人，与医生对病人康复的正常判断不相符。", "嫉妒": "语义：“嫉妒”是对他人的忌恨，医生对病人出院的判断不能用它。", "叹息": "语域：“叹息”偏书面抒情，用在医生的病情判断中不自然。"}, "sentence_index": 6, "correct_answer": "估计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会计估计了账目，确认没有错误。", "explanation": "这里应该用〈核对〉。估计只是大致判断，不能用来核实账目是否正确。"}, {"text": "实验估计了这个理论，证明它是对的。", "explanation": "这里应该用〈证实〉。估计只是推测，不能用来验证理论是否正确。"}, {"text": "老师估计了我的作业，然后给了我九十分。", "explanation": "这里应该用〈批改〉。估计只是大致判断，不能代替逐题批改作业后打分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我估计得这次比赛会很激烈。", "corrected_sentence": "我估计这次比赛会很激烈。", "error_description": "错误：在“估计”后面多加了“得”。“估计”后直接接小句，不能接补语标记“得”；正确说法是“我估计这次比赛会很激烈。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她估计了错比赛结束的时间。", "corrected_sentence": "她估计错了比赛结束的时间。", "error_description": "错误：语序不对。“错”是“估计”的结果补语，应紧跟在“估计”后面，说“估计错了”；“了”要放在“错”后面，不能说“估计了错”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13816, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下跌", "is_correct": true, "explanation": "下跌与上涨是反义词，指价格、水位等由高到低地变化。"}, {"text": "批准", "is_correct": false, "explanation": "批准指同意或认可，与上涨没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步指慢慢地走，与上涨没有反义关系。"}, {"text": "完成", "is_correct": false, "explanation": "完成指做完某件事，与上涨没有反义关系。"}], "correct_answer": "下跌", "explanations": {"下跌": "下跌与上涨是反义词，指价格、水位等由高到低地变化。", "批准": "批准指同意或认可，与上涨没有反义关系。", "散步": "散步指慢慢地走，与上涨没有反义关系。", "完成": "完成指做完某件事，与上涨没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13816, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下跌", "is_correct": true, "explanation": "下跌与上涨是反义词，指价格、水位等由高到低地变化。"}, {"text": "参观", "is_correct": false, "explanation": "参观指到某处去看，与上涨没有反义关系。"}, {"text": "承认", "is_correct": false, "explanation": "承认指认可某个事实，与上涨没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运指把东西从一处移到另一处，与上涨没有反义关系。"}], "correct_answer": "下跌", "explanations": {"下跌": "下跌与上涨是反义词，指价格、水位等由高到低地变化。", "参观": "参观指到某处去看，与上涨没有反义关系。", "承认": "承认指认可某个事实，与上涨没有反义关系。", "搬运": "搬运指把东西从一处移到另一处，与上涨没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13816, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指价格、水位、数量等从低到高发生变化。", "primary_collocate": null, "pronunciation": "shàng zhǎng", "ipa": "ʂɑŋ˥˩ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "如果蜜蜂变少，苹果的价格可能会上涨。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "最近牛奶的价格上涨了。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下大雨以后，河水一直在上涨。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气冷了，菜价又上涨了。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的房价每年都在上涨。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年夏天，海水的水位上涨得很快。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为天气不好，蔬菜的价格上涨了不少。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说下个月汽油价格还会上涨。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工资没有上涨，但是东西越来越贵。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家说，明年的粮食价格可能继续上涨。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "上涨了", "label": "完成体"}, {"form": "上涨过", "label": "经历体"}, {"form": "上漲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "价格、水位、数量等从低变高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70f80afb-2f40-4b32-8524-5af00f94cd49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上涨", "is_correct": true, "explanation": "上涨：价格升高，与“蜜蜂变少、供应减少”的因果相符。"}, {"text": "下跌", "is_correct": false, "explanation": "语义：蜜蜂变少会使供应减少、价格上涨，价格下跌与此因果方向相反。"}, {"text": "降低", "is_correct": false, "explanation": "语义：“降低”与蜜蜂变少导致价格升高的因果方向相反。"}, {"text": "停止", "is_correct": false, "explanation": "搭配：“停止”后面要接动作，不能直接用在“价格”上作谓语。"}], "explanations": {"上涨": "上涨：价格升高，与“蜜蜂变少、供应减少”的因果相符。", "下跌": "语义：蜜蜂变少会使供应减少、价格上涨，价格下跌与此因果方向相反。", "降低": "语义：“降低”与蜜蜂变少导致价格升高的因果方向相反。", "停止": "搭配：“停止”后面要接动作，不能直接用在“价格”上作谓语。"}, "sentence_index": 0, "correct_answer": "上涨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身高上涨了两厘米，比去年高了不少。", "explanation": "这里应该用〈长高〉。上涨用于价格、水位、数量等，身高变高要说“长高”，不能用“上涨”。"}, {"text": "他的英语水平上涨了很多，这次考试得了满分。", "explanation": "这里应该用〈提高〉。上涨指价格、水位等的升高，水平的进步要说“提高”。"}, {"text": "这家公司的业务范围上涨了很多，现在覆盖全国。", "explanation": "这里应该用〈扩展〉。上涨用于价格、水位、数量等，业务范围变大要说“扩展”，不能用“上涨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上涨", "is_correct": true, "explanation": "上涨：价格升高，与“因为天气不好”的因果相符。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体的反应，不能用来描述蔬菜价格的变化。"}, {"text": "吹牛", "is_correct": false, "explanation": "语域：“吹牛”是口语且带贬义，指人说大话，不能用于价格。"}, {"text": "流行", "is_correct": false, "explanation": "语义：“流行”指事物受欢迎，不是价格的变化。"}], "explanations": {"上涨": "上涨：价格升高，与“因为天气不好”的因果相符。", "咳嗽": "语义：“咳嗽”是身体的反应，不能用来描述蔬菜价格的变化。", "吹牛": "语域：“吹牛”是口语且带贬义，指人说大话，不能用于价格。", "流行": "语义：“流行”指事物受欢迎，不是价格的变化。"}, "sentence_index": 6, "correct_answer": "上涨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的规模上涨了很多，现在是全国最大的城市之一。", "explanation": "这里应该用〈扩大〉。上涨用于价格、水位，城市规模变大要说“扩大”。"}, {"text": "这条路上涨了两公里，比原来长多了。", "explanation": "这里应该用〈延长〉。上涨不能用于道路的长度，道路变长要说“延长”。"}, {"text": "我们之间的差距上涨了，需要继续努力。", "explanation": "这里应该用〈缩小〉。上涨不能用于差距，差距变小要说“缩小”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "猪肉的价格上涨了很快。", "corrected_sentence": "猪肉的价格上涨得很快。", "error_description": "错误：“上涨”后应接补语“得”引出“很快”，不能用“了”。正确说法是“猪肉的价格上涨得很快。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月的房租上涨了到三千块。", "corrected_sentence": "这个月的房租上涨到了三千块。", "error_description": "错误：“到”是“上涨”的补语，应紧跟在“上涨”后面，“了”放在“到”后面；“上涨了到”不能说。正确说法是“这个月的房租上涨到了三千块。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13817, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明亮", "is_correct": false, "explanation": "不构成反义：“明亮”形容光线，与数量多少无关。"}, {"text": "众多", "is_correct": true, "explanation": "“众多”表示数量很多，与“稀少”在数量上相对。"}, {"text": "寒冷", "is_correct": false, "explanation": "不构成反义：“寒冷”形容温度，与数量多少无关。"}, {"text": "柔软", "is_correct": false, "explanation": "不构成反义：“柔软”形容质地，与数量多少无关。"}], "correct_answer": "众多", "explanations": {"明亮": "不构成反义：“明亮”形容光线，与数量多少无关。", "众多": "“众多”表示数量很多，与“稀少”在数量上相对。", "寒冷": "不构成反义：“寒冷”形容温度，与数量多少无关。", "柔软": "不构成反义：“柔软”形容质地，与数量多少无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13817, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坚硬", "is_correct": false, "explanation": "不构成反义：“坚硬”形容质地，与数量多少无关。"}, {"text": "清澈", "is_correct": false, "explanation": "不构成反义：“清澈”形容透明，与数量多少无关。"}, {"text": "众多", "is_correct": true, "explanation": "“众多”表示数量很多，与“稀少”在数量上相对。"}, {"text": "高大", "is_correct": false, "explanation": "不构成反义：“高大”形容体形或规模，与数量多少无关。"}], "correct_answer": "众多", "explanations": {"坚硬": "不构成反义：“坚硬”形容质地，与数量多少无关。", "清澈": "不构成反义：“清澈”形容透明，与数量多少无关。", "众多": "“众多”表示数量很多，与“稀少”在数量上相对。", "高大": "不构成反义：“高大”形容体形或规模，与数量多少无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13817, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容数量很少，不常见。", "primary_collocate": null, "pronunciation": "xī shǎo", "ipa": "ɕi˥ ʂɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这意味着，如果我们失去太多蜜蜂，食物的价格可能会上涨，有些食物甚至可能变得稀少。", "target_word": "稀少", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种花很稀少，一般的店里买不到。", "target_word": "稀少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙漠里的雨水非常稀少。", "target_word": "稀少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个地方的人口很稀少。", "target_word": "稀少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个湖里的鱼越来越稀少了。", "target_word": "稀少", "complexity_tier": "T3", "furigana": "zhè gè hú lǐ de yú yuè lái yuè xī shǎo le", "sentence_source": "generated"}, {"text": "冬天山上的草木变得稀少了。", "target_word": "稀少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种树现在很稀少，只剩几棵了。", "target_word": "稀少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的野生鸟类十分稀少。", "target_word": "稀少", "complexity_tier": "T3", "furigana": "zhè lǐ de yě shēng niǎo lèi shí fēn xī shǎo", "sentence_source": "generated"}, {"text": "北方的冬天，雨水比较稀少。", "target_word": "稀少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种旧版硬币的数量很稀少。", "target_word": "稀少", "complexity_tier": "T3", "furigana": "zhè zhǒng jiù bǎn yìng bì de shù liàng hěn xī shǎo", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量很少、不常见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70f80afb-2f40-4b32-8524-5af00f94cd49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13817, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "充足", "is_correct": false, "explanation": "语义：“充足”表示数量够多，与前文“失去太多蜜蜂、食物减少”的推论相反。"}, {"text": "稀少", "is_correct": true, "explanation": "“稀少”指数量很少、不常见，与前文“失去蜜蜂，食物可能变少”的推论相符。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体形或规模大，不用来说食物“变得高大”。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”与前文“食物的价格可能会上涨”矛盾，不合语境。"}], "explanations": {"充足": "语义：“充足”表示数量够多，与前文“失去太多蜜蜂、食物减少”的推论相反。", "稀少": "“稀少”指数量很少、不常见，与前文“失去蜜蜂，食物可能变少”的推论相符。", "高大": "搭配：“高大”形容体形或规模大，不用来说食物“变得高大”。", "便宜": "语义：“便宜”与前文“食物的价格可能会上涨”矛盾，不合语境。"}, "sentence_index": 0, "correct_answer": "稀少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "高原上的空气很稀少。", "explanation": "这里应该用〈稀薄〉。稀少说的是数量少，空气、液体的浓度低要用稀薄。"}, {"text": "他的身高很稀少。", "explanation": "这里误用了〈稀少〉的“数量少”义项。身高说的是高矮，应该用〈矮〉这样的词来描述。"}, {"text": "这杯水的温度很稀少。", "explanation": "这里误用了〈稀少〉的“数量少”义项。温度说的是高低，应该用〈低〉或〈高〉来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13817, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辽阔", "is_correct": false, "explanation": "搭配：“辽阔”形容地域或空间广大，不用来形容一棵树的数量状态。"}, {"text": "茂盛", "is_correct": false, "explanation": "语义：“茂盛”指长得旺盛、数量多，与“只剩几棵了”矛盾。"}, {"text": "稀少", "is_correct": true, "explanation": "“稀少”指数量很少，与“只剩几棵了”相符。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或眼睛等透明，不用于描述树。"}], "explanations": {"辽阔": "搭配：“辽阔”形容地域或空间广大，不用来形容一棵树的数量状态。", "茂盛": "语义：“茂盛”指长得旺盛、数量多，与“只剩几棵了”矛盾。", "稀少": "“稀少”指数量很少，与“只剩几棵了”相符。", "清澈": "搭配：“清澈”形容水或眼睛等透明，不用于描述树。"}, "sentence_index": 6, "correct_answer": "稀少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗粥很稀少。", "explanation": "这里应该用〈稀薄〉。稀少指数量少；粥的浓度低要用稀薄。"}, {"text": "他的年龄很稀少。", "explanation": "这里误用了〈稀少〉的“数量少”义项。年龄说的是大小，应该用〈大〉或〈小〉来描述。"}, {"text": "这个湖的深度很稀少。", "explanation": "这里误用了〈稀少〉的“数量少”义项。深度说的是深浅，应该用〈浅〉来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13817, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这条街上的饭馆弄稀少了。", "corrected_sentence": "我把这条街上的饭馆弄得稀少了。", "error_description": "错误在于补语标记缺失：“弄”后接性质形容词作结果补语时须加“得”，应说“弄得稀少了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13817, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个村子的老人稀少得。", "corrected_sentence": "这个村子的老人稀少得很。", "error_description": "错误在于程度补语：“稀少得”后面必须接“很”等程度补语，少了“很”，句子语意不完整。应说“稀少得很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
