INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13819, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为了见到或得到某人或某物而付出努力。", "primary_collocate": null, "pronunciation": "xún zhǎo", "ipa": "ɕyn˧˥ ʈʂɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "许多研究正在寻找原因，可能包括农药的使用、栖息地的减少以及气候变化。", "target_word": "寻找", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "小狗走丢了，孩子们到处寻找。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天都在寻找一份新工作。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察正在寻找那个丢失的孩子。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一直在寻找回家的路。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她寻找了很久，终于找到了钥匙。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多年轻人去大城市寻找机会。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在书包里寻找着那把小钥匙。", "target_word": "寻找", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家们正在寻找新的能源。", "target_word": "寻找", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他寻找过很多地方，都没有看到那只猫。", "target_word": "寻找", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "寻找了", "label": "完成体"}, {"form": "寻找着", "label": "持续体"}, {"form": "寻找过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "努力去找某人或某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70f80afb-2f40-4b32-8524-5af00f94cd49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13819, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丢失", "is_correct": false, "explanation": "语义：“丢失”是失去东西，研究不会把原因丢失，与“正在”后的动作矛盾。"}, {"text": "寻找", "is_correct": true, "explanation": "“寻找”指为了得到某物而努力去找，与“研究正在……原因”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“原因”作宾语。"}, {"text": "帮助", "is_correct": false, "explanation": "配价：“帮助”要求带人作宾语，不能说“帮助原因”。"}], "explanations": {"丢失": "语义：“丢失”是失去东西，研究不会把原因丢失，与“正在”后的动作矛盾。", "寻找": "“寻找”指为了得到某物而努力去找，与“研究正在……原因”的语境相符。", "吃": "搭配：“吃”不能带“原因”作宾语。", "帮助": "配价：“帮助”要求带人作宾语，不能说“帮助原因”。"}, "sentence_index": 0, "correct_answer": "寻找"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他寻找了对老师的感谢。", "explanation": "这里应该用〈表达〉。寻找的对象是能去找到的人或东西，感谢是要表达的情感，应说“表达感谢”。"}, {"text": "他寻找了一个小时的头疼。", "explanation": "这里误把〈寻找〉当成“感受”来用。寻找的对象要是能找到的人或东西；头疼是身体感受，应说“感到”或“忍受”。"}, {"text": "妈妈寻找了我的生日。", "explanation": "这里应该用〈庆祝〉。寻找的对象是能找到的人或东西，生日是要庆祝的日子，应说“庆祝生日”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13819, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是不再努力，与“去大城市”的目的矛盾。"}, {"text": "寻找", "is_correct": true, "explanation": "“寻找”指为了得到而努力去找，与“去大城市”的语境相符。"}, {"text": "抚养", "is_correct": false, "explanation": "搭配：“抚养”的宾语是人，不能说“抚养机会”。"}, {"text": "错过", "is_correct": false, "explanation": "语义：“错过”是失去时机，与“去大城市”的目的矛盾。"}], "explanations": {"放弃": "语义：“放弃”是不再努力，与“去大城市”的目的矛盾。", "寻找": "“寻找”指为了得到而努力去找，与“去大城市”的语境相符。", "抚养": "搭配：“抚养”的宾语是人，不能说“抚养机会”。", "错过": "语义：“错过”是失去时机，与“去大城市”的目的矛盾。"}, "sentence_index": 6, "correct_answer": "寻找"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士寻找了病人的体温。", "explanation": "这里应该用〈量〉。寻找的对象是能找到的人或东西，体温要用“量”来测。"}, {"text": "天空寻找了一场大雨。", "explanation": "这里应该用〈下〉。寻找的对象是人或东西，大雨是天气现象，应说“下大雨”。"}, {"text": "我寻找了一个暑假。", "explanation": "这里应该用〈度过〉。寻找的对象是人或东西，暑假是时间，应说“度过一个暑假”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13819, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在桌子上寻找了着遥控器。", "corrected_sentence": "他在桌子上寻找着遥控器。", "error_description": "错误在于体标叠加：持续体只用“着”，“了”和“着”不能同时放在动词“寻找”后，应说“寻找着遥控器”，不能说“寻找了着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13819, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在书架上寻找得那本字典。", "corrected_sentence": "他在书架上寻找那本字典。", "error_description": "错误在于多加了“得”：“寻找”后直接带宾语“那本字典”，不用“得”，应说“在书架上寻找那本字典”，不能说“寻找得那本字典”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e73d10c-acf8-41d7-97ef-a3efe7aef2c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
