INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13823, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用于防治农业病虫害、杂草等的化学合成物质。", "primary_collocate": null, "pronunciation": "huà xué nóng yào", "ipa": "xua˥˩ ɕɥe˧˥ noŋ˧˥ jɑʊ˥˩", "syllable_count": 4, "sentences": [{"text": "为了保护蜜蜂，一些农民开始减少使用化学农药，转而采用更环保的种植方式。", "target_word": "化学农药", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "农民在地里喷了化学农药。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "化学农药能杀死害虫，也会伤到蜜蜂。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种化学农药对人不太好。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想再用化学农药种菜了。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买化学农药的时候要看清楚说明。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用了化学农药的菜，要多洗几次。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店卖种子，也卖化学农药。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子不能碰化学农药，很危险。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "化学农药用得太多，河水也会变脏。", "target_word": "化学农药", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "农药", "label": "简称"}, {"form": "种", "label": "量词"}, {"form": "瓶", "label": "量词"}], "register": "中性", "sense_fingerprint": "农业中用来防治病虫害和杂草的化学合成药剂，可喷洒使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b8871e-37c6-4207-918f-20fe6c25658f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "化学农药", "is_correct": true, "explanation": "正确：减少使用它，转而采用更环保的种植方式，与“保护蜜蜂”的语境一致。"}, {"text": "有机肥", "is_correct": false, "explanation": "语义：有机肥本身也是环保的，减少使用它不能“转而采用更环保的种植方式”，与语境矛盾。"}, {"text": "太阳能", "is_correct": false, "explanation": "语义：太阳能是清洁能源，减少使用它与“更环保”的逻辑相反。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：“雨水”一般不说“减少使用”，与“减少使用”搭配不当。"}], "explanations": {"化学农药": "正确：减少使用它，转而采用更环保的种植方式，与“保护蜜蜂”的语境一致。", "有机肥": "语义：有机肥本身也是环保的，减少使用它不能“转而采用更环保的种植方式”，与语境矛盾。", "太阳能": "语义：太阳能是清洁能源，减少使用它与“更环保”的逻辑相反。", "雨水": "搭配：“雨水”一般不说“减少使用”，与“减少使用”搭配不当。"}, "sentence_index": 0, "correct_answer": "化学农药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只化学农药。", "explanation": "这里应该用〈瓶〉或〈袋〉。农药多以瓶、袋计量，“只”是动物的量词。"}, {"text": "农民就用化学农药给庄稼施肥。", "explanation": "这里应该用〈化肥〉。化学农药是用来杀虫、除草的，不能用来施肥。"}, {"text": "医生用化学农药治感冒。", "explanation": "这里应该用〈感冒药〉。这里的“化学农药”指杀虫除草的药剂，不能用于治病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "化学农药", "is_correct": true, "explanation": "正确：用过它的菜要多洗几次，与“用了……的菜”的语境一致。"}, {"text": "毒药", "is_correct": false, "explanation": "语义：“毒药”的毒性远超农药，用过毒药的菜不是多洗几次就能处理，与语境不符。"}, {"text": "冰块", "is_correct": false, "explanation": "搭配：“用了冰块的菜”不是常见说法，“用”与“冰块”搭配不当。"}, {"text": "柴油", "is_correct": false, "explanation": "语义：柴油不能用于烹饪或处理蔬菜，与“菜”的语境矛盾。"}], "explanations": {"化学农药": "正确：用过它的菜要多洗几次，与“用了……的菜”的语境一致。", "毒药": "语义：“毒药”的毒性远超农药，用过毒药的菜不是多洗几次就能处理，与语境不符。", "冰块": "搭配：“用了冰块的菜”不是常见说法，“用”与“冰块”搭配不当。", "柴油": "语义：柴油不能用于烹饪或处理蔬菜，与“菜”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "化学农药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用化学农药给孩子洗澡。", "explanation": "这里应该用〈沐浴露〉。农药不能用于人体清洁，这里应该用专门的清洁用品。"}, {"text": "化学农药可以当作调料放进汤里。", "explanation": "这里应该用〈食盐〉。化学农药不是食用物质，不能当作调料。"}, {"text": "他用化学农药做饼干。", "explanation": "这里应该用〈面粉〉。化学农药不能用来做食物，做饼干要用面粉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民喷完着化学农药。", "corrected_sentence": "农民喷完了化学农药。", "error_description": "错误：“完”表示动作结束，后面要用“了”，不能用“着”，写成“喷完着”不对。正确：“农民喷完了化学农药”，“了”表示动作已经完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只化学农药太贵了。", "corrected_sentence": "这瓶化学农药太贵了。", "error_description": "错误：“只”是动物的量词，用来修饰“化学农药”不对。正确：农药多以瓶、袋计量，应说“这瓶化学农药”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13824, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13824, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13824, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "养蜂是指人工饲养蜜蜂，以获取蜂蜜、蜂王浆等产品。", "primary_collocate": null, "pronunciation": "yǎng fēng", "ipa": "jɑŋ˨˩˦ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "城市里也有人开始在屋顶或阳台养蜂。", "target_word": "养蜂", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他退休以后，在山上养蜂。", "target_word": "养蜂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "想养蜂，要先买蜂箱。", "target_word": "养蜂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在花园里养蜂，每年都能收到蜂蜜。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "养蜂的人要穿特别的衣服。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷养蜂已经十年了。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天花开了，农民开始养蜂。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在农村养蜂，卖蜂蜜赚钱。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想学养蜂，就不能怕蜜蜂。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个山村，很多人靠养蜂生活。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "养过蜂", "label": "体标"}, {"form": "养蜂人", "label": "复合"}, {"form": "養蜂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人工饲养蜜蜂以获取蜂蜜等产品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbaaaf73-74c4-4217-9399-ec60d52059ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骑马", "is_correct": false, "explanation": "语义：屋顶和阳台上不能骑马，与“城市里也有人开始”的语境不合。"}, {"text": "滑冰", "is_correct": false, "explanation": "语义：屋顶和阳台上不能滑冰，与“城市里也有人开始”的语境不合。"}, {"text": "冬眠", "is_correct": false, "explanation": "语义：冬眠是动物的习性，人不会冬眠，“开始在屋顶或阳台冬眠”与句意不合。"}, {"text": "养蜂", "is_correct": true, "explanation": "正确。“养蜂”指人工饲养蜜蜂，屋顶和阳台可以放置蜂箱，与句意相合。"}], "explanations": {"骑马": "语义：屋顶和阳台上不能骑马，与“城市里也有人开始”的语境不合。", "滑冰": "语义：屋顶和阳台上不能滑冰，与“城市里也有人开始”的语境不合。", "冬眠": "语义：冬眠是动物的习性，人不会冬眠，“开始在屋顶或阳台冬眠”与句意不合。", "养蜂": "正确。“养蜂”指人工饲养蜜蜂，屋顶和阳台可以放置蜂箱，与句意相合。"}, "sentence_index": 0, "correct_answer": "养蜂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在阳台养蜂，每天浇水。", "explanation": "这里应该用〈养花〉。养蜂是饲养蜜蜂，每天浇水是养花的做法。"}, {"text": "他在家里养蜂，每周换一次水。", "explanation": "这里应该用〈养鱼〉。养鱼要定期换水；养蜂是饲养蜜蜂，不需要换水。"}, {"text": "他在农村养蜂，每天都去收鸡蛋。", "explanation": "这里应该用〈养鸡〉。收鸡蛋要靠养鸡，养蜂得到的是蜂蜜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冬眠", "is_correct": false, "explanation": "语义：冬眠是动物的习性，“农民开始冬眠”与“春天花开了”的语境不合。"}, {"text": "滑雪", "is_correct": false, "explanation": "语义：春天花开的季节不适合滑雪，“农民开始滑雪”与句中季节矛盾。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”需要带宾语（修理什么），“农民开始修理”缺少宾语，句子不完整。"}, {"text": "养蜂", "is_correct": true, "explanation": "正确。“春天花开了，农民开始养蜂”，花开后正适合养蜂采蜜，句意通顺。"}], "explanations": {"冬眠": "语义：冬眠是动物的习性，“农民开始冬眠”与“春天花开了”的语境不合。", "滑雪": "语义：春天花开的季节不适合滑雪，“农民开始滑雪”与句中季节矛盾。", "修理": "配价：“修理”需要带宾语（修理什么），“农民开始修理”缺少宾语，句子不完整。", "养蜂": "正确。“春天花开了，农民开始养蜂”，花开后正适合养蜂采蜜，句意通顺。"}, "sentence_index": 6, "correct_answer": "养蜂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在这个山村，很多蜜蜂靠养蜂生活。", "explanation": "这里误用了〈养蜂〉的施事：养蜂须由人来做，蜜蜂自己做的是〈采蜜〉，不能说养蜂。"}, {"text": "在这个山村，很多鱼靠养蜂生活。", "explanation": "这里应该用〈养鱼〉。养蜂要由人来做，鱼不能养蜂。"}, {"text": "在这个山村，这块石头靠养蜂生活。", "explanation": "“石头”不能靠养蜂生活；养蜂的施事只能是人，无生命的石头无法充当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他养蜂了三年，现在很会照顾蜜蜂。", "corrected_sentence": "他养了三年蜂，现在很会照顾蜜蜂。", "error_description": "离合词拆分错误：离合词“养蜂”的“了”和时量词“三年”应插在“养”与“蜂”之间，应说“养了三年蜂”，不能说“养蜂了三年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他养蜂得很好。", "corrected_sentence": "他养蜂养得很好。", "error_description": "补语错误：动词“养蜂”后接程度补语“得很好”时，动词要重复，应说“养蜂养得很好”，不能说“养蜂得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe460a13-b349-4f9d-a31a-e0d890935749') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
