INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13827, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "利用生态学原理，发展可持续的农业模式。", "primary_collocate": null, "pronunciation": "shēng tài nóng yè", "ipa": "ʂɤŋ˥ tʰaɪ˥˩ nʊŋ˧˥ jɛ˥˩", "syllable_count": 4, "sentences": [{"text": "我们每个人都可以通过种植花草、支持生态农业来帮助蜜蜂。", "target_word": "生态农业", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "生态农业不用太多化肥。", "target_word": "生态农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子发展生态农业已经十年了。", "target_word": "生态农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生态农业能保护土地和水。", "target_word": "生态农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想学习生态农业的新方法。", "target_word": "生态农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府鼓励农民搞生态农业。", "target_word": "生态农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生态农业的产品更健康，价格也高一些。", "target_word": "生态农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们去农场了解了生态农业。", "target_word": "生态农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发展生态农业需要时间，也需要钱。", "target_word": "生态农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她大学学的专业是生态农业。", "target_word": "生态农业", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "生態農業", "label": "繁体"}, {"form": "生态农业园", "label": "复合"}], "register": "中性", "sense_fingerprint": "利用生态学原理的可持续农业模式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '048066ef-e0c6-43cd-971f-4df52a6c6dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13827, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工业化农业", "is_correct": false, "explanation": "语义：大量使用化肥和农药会伤害蜜蜂，与“帮助蜜蜂”的句意相反。"}, {"text": "生态农业", "is_correct": true, "explanation": "正确：与“种植花草”“帮助蜜蜂”的语境一致，是值得支持的农业方式。"}, {"text": "城市交通", "is_correct": false, "explanation": "语义：城市交通与种植花草、帮助蜜蜂没有关系，不能用来帮助蜜蜂。"}, {"text": "农活", "is_correct": false, "explanation": "搭配：“支持”多接项目、事业，“农活”指具体的劳动，一般不说“支持农活”。"}], "explanations": {"工业化农业": "语义：大量使用化肥和农药会伤害蜜蜂，与“帮助蜜蜂”的句意相反。", "生态农业": "正确：与“种植花草”“帮助蜜蜂”的语境一致，是值得支持的农业方式。", "城市交通": "语义：城市交通与种植花草、帮助蜜蜂没有关系，不能用来帮助蜜蜂。", "农活": "搭配：“支持”多接项目、事业，“农活”指具体的劳动，一般不说“支持农活”。"}, "sentence_index": 0, "correct_answer": "生态农业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民用生态农业去锄地。", "explanation": "这里应该用〈锄头〉。生态农业指种地的方式，不是可以用来锄地的工具，锄地要用锄头。"}, {"text": "超市里摆满了生态农业。", "explanation": "这里应该用〈有机食品〉。生态农业是生产方式，不是可以摆在超市货架上的商品。"}, {"text": "我每天早上喝一杯生态农业。", "explanation": "这里应该用〈果汁〉。生态农业指种地的方式，不是饮料，不能用“喝”来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13827, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "农药", "is_correct": false, "explanation": "语义：农药是有毒的化学品，不可能使产品“更健康”。"}, {"text": "生态农业", "is_correct": true, "explanation": "正确：指利用生态原理的农业，其产品更健康，价格也较高，符合句意。"}, {"text": "农业机械", "is_correct": false, "explanation": "搭配：“产品”在这里指可食用的农产品，农业机械不是食品，不说“机械的产品更健康”。"}, {"text": "化工厂", "is_correct": false, "explanation": "语义：化工厂的产品多是工业化学品，与“更健康”的评价正好相反。"}], "explanations": {"农药": "语义：农药是有毒的化学品，不可能使产品“更健康”。", "生态农业": "正确：指利用生态原理的农业，其产品更健康，价格也较高，符合句意。", "农业机械": "搭配：“产品”在这里指可食用的农产品，农业机械不是食品，不说“机械的产品更健康”。", "化工厂": "语义：化工厂的产品多是工业化学品，与“更健康”的评价正好相反。"}, "sentence_index": 6, "correct_answer": "生态农业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他开着生态农业去上班。", "explanation": "这里应该用〈汽车〉。生态农业指种地的方式，不是交通工具，不能开着去上班。"}, {"text": "这块地施了很多生态农业。", "explanation": "这里应该用〈有机肥〉。生态农业是一种农业方式，不能像肥料一样“施”在地里。"}, {"text": "农民给庄稼喷洒了生态农业。", "explanation": "这里应该用〈农药〉。生态农业指一种种植方式，不是可以喷洒的物质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13827, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在村里推广一只生态农业。", "corrected_sentence": "他们在村里推广一种生态农业。", "error_description": "量词错误：“生态农业”是抽象的种植方式，应该用量词“种”。“只”多用于动物或单个物件，不能用来修饰这类抽象的方式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13827, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们用生态农业地方法种菜。", "corrected_sentence": "他们用生态农业的方法种菜。", "error_description": "结构助词错误：“生态农业”修饰“方法”时应该用“的”，写成“地”是错误的。“地”用来修饰动词，这里用错后，修饰关系就不对了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
