INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13829, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示程度或范围超出所提到的，不仅限于。", "primary_collocate": null, "pronunciation": "yuǎn bù zhǐ", "ipa": "ɥɛn˨˩˦ pu˥˩ ʈʂɨ˨˩˦", "syllable_count": 3, "sentences": [{"text": "在地球错综复杂的生态系统中，蜜蜂作为最为关键的授粉昆虫之一，其存在远不止于生产蜂蜜这一表层价值。", "target_word": "远不止", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他的收入远不止这些，还有很多别的来源。", "target_word": "远不止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的人口远不止一千万。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学好汉语远不止是记单词。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们遇到的困难远不止这一个。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "参加比赛的人远不止二十个。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次旅行花的钱远不止一万块。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "健康远不止是不生病，还包括心情好。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店卖的东西远不止衣服，还有鞋和包。", "target_word": "远不止", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教给我们的远不止知识。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "遠不止", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数量、范围或程度大大超出所说的，不只是所提到的那些", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d3adfa-528b-4034-a494-9783488f8294') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13829, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仅仅", "is_correct": false, "explanation": "语义：“仅仅”表示限定范围，与后文“远不止于表层价值”的超出之义相反。"}, {"text": "远不止", "is_correct": true, "explanation": "“远不止”表示超出范围，与“于生产蜂蜜这一表层价值”的对比相合。"}, {"text": "不过", "is_correct": false, "explanation": "配价：“不过”不能这样带“于”引出的范围，结构不成立。"}, {"text": "不免", "is_correct": false, "explanation": "搭配：“不免”表示难以避免，与“存在……于生产蜂蜜”的说法搭配不当。"}], "explanations": {"仅仅": "语义：“仅仅”表示限定范围，与后文“远不止于表层价值”的超出之义相反。", "远不止": "“远不止”表示超出范围，与“于生产蜂蜜这一表层价值”的对比相合。", "不过": "配价：“不过”不能这样带“于”引出的范围，结构不成立。", "不免": "搭配：“不免”表示难以避免，与“存在……于生产蜂蜜”的说法搭配不当。"}, "sentence_index": 0, "correct_answer": "远不止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家小店的规模远不止大型商场。", "explanation": "这里应该用〈远不及〉。远不止表示超出，说小店比不上商场要用远不及。"}, {"text": "这个方案远不止完美，还需要改进。", "explanation": "这里应该用〈远非〉。“完美”已是最高状态，不能说远不止完美；说离完美还远要用远非。"}, {"text": "我的存款远不止够买房，还差得很远。", "explanation": "用法不当：远不止表示超出，“远不止够买房”与“还差得很远”矛盾；说不够要用远远不够。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13829, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很", "is_correct": false, "explanation": "搭配：“很”是程度副词，不能直接限定“一万块”这样的数量短语。"}, {"text": "远不止", "is_correct": true, "explanation": "“远不止”表示超过一万块，正好说明花费超出预期。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”是程度副词，不能直接修饰“一万块”这样的数额。"}, {"text": "也", "is_correct": false, "explanation": "语义：“也”表示并列，与花费数额的超出判断无关，句子意思不通。"}], "explanations": {"很": "搭配：“很”是程度副词，不能直接限定“一万块”这样的数量短语。", "远不止": "“远不止”表示超过一万块，正好说明花费超出预期。", "非常": "搭配：“非常”是程度副词，不能直接修饰“一万块”这样的数额。", "也": "语义：“也”表示并列，与花费数额的超出判断无关，句子意思不通。"}, "sentence_index": 6, "correct_answer": "远不止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家离学校远不止一公里，走路五分钟就到了。", "explanation": "这里应该用〈不远〉。远不止表示超出所提到的距离，说距离很近应该用不远；与“走路五分钟就到”也矛盾。"}, {"text": "我的速度远不止他的，我只能慢慢游。", "explanation": "这里应该用〈远不及〉。远不止表示超出所提到的程度，说自己比别人慢要用远不及；与“只能慢慢游”也矛盾。"}, {"text": "这个想法远不止简单，大家都很快就理解了。", "explanation": "这里应该用〈很〉。远不止表示超出所说的程度；想法大家很快就理解，说明它简单，应说“很简单”，不说“远不止简单”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13829, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学习外语很远不止背单词，还要练口语。", "corrected_sentence": "学习外语远不止背单词，还要练口语。", "error_description": "错误形式：“很远不止”。正确形式：“远不止”。“远不止”本身是副词，前面不能再加“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13829, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学会一门乐器是远不止练习指法，还要懂乐理。", "corrected_sentence": "学会一门乐器远不止练习指法，还要懂乐理。", "error_description": "错误形式：“是远不止练习指法”。正确形式：“远不止练习指法”。“远不止”是副词，前面不能加“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
