INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13830, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13830, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物体最外侧或表面的部分。", "primary_collocate": null, "pronunciation": "biǎo céng", "ipa": "pjɑʊ˨˩˦ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这块蛋糕的表层烤得很脆，里面却还是软的。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地面的表层很干，下面的土还是湿的。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海水表层的温度比深处高。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把桌子表层的灰尘擦干净。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块木板的表层涂了一层油漆。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨水只湿了土壤的表层。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰的表层很滑，走路要小心。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "苹果的表层有一层薄薄的蜡。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皮肤的表层每天都会掉一些细胞。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个湖的表层结了冰，下面还有水。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "表層", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体最外面、靠近表面的那一部分，与里层、深处相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d3adfa-528b-4034-a494-9783488f8294') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表层", "is_correct": true, "explanation": "正确：“表层”指物体外侧的部分，外面烤得脆、里面仍软，与句意相合。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”不能被“烤得很脆”来形容。"}, {"text": "利润", "is_correct": false, "explanation": "语义：“利润”是经济概念，不是食物的部位，不能作“烤得很脆”的主语。"}, {"text": "面子", "is_correct": false, "explanation": "语义：“面子”指人的体面，不能指食物的部位。"}], "explanations": {"表层": "正确：“表层”指物体外侧的部分，外面烤得脆、里面仍软，与句意相合。", "温度": "搭配：“温度”不能被“烤得很脆”来形容。", "利润": "语义：“利润”是经济概念，不是食物的部位，不能作“烤得很脆”的主语。", "面子": "语义：“面子”指人的体面，不能指食物的部位。"}, "sentence_index": 0, "correct_answer": "表层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的表层很普通，看不出什么特别的地方。", "explanation": "这里应该用〈外表〉。表层指物体最外侧的部分，说人的样子要用外表，不说表层。"}, {"text": "他做事只做表层功夫，不肯真下力气。", "explanation": "这里应该用〈表面〉。“表面功夫”是固定说法，指只做表面的样子，不说“表层功夫”。"}, {"text": "这座城市的表层很热闹，晚上特别多人。", "explanation": "这里应该用〈外围〉。表层指紧贴物体外侧的一层，说城市的边缘地带要用外围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表层", "is_correct": true, "explanation": "正确：“表层”指冰的外侧，与“很滑”搭配。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“很滑”描述的是表面的质感，不能用来形容温度。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道没有滑与不滑之分，与句子所描述的触感不符。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：“很滑”不能形容颜色，颜色不是可以感觉滑的部分。"}], "explanations": {"表层": "正确：“表层”指冰的外侧，与“很滑”搭配。", "温度": "搭配：“很滑”描述的是表面的质感，不能用来形容温度。", "味道": "语义：味道没有滑与不滑之分，与句子所描述的触感不符。", "颜色": "体貌：“很滑”不能形容颜色，颜色不是可以感觉滑的部分。"}, "sentence_index": 6, "correct_answer": "表层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段声音的表层很大，听起来很吵。", "explanation": "这里应该用〈大〉。表层指物体外侧的一层，声音没有外层，说声音响要用“很大”。"}, {"text": "这家公司的表层很有名气，业内人都知道。", "explanation": "这里应该用〈名气〉。“名气”说人或机构的名声，表层只指物体的外侧。"}, {"text": "这首歌的表层很好听，大家都爱唱。", "explanation": "这里应该用〈旋律〉。表层指物体的外侧，不能用来形容乐曲的好听与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把冰的表层敲掉着。", "corrected_sentence": "我把冰的表层敲掉了。", "error_description": "错误：动作已经完成要用“了”，“着”表示持续状态，不能接在“敲掉”后面。正确：“把冰的表层敲掉了”，用“了”表示动作完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块饼干的表层烤得脆很。", "corrected_sentence": "这块饼干的表层烤得很脆。", "error_description": "错误：补语“脆很”的语序错误。正确：“烤得很脆”，程度副词“很”应放在形容词“脆”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
