INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13833, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "占据，指用强力取得或拥有某个位置、空间或利益。", "primary_collocate": null, "pronunciation": "zhàn", "ipa": "ʈʂan˥˩", "syllable_count": 1, "sentences": [{"text": "这个会议室的座位大多已经被提前到场的人占了，后来的同学只能站在走廊里听讲。", "target_word": "占", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "那辆车占了两个停车位。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早早地占着一个好座位。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张大桌子占了房间很多空间。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人占着我的座位，我只好站着。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队占了山上的小村子。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在公园里占好了一块地方玩游戏。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行李放在过道上会占地方。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他来得早，占了教室最前面的位子。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店占着街角最好的位置。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "占了", "label": "体标"}, {"form": "占着", "label": "体标"}, {"form": "占过", "label": "体标"}, {"form": "占据", "label": "复合"}, {"form": "占领", "label": "复合"}, {"form": "占用", "label": "复合"}, {"form": "佔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "占据位置、空间或利益", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d3adfa-528b-4034-a494-9783488f8294') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13833, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "占", "is_correct": true, "explanation": "占（zhàn）：用强力取得或占据某个位置、空间或利益。"}, {"text": "沾", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，意思是沾上、沾染，与占据无关。"}, {"text": "展", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是展开。"}, {"text": "善", "is_correct": false, "explanation": "shàn 与 zhàn 声母不同（sh 与 zh），意思是善良、好。"}, {"text": "赞", "is_correct": false, "explanation": "zàn 与 zhàn 声母不同（z 与 zh），意思是赞美。"}, {"text": "账", "is_correct": false, "explanation": "zhàng 与 zhàn 韵母不同（ang 与 an），意思是账目。"}], "explanations": {"占": "占（zhàn）：用强力取得或占据某个位置、空间或利益。", "沾": "zhān（第一声）与 zhàn（第四声）声调不同，意思是沾上、沾染，与占据无关。", "展": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是展开。", "善": "shàn 与 zhàn 声母不同（sh 与 zh），意思是善良、好。", "赞": "zàn 与 zhàn 声母不同（z 与 zh），意思是赞美。", "账": "zhàng 与 zhàn 韵母不同（ang 与 an），意思是账目。"}, "sentence_index": null, "correct_answer": "占"}, "level_3": {"options": [{"text": "占", "is_correct": true, "explanation": "占：指提前到场的人先占据座位，与“被……占了”相配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能用于座位。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指歌唱，与座位无关。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮料，与座位无关。"}], "explanations": {"占": "占：指提前到场的人先占据座位，与“被……占了”相配。", "吃": "搭配：“吃”的对象是食物，不能用于座位。", "唱": "语义：“唱”指歌唱，与座位无关。", "喝": "语义：“喝”的对象是饮料，与座位无关。"}, "sentence_index": 0, "correct_answer": "占"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他占了很多才能。", "explanation": "这里应该用〈拥有〉。占指用强力取得某个位置、空间或利益，才能是抽象的个人特质，不能被占，应该用拥有。"}, {"text": "他终于占了自己的理想。", "explanation": "这里应该用〈实现〉。占指用强力取得或拥有位置、空间或利益，理想是抽象的目标，不能被占，应该用实现。"}, {"text": "这家人占着安静的生活。", "explanation": "这里应该用〈享受〉。占指取得具体的位置、空间或利益，安静的生活是抽象状态，不能被占，应该用享受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13833, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "占", "is_correct": true, "explanation": "占（zhàn）：用强力取得或占据某个位置、空间或利益。"}, {"text": "粘", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，意思是粘贴。"}, {"text": "扇", "is_correct": false, "explanation": "shàn 与 zhàn 声母不同（sh 与 zh），意思是扇子。"}, {"text": "暂", "is_correct": false, "explanation": "zàn 与 zhàn 声母不同（z 与 zh），意思是暂时。"}, {"text": "胀", "is_correct": false, "explanation": "zhàng 与 zhàn 韵母不同（ang 与 an），意思是膨胀。"}, {"text": "颤", "is_correct": false, "explanation": "chàn 与 zhàn 声母不同（ch 与 zh），意思是颤抖。"}], "explanations": {"占": "占（zhàn）：用强力取得或占据某个位置、空间或利益。", "粘": "zhān（第一声）与 zhàn（第四声）声调不同，意思是粘贴。", "扇": "shàn 与 zhàn 声母不同（sh 与 zh），意思是扇子。", "暂": "zàn 与 zhàn 声母不同（z 与 zh），意思是暂时。", "胀": "zhàng 与 zhàn 韵母不同（ang 与 an），意思是膨胀。", "颤": "chàn 与 zhàn 声母不同（ch 与 zh），意思是颤抖。"}, "sentence_index": null, "correct_answer": "占"}, "level_3": {"options": [{"text": "占", "is_correct": true, "explanation": "占：“占好了一块地方”指先占据场地。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”要接人或物，不能说“送好了一块地方”。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应为食物，不能带“地方”作宾语。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写文字，与在公园里占用场地无关。"}], "explanations": {"占": "占：“占好了一块地方”指先占据场地。", "送": "搭配：“送”要接人或物，不能说“送好了一块地方”。", "吃": "配价：“吃”的宾语应为食物，不能带“地方”作宾语。", "写": "语义：“写”指书写文字，与在公园里占用场地无关。"}, "sentence_index": 6, "correct_answer": "占"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她占了大家的信任。", "explanation": "这里应该用〈赢得〉。占用于取得位置、空间或利益，信任是人与人之间的情感，不能被占，应该用赢得。"}, {"text": "他占了很大的进步。", "explanation": "这里应该用〈取得〉。占强调用力占据某物，进步这类抽象结果不能被占，应该用取得。"}, {"text": "她占了一张奖状。", "explanation": "这里应该用〈获得〉。占指用强力取得或拥有位置、空间或利益，奖状要靠成绩获得，不能被占，应该用获得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13833, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他占了着座位不让别人坐。", "corrected_sentence": "他占着座位不让别人坐。", "error_description": "“了”与“着”不能同时用在“占”后，应去掉“了”，改为“他占着座位不让别人坐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13833, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书堆占了满整张桌子。", "corrected_sentence": "书堆占满了整张桌子。", "error_description": "“满”是“占”的结果补语，应紧跟在“占”后，“了”放在“满”的后面，应说“占满了整张桌子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
