INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13834, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指可可树的种子，经加工后可制成可可粉、巧克力等食品。", "primary_collocate": null, "pronunciation": "kě kě", "ipa": "kʰɤ˨˩˦ kʰɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "从苹果、杏仁到咖啡与可可，这些人类饮食结构中的重要组成部分，其产量与质量皆深刻受制于蜂类活动的稳定性。", "target_word": "可可", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "巧克力是用可可做的。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早上喝了一杯热可可。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "非洲的很多农民种可可。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "可可的味道有一点苦。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在牛奶里加了可可。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种蛋糕里有咖啡和可可。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热带地区的农民种着可可。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把可可做成了巧克力。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，我喜欢喝牛奶可可。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可可粉", "label": "复合"}, {"form": "可可豆", "label": "复合"}, {"form": "热可可", "label": "复合"}], "register": "中性", "sense_fingerprint": "可可树的种子，可制成可可粉和巧克力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d3adfa-528b-4034-a494-9783488f8294') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13834, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可可", "is_correct": true, "explanation": "可可：指可可树的种子，与苹果、杏仁、咖啡同属食物，可以并列。"}, {"text": "木材", "is_correct": false, "explanation": "语义：木材不属于饮食结构，不能与前面的食物并列。"}, {"text": "石油", "is_correct": false, "explanation": "搭配：“与”并列的应是同类食物，石油无法与苹果、咖啡并列。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥不是食物，与“饮食结构”的描述无关。"}], "explanations": {"可可": "可可：指可可树的种子，与苹果、杏仁、咖啡同属食物，可以并列。", "木材": "语义：木材不属于饮食结构，不能与前面的食物并列。", "石油": "搭配：“与”并列的应是同类食物，石油无法与苹果、咖啡并列。", "水泥": "语义：水泥不是食物，与“饮食结构”的描述无关。"}, "sentence_index": 0, "correct_answer": "可可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早上喝了一只可可。", "explanation": "这里应该用〈杯〉。可可作饮料时按杯计量，“只”用于动物或成对的物品，不能说“一只可可”。"}, {"text": "他买了一张可可，准备做饼干。", "explanation": "这里应该用〈包〉。可可粉按包计量，“张”用于纸张、桌子等平面的东西，不能用于可可。"}, {"text": "我每天早上喝一根可可。", "explanation": "这里应该用〈杯〉。可可饮料按杯计量，“根”用于细长的东西，不能用于饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可可", "is_correct": true, "explanation": "可可：蛋糕里常用的原料，可以与咖啡并列。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝不能用于做蛋糕，与咖啡并列不成立。"}, {"text": "钢筋", "is_correct": false, "explanation": "搭配：“咖啡和”并列的应为可食用之物，钢筋无法与之并列。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子不是食材，放进蛋糕不合常理。"}], "explanations": {"可可": "可可：蛋糕里常用的原料，可以与咖啡并列。", "螺丝": "语义：螺丝不能用于做蛋糕，与咖啡并列不成立。", "钢筋": "搭配：“咖啡和”并列的应为可食用之物，钢筋无法与之并列。", "沙子": "语义：沙子不是食材，放进蛋糕不合常理。"}, "sentence_index": 6, "correct_answer": "可可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一条可可。", "explanation": "这里应该用〈包〉。可可粉按包计量，“条”用于细长的东西，不能用于可可。"}, {"text": "我的同桌买了一本可可。", "explanation": "这里应该用〈包〉。可可粉按包计量，“本”用于书册，不能用于可可。"}, {"text": "妈妈每天给我倒一座可可。", "explanation": "这里应该用〈杯〉。可可饮料按杯计量，“座”用于山、房屋等大型的东西，不能用于饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈买了一只可可，准备做饼干。", "corrected_sentence": "妈妈买了一包可可，准备做饼干。", "error_description": "“可可”指粉末状的可可，量词应用“包”，不能用“只”，应改为“妈妈买了一包可可，准备做饼干”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬天的晚上，我喜欢喝热了可可。", "corrected_sentence": "冬天的晚上，我喜欢喝热可可。", "error_description": "错误：“了”位置错误。“热可可”是修饰“可可”的形容词加名词，中间不能加“了”，应说“喜欢喝热可可”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac577367-6340-4793-8b57-4566a6407074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
