INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13835, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13835, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "饮食结构指一个人或群体日常摄入的食物种类、数量及其比例关系。", "primary_collocate": null, "pronunciation": "yǐn shí jié gòu", "ipa": "in˨˩˦ ʂʐ̩˧˥ tɕjɛ˧˥ kou˥˩", "syllable_count": 4, "sentences": [{"text": "从苹果、杏仁到咖啡与可可，这些人类饮食结构中的重要组成部分，其产量与质量皆深刻受制于蜂类活动的稳定性。", "target_word": "饮食结构", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "医生建议他调整一下饮食结构。", "target_word": "饮食结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的饮食结构太单一，每天只吃面条。", "target_word": "饮食结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "改善饮食结构对身体健康很重要。", "target_word": "饮食结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "南方和北方的饮食结构有很大的不同。", "target_word": "饮食结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把家人的饮食结构改成了多吃蔬菜、少吃肉。", "target_word": "饮食结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着收入提高，农村居民的饮食结构发生了明显变化。", "target_word": "饮食结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "营养师先了解了孩子的饮食结构，再制定食谱。", "target_word": "饮食结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合理的饮食结构应该包括粮食、蔬菜、水果和肉类。", "target_word": "饮食结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的饮食结构要少油少盐，多吃清淡的食物。", "target_word": "饮食结构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飲食結構", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人或群体日常摄入食物的种类、数量和比例构成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '703145e0-38ab-495d-a56f-5eaa17780ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13835, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饮食结构", "is_correct": true, "explanation": "正确：「饮食结构」指人或群体吃的食物的种类、数量和比例，与句中列举的苹果、杏仁、咖啡等食物相符。"}, {"text": "人口结构", "is_correct": false, "explanation": "搭配：「产量与质量」说的是食物，不能与「人口结构」搭配；「人口结构」指人口的年龄、性别等构成。"}, {"text": "交通工具", "is_correct": false, "explanation": "语义：苹果、咖啡不是交通工具的组成部分，句意不通。"}, {"text": "农药", "is_correct": false, "explanation": "语义：农药不是人类饮食的组成部分，与句中列举的食物相矛盾。"}], "explanations": {"饮食结构": "正确：「饮食结构」指人或群体吃的食物的种类、数量和比例，与句中列举的苹果、杏仁、咖啡等食物相符。", "人口结构": "搭配：「产量与质量」说的是食物，不能与「人口结构」搭配；「人口结构」指人口的年龄、性别等构成。", "交通工具": "语义：苹果、咖啡不是交通工具的组成部分，句意不通。", "农药": "语义：农药不是人类饮食的组成部分，与句中列举的食物相矛盾。"}, "sentence_index": 0, "correct_answer": "饮食结构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要制定一只新的饮食结构。", "explanation": "这里应该用〈种〉或〈套〉。「只」用于单个动物或成对的物件，饮食结构是抽象的体系，不能用「只」来计量。"}, {"text": "这座大桥的饮食结构很坚固，车辆可以安全通过。", "explanation": "这里应该用〈桥梁〉。「饮食结构」指食物的种类与比例，不能用来形容大桥的坚固；说大桥坚固应指桥梁的承重结构。"}, {"text": "公司正在调整饮食结构。", "explanation": "这里应该用〈产品结构〉。饮食结构指人或群体平时吃的东西，公司不吃东西，应说「产品结构」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饮食结构", "is_correct": true, "explanation": "正确：「饮食结构」指人或群体吃的食物的结构，与「收入提高」后居民饮食的变化相符。"}, {"text": "交通规则", "is_correct": false, "explanation": "语义：交通规则由政府制定，与收入提高无关，不能说随着收入提高而「发生明显变化」。"}, {"text": "地壳", "is_correct": false, "explanation": "语义：地壳是地球的构造，不属于居民，句意荒谬。"}, {"text": "质量", "is_correct": false, "explanation": "搭配：「质量」不用于描述人群，不能说农村居民的「质量」发生变化。"}], "explanations": {"饮食结构": "正确：「饮食结构」指人或群体吃的食物的结构，与「收入提高」后居民饮食的变化相符。", "交通规则": "语义：交通规则由政府制定，与收入提高无关，不能说随着收入提高而「发生明显变化」。", "地壳": "语义：地壳是地球的构造，不属于居民，句意荒谬。", "质量": "搭配：「质量」不用于描述人群，不能说农村居民的「质量」发生变化。"}, "sentence_index": 6, "correct_answer": "饮食结构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种饮料的饮食结构很简单，只有糖和水。", "explanation": "这里应该用〈成分〉。饮料不吃东西，饮食结构指人或群体吃的食物的种类与比例，说饮料的构成应用「成分」。"}, {"text": "他的饮食结构很大，一顿能吃三碗。", "explanation": "这里应该用〈饭量〉。「饭量」说吃多少，饮食结构说吃哪些食物及其比例，不能用「很大」来形容。"}, {"text": "他的饮食结构很亮堂，房间里有很多窗户。", "explanation": "这里应该用〈房间〉。「亮堂」形容光线充足的空间，饮食结构是抽象体系，不能这样描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈希望我改善一只饮食结构，少吃油炸食品。", "corrected_sentence": "我妈妈希望我改善饮食结构，少吃油炸食品。", "error_description": "量词错误：「只」用于单个动物或成对的物件，「饮食结构」是抽象的体系，不能说「一只饮食结构」，应直接说「改善饮食结构」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶正在饮食结构。", "corrected_sentence": "奶奶正在调整饮食结构。", "error_description": "动词缺失：「饮食结构」是名词，不能直接跟在「正在」后作谓语，应补出动词「调整」，说「正在调整饮食结构」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
