INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13839, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "完整区域被分割成多个小部分的状况", "primary_collocate": null, "pronunciation": "suì piàn", "ipa": "suei˥˩ pʰiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "栖息地被切成碎片、农药滥用、气候变化以及外来物种入侵，正在协同加速蜜蜂种群的衰退，进而威胁整个陆地生态系统的功能完整性。", "target_word": "碎片", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "公路把森林分成了许多碎片，小动物很难过去。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土地被切成碎片，农民没法种大片的田。", "target_word": "碎片", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "城市里的绿地成了一块块碎片。", "target_word": "碎片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林碎片越多，动物找食物就越难。", "target_word": "碎片", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果森林变成碎片，鸟就会失去家。", "target_word": "碎片", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "研究人员正在测量这些绿地碎片的大小。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要用绿色通道把这些森林碎片连起来。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护区被道路切成了几块碎片。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草原一旦变成碎片，牛羊就没有足够的地方吃草。", "target_word": "碎片", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "碎片化", "label": "复合"}], "register": "中性", "sense_fingerprint": "完整的区域被分割成多个互相分开的小部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f2921a4-34be-472b-b0db-c2ea060409ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13839, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "碎片", "is_correct": true, "explanation": "正确。「碎片」指完整区域被分割后的零散部分，这里说栖息地被切成了碎片。"}, {"text": "电子", "is_correct": false, "explanation": "语义：「切成电子」读不通，电子指电子设备或元件，与句中的生态威胁语境不符。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：「切成玩具」读不通，玩具与生态栖息地无关，句意不成立。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：「切成音乐」读不通，音乐不是可以切割成块的实体，与生态威胁的语境无关。"}], "explanations": {"碎片": "正确。「碎片」指完整区域被分割后的零散部分，这里说栖息地被切成了碎片。", "电子": "语义：「切成电子」读不通，电子指电子设备或元件，与句中的生态威胁语境不符。", "玩具": "语义：「切成玩具」读不通，玩具与生态栖息地无关，句意不成立。", "音乐": "语义：「切成音乐」读不通，音乐不是可以切割成块的实体，与生态威胁的语境无关。"}, "sentence_index": 0, "correct_answer": "碎片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片森林被碎片成了两块。", "explanation": "词性误用：碎片是名词，不能作动词用；这里应该用〈分割〉。"}, {"text": "这片森林至今仍是完整的碎片，动物可以自由往来。", "explanation": "语义矛盾：碎片指被分割后的零散部分，与「完整」相矛盾；这里应该用〈整体〉。"}, {"text": "这片森林被分成了一只碎片。", "explanation": "量词误用：「只」用于动物或成对的东西，这里应该用〈块〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13839, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "碎片", "is_correct": true, "explanation": "正确。「绿地碎片」指被分割开的小块绿地，是可以测量大小的对象。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有大小可言，「测量颜色的大小」读不通。"}, {"text": "对话", "is_correct": false, "explanation": "搭配：「大小」不用来衡量对话，「对话的大小」不搭配。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格无法测量大小，这里说的是绿地的物理范围，句子不成立。"}], "explanations": {"碎片": "正确。「绿地碎片」指被分割开的小块绿地，是可以测量大小的对象。", "颜色": "语义：颜色没有大小可言，「测量颜色的大小」读不通。", "对话": "搭配：「大小」不用来衡量对话，「对话的大小」不搭配。", "性格": "语义：性格无法测量大小，这里说的是绿地的物理范围，句子不成立。"}, "sentence_index": 6, "correct_answer": "碎片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片草原被河流切得很碎片。", "explanation": "词性误用：碎片是名词，不能作形容词用；形容零散程度应说〈零碎〉。"}, {"text": "这条河把草原分成了一座碎片。", "explanation": "量词误用：「座」用于山、楼等大型固定物，碎片应说〈块〉。"}, {"text": "这些农田已经连成一大片碎片，适合大型机械作业。", "explanation": "语义矛盾：碎片指被割开的零散部分，与已经连成一大片的农田相矛盾；这里应该用〈连片〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13839, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片湿地被公路切成了不少碎片化。", "corrected_sentence": "这片湿地被公路切成了不少碎片。", "error_description": "词形错误：「碎片化」是动词，指分散成碎片的过程，不能直接接在「不少」之后作名词，应说「碎片」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13839, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片林地被公路切碎片了。", "corrected_sentence": "这片林地被公路切成碎片了。", "error_description": "补语缺失：「切」后面要加结果补语「成」，应说「切成碎片」，不能说「切碎片」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
