INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13840, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指没有节制地、过分地使用。", "primary_collocate": null, "pronunciation": "làn yòng", "ipa": "lan˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "栖息地碎片化、农药滥用、气候变化以及外来物种入侵，正在协同加速蜜蜂种群的衰退，进而威胁整个陆地生态系统的功能完整性。", "target_word": "滥用", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "医生提醒大家，不能滥用抗生素。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官员不能滥用手中的权力。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "滥用药物会伤害身体。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为滥用职权，丢了工作。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，网络上不要滥用别人的照片。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民滥用农药，河水受到了污染。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司滥用客户的信息是违法的。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察不可以滥用武器。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去很多人滥用抗生素，现在细菌更难杀死了。", "target_word": "滥用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "滥用了", "label": "完成体"}, {"form": "滥用过", "label": "经历体"}, {"form": "滥用职权", "label": "复合"}], "register": "中性", "sense_fingerprint": "没有节制、过分地使用药物、权力、农药等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '703145e0-38ab-495d-a56f-5eaa17780ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农药滥用", "is_correct": true, "explanation": "正确：“农药滥用”指过度使用农药，是句中所列的威胁之一。"}, {"text": "农药研发", "is_correct": false, "explanation": "语义：研发农药本身不会加速蜜蜂衰退，与“威胁整个生态系统”的语境相冲突。"}, {"text": "农药稀释", "is_correct": false, "explanation": "搭配：“稀释”是动词，“农药稀释”不构成可列举的名词性威胁项。"}, {"text": "农药回收", "is_correct": false, "explanation": "语义：回收农药能减少污染，与句中“加速衰退”的威胁语境相反。"}], "explanations": {"农药滥用": "正确：“农药滥用”指过度使用农药，是句中所列的威胁之一。", "农药研发": "语义：研发农药本身不会加速蜜蜂衰退，与“威胁整个生态系统”的语境相冲突。", "农药稀释": "搭配：“稀释”是动词，“农药稀释”不构成可列举的名词性威胁项。", "农药回收": "语义：回收农药能减少污染，与句中“加速衰退”的威胁语境相反。"}, "sentence_index": 0, "correct_answer": "农药滥用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要充分滥用太阳能。", "explanation": "这里应该用〈利用〉。“滥用”指没有节制地过度使用，含贬义，不能与“充分”搭配，应说“充分利用太阳能”。"}, {"text": "医生建议患者合理滥用抗生素。", "explanation": "这里应该用〈使用〉。“滥用”本身含贬义，不能与“合理”搭配，应说“合理使用抗生素”。"}, {"text": "我们要滥用每一天。", "explanation": "这里应该用〈珍惜〉。“滥用”与“珍惜”意思相反，应说“珍惜每一天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滥用", "is_correct": true, "explanation": "正确：“农民滥用农药”指过度使用农药，与“河水受到了污染”的因果相符。"}, {"text": "节约", "is_correct": false, "explanation": "语义：节约农药不会污染河水，与“河水受到了污染”的结果不符。"}, {"text": "回收", "is_correct": false, "explanation": "语义：回收农药能减少污染，与“河水受到了污染”的结果相矛盾。"}, {"text": "饮用", "is_correct": false, "explanation": "搭配：“饮用”的对象是可以喝的液体，不说“饮用农药”。"}], "explanations": {"滥用": "正确：“农民滥用农药”指过度使用农药，与“河水受到了污染”的因果相符。", "节约": "语义：节约农药不会污染河水，与“河水受到了污染”的结果不符。", "回收": "语义：回收农药能减少污染，与“河水受到了污染”的结果相矛盾。", "饮用": "搭配：“饮用”的对象是可以喝的液体，不说“饮用农药”。"}, "sentence_index": 6, "correct_answer": "滥用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府加强了对森林的滥用。", "explanation": "这里应该用〈保护〉。“滥用”含贬义，与“加强”的管理意图矛盾，应说“加强对森林的保护”。"}, {"text": "护士严格滥用病人的服药量。", "explanation": "这里应该用〈控制〉。“滥用”指过度使用，与“严格”的要求冲突，应说“严格控制”。"}, {"text": "大家都要滥用每一度电。", "explanation": "这里应该用〈节约〉。“滥用”指过度使用，与要节约的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们不能滥用了药物。", "corrected_sentence": "我们不能滥用药物。", "error_description": "体标错误：“不能”后不能加完成体“了”，“滥用了”与否定的情态意义冲突。应为“不能滥用药物”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不滥用过职权。", "corrected_sentence": "他没滥用过职权。", "error_description": "否定词错误：表示“从未有过”的经历要用“没”，“不”用于习惯或意愿，“不……过”不成立。应为“没滥用过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
