INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13841, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指外部力量（如敌军、病毒等）未经允许进入某地区或系统，造成破坏或威胁。", "primary_collocate": null, "pronunciation": "rù qīn", "ipa": "ʐu˥˩ tɕʰin˥", "syllable_count": 2, "sentences": [{"text": "外来物种入侵了这个湖，鱼越来越少。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病毒入侵身体后，人会发烧。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑客入侵了公司的电脑系统。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌军入侵边境，人们只好离开家。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种草入侵农田，让农民很头疼。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人入侵了我的邮箱，我马上改了密码。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昆虫入侵森林，大片的树都死了。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，很多国家曾经入侵过邻国。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "防火墙能挡住入侵系统的程序。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红火蚁入侵了南方的城市。", "target_word": "入侵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "入侵了", "label": "完成体"}, {"form": "入侵过", "label": "经历体"}, {"form": "入侵者", "label": "复合"}], "register": "中性", "sense_fingerprint": "外来力量（物种、病毒、黑客、敌军）未经允许进入并造成破坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '703145e0-38ab-495d-a56f-5eaa17780ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13841, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清理", "is_correct": false, "explanation": "语义：清理是人为把脏东西除去，外来物种不会清理湖，句中的后果是鱼变少。"}, {"text": "入侵", "is_correct": true, "explanation": "外来物种未经允许进入湖泊并造成破坏，与“鱼越来越少”的后果相符。"}, {"text": "繁殖", "is_correct": false, "explanation": "语义：繁殖指生物产生后代，不能用来说繁殖一个湖；句中的后果是鱼变少。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的对象是动物，不能说喂养一个湖。"}], "explanations": {"清理": "语义：清理是人为把脏东西除去，外来物种不会清理湖，句中的后果是鱼变少。", "入侵": "外来物种未经允许进入湖泊并造成破坏，与“鱼越来越少”的后果相符。", "繁殖": "语义：繁殖指生物产生后代，不能用来说繁殖一个湖；句中的后果是鱼变少。", "喂养": "搭配：“喂养”的对象是动物，不能说喂养一个湖。"}, "sentence_index": 0, "correct_answer": "入侵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生入侵了教室，然后坐下来上课。", "explanation": "这里应该用〈进入〉。入侵指外力未经允许闯入并造成破坏，学生正常走进教室不能用入侵。"}, {"text": "他终于入侵了这个难题，松了一口气。", "explanation": "这里应该用〈攻克〉。入侵只用于外力闯入地区或系统，难题要用攻克。"}, {"text": "我们入侵了那家酒店，住了一晚。", "explanation": "这里应该用〈入住〉。入侵含有敌对和破坏的意思，住进酒店要用入住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13841, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生长", "is_correct": false, "explanation": "配价：“生长”是不及物动词，不能直接带“森林”作宾语。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：修剪是有意整理植物的行为，昆虫不会修剪森林，且句中大片的树已经死了。"}, {"text": "入侵", "is_correct": true, "explanation": "昆虫从外部进入森林并造成树木死亡，符合句意。"}, {"text": "驯养", "is_correct": false, "explanation": "搭配：“驯养”的对象是动物，不能说驯养森林。"}], "explanations": {"生长": "配价：“生长”是不及物动词，不能直接带“森林”作宾语。", "修剪": "语义：修剪是有意整理植物的行为，昆虫不会修剪森林，且句中大片的树已经死了。", "入侵": "昆虫从外部进入森林并造成树木死亡，符合句意。", "驯养": "搭配：“驯养”的对象是动物，不能说驯养森林。"}, "sentence_index": 6, "correct_answer": "入侵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们入侵了长城，拍了很多照片。", "explanation": "这里应该用〈游览〉。入侵指外力未经允许闯入并造成破坏，游客观光不能用入侵。"}, {"text": "他入侵了公司的钱，然后存进了银行。", "explanation": "这里应该用〈侵占〉。入侵指外力闯入地区或系统，财物被非法据为己有要用侵占。"}, {"text": "他入侵了前排的座位，然后坐了下来。", "explanation": "这里应该用〈占据〉。入侵含有破坏、威胁的意思，抢占座位只说占据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13841, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一群蚂蚁在入侵了我家的厨房。", "corrected_sentence": "一群蚂蚁入侵了我家的厨房。", "error_description": "错误形式：“在入侵了”；正确形式：“入侵了”。“在”表示动作正在进行，与表示完成的“了”不能同时用于同一动作，句中是已经完成的入侵，应去掉“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13841, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蝗虫入侵的了这个岛，庄稼都没了。", "corrected_sentence": "蝗虫入侵了这个岛，庄稼都没了。", "error_description": "错误形式：“入侵的了”；正确形式：“入侵了”。表示动作完成要在动词后用“了”，“的”不能放在动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
