INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13842, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13842, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指一定空间范围内同种生物的个体集合。", "primary_collocate": null, "pronunciation": "zhǒng qún", "ipa": "ʈʂʊŋ˨˩˦ tɕʰyn˧˥", "syllable_count": 2, "sentences": [{"text": "栖息地碎片化、农药滥用、气候变化以及外来物种入侵，正在协同加速蜜蜂种群的衰退，进而威胁整个陆地生态系统的功能完整性。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "生态学家近年来通过高分辨率遥感数据与基因追踪技术，对蜜蜂的觅食路径、种群遗传结构及其与植物网络的互动关系展开了系统性研究。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "蜜蜂在这一网络中扮演着“生态枢纽”的角色——它们穿梭于不同植物之间，促进基因流动，增强植物种群的适应潜力，从而提升整个生态系统的抗逆能力。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这片湖里的鲫鱼种群数量越来越少。", "target_word": "种群", "complexity_tier": "T3", "furigana": "zhǒng qún", "sentence_source": "generated"}, {"text": "保护区里，老虎的种群慢慢变大了。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员每年都要数一数这种鸟的种群数量。", "target_word": "种群", "complexity_tier": "T3", "furigana": "zhǒng qún", "sentence_source": "generated"}, {"text": "食物不够时，动物种群会变小。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个种群里的个体越多，竞争就越激烈。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种蝴蝶的种群只生活在山谷里。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护大熊猫，科学家想让它们的种群变大。", "target_word": "种群", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种群数量", "label": "复合"}, {"form": "种群密度", "label": "复合"}], "register": "书面", "sense_fingerprint": "生态学术语：一定区域内同种生物个体的总和，可数数量、密度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '703145e0-38ab-495d-a56f-5eaa17780ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13842, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花朵", "is_correct": false, "explanation": "语义：句中说的是蜜蜂这一生物群体，花朵不是蜜蜂的群体，句意不通。"}, {"text": "种群", "is_correct": true, "explanation": "同种生物个体的总和，蜜蜂种群的衰退符合句意。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言可以衰退，但“蜜蜂语言”指不了蜜蜂群体，句中谈的是生态问题。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“衰退”多用于种群、人口、经济，价格下降要说下跌，不说衰退。"}], "explanations": {"花朵": "语义：句中说的是蜜蜂这一生物群体，花朵不是蜜蜂的群体，句意不通。", "种群": "同种生物个体的总和，蜜蜂种群的衰退符合句意。", "语言": "语义：语言可以衰退，但“蜜蜂语言”指不了蜜蜂群体，句中谈的是生态问题。", "价格": "搭配：“衰退”多用于种群、人口、经济，价格下降要说下跌，不说衰退。"}, "sentence_index": 0, "correct_answer": "种群"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这群工人组成了一个种群，一起工作。", "explanation": "这里应该用〈群体〉。种群指同种生物的集合，人的集合要说群体。"}, {"text": "一只老鼠就是一个种群，它的寿命很短。", "explanation": "这里应该用〈个体〉。种群是多个同种个体的集合，单独一只老鼠是个体。"}, {"text": "这条街上的种群很拥挤，我们走不动了。", "explanation": "这里应该用〈人群〉。种群指同种生物的集合，街上拥挤的行人要说人群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小说", "is_correct": false, "explanation": "语义：小说不会因为食物不够而变小，句中指的是动物群体的数量。"}, {"text": "种群", "is_correct": true, "explanation": "同种生物个体的总和，食物不够时动物种群变小，符合句意。"}, {"text": "工资", "is_correct": false, "explanation": "语义：动物没有工资，“动物工资”不成立；且工资不会因食物不够而变化，句中谈的是动物种群。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不会因食物不够而变小，这与句中的生态因果不符。"}], "explanations": {"小说": "语义：小说不会因为食物不够而变小，句中指的是动物群体的数量。", "种群": "同种生物个体的总和，食物不够时动物种群变小，符合句意。", "工资": "语义：动物没有工资，“动物工资”不成立；且工资不会因食物不够而变化，句中谈的是动物种群。", "歌曲": "语义：歌曲不会因食物不够而变小，这与句中的生态因果不符。"}, "sentence_index": 6, "correct_answer": "种群"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "车站里挤满了种群，大家都在排队。", "explanation": "这里应该用〈人群〉。种群指同种生物的集合，挤在车站的人要说人群。"}, {"text": "这个种群的人每周一起开会，选出了主席。", "explanation": "这里应该用〈社团〉。种群是生物学术语，指同种生物的集合，人的社团不能说种群。"}, {"text": "我们种群的人常常一起过节，关系很好。", "explanation": "这里应该用〈家族〉。种群是生物学术语，人的家族不能说种群。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片森林里的鸟种群们数量在增加。", "corrected_sentence": "这片森林里的鸟种群数量在增加。", "error_description": "错误形式：“种群们”；正确形式：“种群”。“种群”是同种生物的集合名词，表示整体，不能再加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个湖里有很多条鲫鱼种群。", "corrected_sentence": "这个湖里有很多个鲫鱼种群。", "error_description": "错误形式：“很多条鲫鱼种群”；正确形式：“很多个鲫鱼种群”。种群是生物学上的群体，应使用通用量词“个”；“条”用于鱼、蛇等细长的事物，不能用来数种群。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d4e8244-7603-4c91-9fa2-25d131b719f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13843, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13843, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "繁荣", "is_correct": true, "explanation": "正确。“经济衰退”的反义是“经济繁荣”。"}, {"text": "安静", "is_correct": false, "explanation": "安静形容声音或环境平和，与“衰退”没有反义关系。"}, {"text": "紧张", "is_correct": false, "explanation": "紧张形容情绪或局势，与“衰退”不构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚形容是否明白或明显，与“衰退”的意义无关。"}], "correct_answer": "繁荣", "explanations": {"繁荣": "正确。“经济衰退”的反义是“经济繁荣”。", "安静": "安静形容声音或环境平和，与“衰退”没有反义关系。", "紧张": "紧张形容情绪或局势，与“衰退”不构成反义。", "清楚": "清楚形容是否明白或明显，与“衰退”的意义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13843, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指事物向较差、较低的水平发展，比如经济、健康或能力等逐渐下降。", "primary_collocate": null, "pronunciation": "shuāi tuì", "ipa": "ʂuai̯˥ tʰuei̯˥˩", "syllable_count": 2, "sentences": [{"text": "栖息地碎片化、农药滥用、气候变化以及外来物种入侵，正在协同加速蜜蜂种群的衰退，进而威胁整个陆地生态系统的功能完整性。", "target_word": "衰退", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "随着年龄增长，老人的记忆力逐渐衰退。", "target_word": "衰退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的经济连续三年衰退，失业人数不断上升。", "target_word": "衰退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期熬夜会使人的体力和视力慢慢衰退。", "target_word": "衰退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂搬走以后，这座小城的工业很快衰退了。", "target_word": "衰退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古罗马帝国为什么会衰退？", "target_word": "衰退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，他的肾功能已经开始衰退。", "target_word": "衰退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气候变暖使这片湖里的鱼类数量逐年衰退。", "target_word": "衰退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的业绩持续衰退，老板决定调整方向。", "target_word": "衰退", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济衰退时，很多人不敢随便花钱。", "target_word": "衰退", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "衰退了", "label": "体标"}, {"form": "衰退过", "label": "体标"}, {"form": "衰退期", "label": "复合"}], "register": "书面", "sense_fingerprint": "衰退|动词|经济、健康、能力等向较差水平逐渐发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ca8de9-da7d-4909-9408-983c1c2cb8f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13843, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "衰退", "is_correct": true, "explanation": "正确答案，shuāi tuì。"}, {"text": "摔碎", "is_correct": false, "explanation": "shuāi suì（碎）与 shuāi tuì 只有声母不同（s 与 t），意思是东西摔成碎片。"}, {"text": "摔腿", "is_correct": false, "explanation": "shuāi tuǐ（腿，第三声）与 shuāi tuì（第四声）只有第二个音节的声调不同，意思是摔伤了腿。"}, {"text": "甩腿", "is_correct": false, "explanation": "shuǎi tuǐ 与 shuāi tuì 两个音节的声调都不同，意思是挥动腿。"}], "explanations": {"衰退": "正确答案，shuāi tuì。", "摔碎": "shuāi suì（碎）与 shuāi tuì 只有声母不同（s 与 t），意思是东西摔成碎片。", "摔腿": "shuāi tuǐ（腿，第三声）与 shuāi tuì（第四声）只有第二个音节的声调不同，意思是摔伤了腿。", "甩腿": "shuǎi tuǐ 与 shuāi tuì 两个音节的声调都不同，意思是挥动腿。"}, "sentence_index": null, "correct_answer": "衰退"}, "level_3": {"options": [{"text": "衰退", "is_correct": true, "explanation": "正确。种群数量逐渐下降，才会威胁整个生态系统的完整性。"}, {"text": "恢复", "is_correct": false, "explanation": "语义：“恢复”表示回升，与后文“威胁整个陆地生态系统”的语义相矛盾。"}, {"text": "维持", "is_correct": false, "explanation": "搭配：“加速”表示促使变化，与“维持”意思相反，不能说“加速蜜蜂种群的维持”。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是减少伤害的行为，与“威胁”的语义相反，句子不通。"}], "explanations": {"衰退": "正确。种群数量逐渐下降，才会威胁整个生态系统的完整性。", "恢复": "语义：“恢复”表示回升，与后文“威胁整个陆地生态系统”的语义相矛盾。", "维持": "搭配：“加速”表示促使变化，与“维持”意思相反，不能说“加速蜜蜂种群的维持”。", "保护": "语义：“保护”是减少伤害的行为，与“威胁”的语义相反，句子不通。"}, "sentence_index": 0, "correct_answer": "衰退"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天坚持锻炼，身体的各项功能慢慢衰退了。", "explanation": "这里应该用〈增强〉。衰退指向较差的水平发展，坚持锻炼后身体功能应当增强。"}, {"text": "夜里，敌军悄悄衰退了。", "explanation": "这里应该用〈撤退〉。衰退指水平或状态逐渐变差，不指军队离开阵地。"}, {"text": "经过三个月的治疗，他的肾功能不断衰退，身体好了很多。", "explanation": "这里应该用〈好转〉。衰退指向较差的水平发展，身体变好要说好转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13843, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衰退", "is_correct": true, "explanation": "正确。肾功能逐渐变差，与“已经开始”相符。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”用于生物的增长发育，成年人的肾功能不能说生长。"}, {"text": "繁殖", "is_correct": false, "explanation": "语义：“繁殖”指生物增加个体数量，与器官功能无关。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”指植物的种子长出新芽，与人体器官的变化不符。"}], "explanations": {"衰退": "正确。肾功能逐渐变差，与“已经开始”相符。", "生长": "搭配：“生长”用于生物的增长发育，成年人的肾功能不能说生长。", "繁殖": "语义：“繁殖”指生物增加个体数量，与器官功能无关。", "发芽": "语义：“发芽”指植物的种子长出新芽，与人体器官的变化不符。"}, "sentence_index": 6, "correct_answer": "衰退"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵向后衰退了三步。", "explanation": "这里应该用〈后退〉。衰退指水平或状态变差，不表示位置的移动。"}, {"text": "他每次练习都比上次衰退，技术越来越好。", "explanation": "这里应该用〈进步〉。衰退指向较差的水平发展，技术越来越好要说进步。"}, {"text": "这棵树的枝叶衰退得很茂盛。", "explanation": "这里应该用〈生长〉。衰退指向较差的水平发展，不能用来形容枝叶茂盛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "长期不运动，身体的功能会逐渐被衰退。", "corrected_sentence": "长期不运动，身体的功能会逐渐衰退。", "error_description": "“衰退”是不及物动词，不能用“被”字句。正确形式是“功能会逐渐衰退”，去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生说，这种药吃久了，肝脏的功能衰退的很厉害。", "corrected_sentence": "医生说，这种药吃久了，肝脏的功能衰退得很厉害。", "error_description": "“衰退”作程度补语时要用“得”，不能用“的”。句中“的”应改为“得”，即“衰退得很厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
