INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13844, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生态学家是研究生物与环境之间相互关系的科学家，他们观察和解释自然界中各种生物如何共存、如何适应环境。", "primary_collocate": null, "pronunciation": "shēng tài xué jiā", "ipa": "ʂɤŋ˥ tʰai̯˥˩ ɕɥe˧˥ tɕja˥", "syllable_count": 4, "sentences": [{"text": "生态学家近年来通过高分辨率遥感数据与基因追踪技术，对蜜蜂的觅食路径、种群遗传结构及其与植物网络的互动关系展开了系统性研究。", "target_word": "生态学家", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这位生态学家在森林里研究了二十年。", "target_word": "生态学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态学家发现，河水变脏以后，鱼少了很多。", "target_word": "生态学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小爱动物，长大后成了一名生态学家。", "target_word": "生态学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态学家提醒大家，不要随便带外来植物进山。", "target_word": "生态学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几位生态学家一起去湿地调查水鸟。", "target_word": "生态学家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生态学家说，保护森林就是保护我们自己。", "target_word": "生态学家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位生态学家常常带着学生到野外观察昆虫。", "target_word": "生态学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态学家用相机记录了这片草原的变化。", "target_word": "生态学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为生态学家，他最关心湖里的水鸟数量。", "target_word": "生态学家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "生态学", "label": "复合"}, {"form": "生態學家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生态学家|名词|研究生物与环境关系的科学家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ca8de9-da7d-4909-9408-983c1c2cb8f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13844, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生态学家", "is_correct": true, "explanation": "正确。研究蜜蜂的觅食路径、种群结构和植物网络，是生态学家的工作。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作与研究蜜蜂种群、植物网络无关。"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员不做系统性的科学研究，与后文的遥感和基因技术不符。"}, {"text": "律师", "is_correct": false, "explanation": "搭配：“展开系统性研究”不与“律师”搭配，律师不做生物学研究。"}], "explanations": {"生态学家": "正确。研究蜜蜂的觅食路径、种群结构和植物网络，是生态学家的工作。", "厨师": "语义：厨师的工作与研究蜜蜂种群、植物网络无关。", "演员": "语义：演员不做系统性的科学研究，与后文的遥感和基因技术不符。", "律师": "搭配：“展开系统性研究”不与“律师”搭配，律师不做生物学研究。"}, "sentence_index": 0, "correct_answer": "生态学家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在山里挖了三十年矿，是一名生态学家。", "explanation": "这里应该用〈地质学家〉。生态学家研究生物与环境的关系，研究岩石和矿物的是地质学家。"}, {"text": "他每天都在医院里救人，是一名优秀的生态学家。", "explanation": "这里应该用〈医生〉。生态学家研究生物与环境的关系，治病救人的是医生。"}, {"text": "他花了二十年研究细胞，是一名著名的生态学家。", "explanation": "这里应该用〈生物学家〉。研究细胞属于生物学，生态学家研究的是生物与环境的关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生态学家", "is_correct": true, "explanation": "正确。这里指研究者，是能够发表观点的人。"}, {"text": "推土机", "is_correct": false, "explanation": "语义：推土机无法说话，与“说”的主语不符。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥是建筑材料，不能发表意见。"}, {"text": "煤炭", "is_correct": false, "explanation": "搭配：“煤炭说”不能成立，煤炭不是发出言论的主体。"}], "explanations": {"生态学家": "正确。这里指研究者，是能够发表观点的人。", "推土机": "语义：推土机无法说话，与“说”的主语不符。", "水泥": "语义：水泥是建筑材料，不能发表意见。", "煤炭": "搭配：“煤炭说”不能成立，煤炭不是发出言论的主体。"}, "sentence_index": 6, "correct_answer": "生态学家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作为生态学家，他每天都在分析台风路线。", "explanation": "这里应该用〈气象学家〉。台风路线属于气象学，生态学家研究生物与环境的关系。"}, {"text": "作为生态学家，他每晚都用望远镜观察星星。", "explanation": "这里应该用〈天文学家〉。观察星星属于天文学，生态学家不研究天体。"}, {"text": "这位生态学家其实是一名专业厨师，每天都在餐厅掌勺。", "explanation": "这里应该用〈厨师〉。“生态学家”指研究生物与环境关系的科学家，不指掌勺的职业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他大学毕业后很生态学家。", "corrected_sentence": "他大学毕业后当生态学家。", "error_description": "“生态学家”是名词，不能被“很”修饰。应该用“当”引出身份，改为“当生态学家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父亲年轻时是一名生态学家们，现在已经退休了。", "corrected_sentence": "父亲年轻时是一名生态学家，现在已经退休了。", "error_description": "“一名”与“生态学家”构成单数的量词结构，不能再加“们”。“们”只能用于没有数量词的复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
