INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13845, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指图像或显示设备能够呈现细节的能力很强，画面清晰。", "primary_collocate": null, "pronunciation": "gāo fēn biàn lǜ", "ipa": "kau̯˥ fən˥ pjɛn˥˩ ly˥˩", "syllable_count": 4, "sentences": [{"text": "生态学家近年来通过高分辨率遥感数据与基因追踪技术，对蜜蜂的觅食路径、种群遗传结构及其与植物网络的互动关系展开了系统性研究。", "target_word": "高分辨率", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这台新电视采用了高分辨率屏幕，画面非常清楚。", "target_word": "高分辨率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用高分辨率图像检查病人的肺部。", "target_word": "高分辨率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种相机的最大优点是高分辨率。", "target_word": "高分辨率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高分辨率的照片放大以后，细节依然清晰。", "target_word": "高分辨率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卫星拍下了这座城市的高分辨率影像。", "target_word": "高分辨率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师需要一台高分辨率的显示器来修图。", "target_word": "高分辨率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "显微镜的高分辨率让我们看清了细小的细胞。", "target_word": "高分辨率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏支持高分辨率，所以画面特别细腻。", "target_word": "高分辨率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想看清星星表面，就要用高分辨率的望远镜。", "target_word": "高分辨率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "超高分辨率", "label": "复合"}, {"form": "低分辨率", "label": "复合"}], "register": "书面", "sense_fingerprint": "高分辨率|名词|图像或设备呈现细节的能力强、画面清晰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1ca8de9-da7d-4909-9408-983c1c2cb8f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13845, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模糊", "is_correct": false, "explanation": "语义：“模糊”说数据不清楚，与系统性研究所需的精确数据相反。"}, {"text": "高分辨率", "is_correct": true, "explanation": "正确：修饰“遥感数据”，说明数据的细节分辨能力强。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”与“近年来”矛盾，近年来的研究不会用陈旧的数据。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“声音”不是遥感数据的属性，不能用来修饰遥感数据。"}], "explanations": {"模糊": "语义：“模糊”说数据不清楚，与系统性研究所需的精确数据相反。", "高分辨率": "正确：修饰“遥感数据”，说明数据的细节分辨能力强。", "陈旧": "语义：“陈旧”与“近年来”矛盾，近年来的研究不会用陈旧的数据。", "声音": "搭配：“声音”不是遥感数据的属性，不能用来修饰遥感数据。"}, "sentence_index": 0, "correct_answer": "高分辨率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗的高分辨率很强，读起来很感人。", "explanation": "这里应该用〈意境〉。高分辨率只指图像或显示设备呈现细节的能力，不能用来形容诗歌。"}, {"text": "这次演出的策划是高分辨率的。", "explanation": "这里应该用〈周密〉。周密用于计划、方案，高分辨率只指图像或显示设备的细节能力。"}, {"text": "这件木雕是高分辨率的。", "explanation": "这里应该用〈精细〉。精细用于工艺品的做工，高分辨率只用于图像或显示设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13845, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模糊", "is_correct": false, "explanation": "语义：“模糊”说画面不清楚，与设计师修图所需的清晰细节相反。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容声音，不能用来修饰显示器。"}, {"text": "高分辨率", "is_correct": true, "explanation": "正确：修饰“显示器”，说明显示器能呈现的细节很多，适合修图。"}, {"text": "微波", "is_correct": false, "explanation": "搭配：“微波”不能修饰显示器，二者不搭配。"}], "explanations": {"模糊": "语义：“模糊”说画面不清楚，与设计师修图所需的清晰细节相反。", "沙哑": "搭配：“沙哑”形容声音，不能用来修饰显示器。", "高分辨率": "正确：修饰“显示器”，说明显示器能呈现的细节很多，适合修图。", "微波": "搭配：“微波”不能修饰显示器，二者不搭配。"}, "sentence_index": 6, "correct_answer": "高分辨率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方法是高分辨率的。", "explanation": "这里应该用〈高效〉。高效用于方法、工作，高分辨率只指图像或显示设备的细节能力。"}, {"text": "他的品德是高分辨率的。", "explanation": "这里应该用〈高尚〉。高尚用于品德、情操，高分辨率只指图像或显示设备呈现细节的能力。"}, {"text": "这位老师的讲课是高分辨率的。", "explanation": "这里应该用〈生动〉。生动用于讲课、表达，高分辨率只指图像或显示设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13845, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台相机的一把高分辨率能拍出很细的纹理。", "corrected_sentence": "这台相机的高分辨率能拍出很细的纹理。", "error_description": "错误在量词：“高分辨率”是抽象的性质，不能用“一把”（“把”用于有柄的东西）。应去掉“一把”，改为“相机的高分辨率”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13845, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台显示器很高分辨率让画面很清楚。", "corrected_sentence": "这台显示器的高分辨率让画面很清楚。", "error_description": "错误在“很”：“高分辨率”是名词，前面不能直接加程度副词“很”，应用“的”连接，改为“……的高分辨率”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6b0ca8f-27f2-4f37-a30a-f806b29be336') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
