INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13849, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人与人之间相互影响、相互联系的关系。", "primary_collocate": null, "pronunciation": "hù dòng guān xì", "ipa": "xu˥˩ tʊŋ˥˩ kwan˥ ɕi˥˩", "syllable_count": 4, "sentences": [{"text": "心理学家近年来通过长期追踪与深度访谈，系统考察了青少年与同伴之间的互动关系，以及这种关系对其社会适应能力的影响。", "target_word": "互动关系", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "父母和孩子的互动关系影响孩子的成长。", "target_word": "互动关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事之间的互动关系很重要。", "target_word": "互动关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师要关注学生之间的互动关系。", "target_word": "互动关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络改变了人们的互动关系。", "target_word": "互动关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想改善员工和客户的互动关系。", "target_word": "互动关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的互动关系需要时间慢慢建立。", "target_word": "互动关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项研究分析了邻居之间的互动关系。", "target_word": "互动关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家人之间的互动关系越好，家里越温暖。", "target_word": "互动关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生和病人建立互动关系，治疗会更顺利。", "target_word": "互动关系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "互動關係", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人与人之间相互影响、相互联系的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2ecdf8b-6c73-43ce-950c-3ea6afae921a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13849, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "互动关系", "is_correct": true, "explanation": "正确。「互动关系」指双方相互影响的关系，与句中的研究对象相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「同伴之间的颜色」讲不通，颜色不能与人构成相互影响的关系。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「同伴之间的体重」讲不通，体重是身体的重量，与人际联系无关。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」指人的体型，不能用来描述青少年与同伴之间的联系。"}], "explanations": {"互动关系": "正确。「互动关系」指双方相互影响的关系，与句中的研究对象相符。", "颜色": "语义：「同伴之间的颜色」讲不通，颜色不能与人构成相互影响的关系。", "体重": "语义：「同伴之间的体重」讲不通，体重是身体的重量，与人际联系无关。", "身材": "体貌：「身材」指人的体型，不能用来描述青少年与同伴之间的联系。"}, "sentence_index": 0, "correct_answer": "互动关系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事和我没有互动关系。", "explanation": "这里应该用〈关联〉。互动关系指人与人之间相互影响，主语「这件事」不是人，表示牵涉的关系不能用互动关系。"}, {"text": "吸烟和肺癌之间是互动关系。", "explanation": "这里应该用〈因果关系〉。互动关系指人与人之间相互影响，吸烟导致肺癌是因果关系，不是人际互动。"}, {"text": "这个公式里的x和y之间是互动关系。", "explanation": "这里应该用〈函数关系〉。互动关系指人与人之间相互影响，变量之间的依存是函数关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13849, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "互动关系", "is_correct": true, "explanation": "正确。「互动关系」指人与人之间相互影响、相互联系，与「建立」搭配，符合句意。"}, {"text": "血型", "is_correct": false, "explanation": "语义：「血型」是先天的血液类别，不能「慢慢建立」，与句意不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」是自然现象，不能「建立」，句中需要的是表示人际联系的词。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：「外貌」指人的容貌，与「建立」不搭，也不指人与人之间的联系。"}], "explanations": {"互动关系": "正确。「互动关系」指人与人之间相互影响、相互联系，与「建立」搭配，符合句意。", "血型": "语义：「血型」是先天的血液类别，不能「慢慢建立」，与句意不符。", "天气": "语义：「天气」是自然现象，不能「建立」，句中需要的是表示人际联系的词。", "外貌": "体貌：「外貌」指人的容貌，与「建立」不搭，也不指人与人之间的联系。"}, "sentence_index": 6, "correct_answer": "互动关系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书和桌子之间是互动关系。", "explanation": "这里应该用〈位置关系〉。互动关系指人与人之间相互影响，书放在桌上只是空间位置关系。"}, {"text": "这份合同和那份报纸之间是互动关系。", "explanation": "这里应该用〈无关〉。互动关系指人与人之间相互影响，这两份文件之间并无相互影响。"}, {"text": "两人从未有过任何来往，他们之间是互动关系。", "explanation": "这里应该用〈素不相识〉。互动关系强调双方相互影响，两人从未往来，没有相互影响。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13849, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师和家长之间有一只互动关系。", "corrected_sentence": "老师和家长之间有一种互动关系。", "error_description": "错误：量词「只」。应改为「种」。「只」多用于动物或单个物件，互动关系是抽象名词，量词用「种」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13849, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生和病人之间有一颗互动关系。", "corrected_sentence": "医生和病人之间有一种互动关系。", "error_description": "错误：量词「颗」。应改为「种」。「颗」用于粒状的小东西，不能修饰互动关系这类抽象关系。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
