INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13851, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "使人产生某种心理感受或状态。", "primary_collocate": null, "pronunciation": "lìng rén", "ipa": "liŋ˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "这个好消息令人高兴。", "target_word": "令人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的故事令人感动。", "target_word": "令人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次比赛的结果令人失望。", "target_word": "令人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的风景令人难忘。", "target_word": "令人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的做法令人担心。", "target_word": "令人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个电影的结尾令人吃惊。", "target_word": "令人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的夜晚很安静，令人放松。", "target_word": "令人", "complexity_tier": "T3", "furigana": "hǎi biān de yè wǎn hěn ān jìng lìng rén fàng sōng", "sentence_source": "generated"}, {"text": "他十分努力，成绩令人佩服。", "target_word": "令人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家餐厅的服务令人满意，我们还会再来。", "target_word": "令人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他突然离开，这件事令人意外。", "target_word": "令人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "使人产生某种心理感受或状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2ecdf8b-6c73-43ce-950c-3ea6afae921a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13851, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "令人", "is_correct": true, "explanation": "正确。「令人」表示使人产生某种感受，与「高兴」搭配，符合句意。"}, {"text": "感到", "is_correct": false, "explanation": "语义：「感到高兴」的主语须是有感受的人，「这个好消息」不能「感到」高兴。"}, {"text": "觉得", "is_correct": false, "explanation": "配价：「觉得」后接的感受需要有感知的主语，用在「好消息」身上搭配不成立。"}, {"text": "变得", "is_correct": false, "explanation": "语义：「变得高兴」指主语的心情发生变化，「好消息」不会「变得」高兴。"}], "explanations": {"令人": "正确。「令人」表示使人产生某种感受，与「高兴」搭配，符合句意。", "感到": "语义：「感到高兴」的主语须是有感受的人，「这个好消息」不能「感到」高兴。", "觉得": "配价：「觉得」后接的感受需要有感知的主语，用在「好消息」身上搭配不成立。", "变得": "语义：「变得高兴」指主语的心情发生变化，「好消息」不会「变得」高兴。"}, "sentence_index": 0, "correct_answer": "令人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班长令人明天去开会。", "explanation": "这里应该用〈通知〉。令人表示使人产生感受或状态，不用来安排他人做具体事务，应说「通知」。"}, {"text": "下雨了，令人打伞。", "explanation": "这里应该用〈提醒〉。令人只用于心理感受或状态，不用来让人做打伞这类具体动作。"}, {"text": "这块石头令人摔倒。", "explanation": "这里应该改用〈使…摔倒〉这类说法。令人表示使人产生心理感受或状态，不用来描述物体引起的摔倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13851, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "令人", "is_correct": true, "explanation": "正确。「令人放松」表示使人产生放松的感受，与句中的夜晚环境相符。"}, {"text": "进行", "is_correct": false, "explanation": "搭配：「进行」后接的是有施事的行为，「夜晚」不能「进行放松」。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：「禁止放松」需要有人下令，句中的夜晚无法禁止放松，与语境不合。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：「拒绝放松」指不愿放松，「海边的夜晚很安静」的语境里不应出现拒绝放松。"}], "explanations": {"令人": "正确。「令人放松」表示使人产生放松的感受，与句中的夜晚环境相符。", "进行": "搭配：「进行」后接的是有施事的行为，「夜晚」不能「进行放松」。", "禁止": "语义：「禁止放松」需要有人下令，句中的夜晚无法禁止放松，与语境不合。", "拒绝": "语义：「拒绝放松」指不愿放松，「海边的夜晚很安静」的语境里不应出现拒绝放松。"}, "sentence_index": 6, "correct_answer": "令人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们令人很兴奋。", "explanation": "这里应该用〈感到〉。令人表示使别人产生某种感受，不用来说说话人自己的心情。"}, {"text": "这份报告令人写完。", "explanation": "这里应该用〈要求〉。令人表示使人产生感受或状态，不用来指派他人完成具体任务。"}, {"text": "这块玻璃令人划伤手。", "explanation": "这里应该用〈导致〉。令人只表示使人产生心理感受或状态，不用来描述物体造成的伤害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13851, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个消息令人了吃惊。", "corrected_sentence": "这个消息令人吃惊。", "error_description": "错误：「了」放错位置。「令人吃惊」是一个整体，「了」不能插在「人」与「吃惊」之间，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13851, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事令人着伤心。", "corrected_sentence": "这件事令人伤心。", "error_description": "错误：「着」放错位置。「令人伤心」中不能在「人」后加「着」，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
