INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13855, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "结实率指植物开花后，成功发育成果实的比例，通常用百分比表示。", "primary_collocate": null, "pronunciation": "jiē shí lǜ", "ipa": "tɕjɛ˥ ʂʐ̩˧˥ lɥy˥˩", "syllable_count": 3, "sentences": [{"text": "这些研究揭示了一个令人警觉的事实：当某一区域的授粉昆虫丰度下降时，不仅植物结实率显著降低，连锁效应还会波及依赖这些植物生存的鸟类、哺乳动物及其他无脊椎动物，从而引发生态系统服务功能的级联式崩溃。", "target_word": "结实率", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今年雨水多，苹果树的结实率很高。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花开的时候下大雨，结实率会变低。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民想提高水稻的结实率。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花的结实率只有百分之三十。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂少了，南瓜的结实率也下降了。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们记录每棵树的结实率。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，会影响桃树的结实率。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地今年的结实率比去年高。", "target_word": "结实率", "complexity_tier": "T3", "furigana": "jié shí lǜ", "sentence_source": "generated"}, {"text": "研究人员正在测量花生的结实率。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "結實率", "label": "繁体"}], "register": "书面", "sense_fingerprint": "植物开花后成功结成果实的比例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2ecdf8b-6c73-43ce-950c-3ea6afae921a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13855, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结实率", "is_correct": true, "explanation": "结实率指植物开花后结成果实的比例，与“显著降低”搭配，符合句意。"}, {"text": "音量", "is_correct": false, "explanation": "语义：植物没有音量，「植物音量显著降低」讲不通。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是上学的费用，与植物的结果情况无关，「植物学费显著降低」讲不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会“显著降低”，与句中植物结果的变化无关。"}], "explanations": {"结实率": "结实率指植物开花后结成果实的比例，与“显著降低”搭配，符合句意。", "音量": "语义：植物没有音量，「植物音量显著降低」讲不通。", "学费": "语义：学费是上学的费用，与植物的结果情况无关，「植物学费显著降低」讲不通。", "颜色": "语义：颜色不会“显著降低”，与句中植物结果的变化无关。"}, "sentence_index": 0, "correct_answer": "结实率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的结实率很高。", "explanation": "这里应该用〈出生率〉。结实率只指植物开花后结果的比例，不用于人口。"}, {"text": "这次考试的结实率很高。", "explanation": "这里应该用〈合格率〉。结实率只用于植物，不用于考试。"}, {"text": "这片果园的一只结实率很高。", "explanation": "量词用错。“只”用于动物等，结实率是比例，不能用“一只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13855, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结实率", "is_correct": true, "explanation": "结实率是要记录的数据，与“记录”搭配，符合句意。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：树没有脾气，无从记录。"}, {"text": "电费", "is_correct": false, "explanation": "语义：树不用电，没有「电费」可以记录，与句意不符。"}, {"text": "名气", "is_correct": false, "explanation": "搭配：“记录”说的是数据和情况，不说“名气”。"}], "explanations": {"结实率": "结实率是要记录的数据，与“记录”搭配，符合句意。", "脾气": "语义：树没有脾气，无从记录。", "电费": "语义：树不用电，没有「电费」可以记录，与句意不符。", "名气": "搭配：“记录”说的是数据和情况，不说“名气”。"}, "sentence_index": 6, "correct_answer": "结实率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支球队的结实率很高。", "explanation": "这里应该用〈胜率〉。结实率只指植物开花后结果的比例，不用于球队的比赛成绩。"}, {"text": "这场比赛的结实率很高。", "explanation": "这里应该用〈上座率〉。结实率只用于植物，不用于比赛的观众。"}, {"text": "这家店的结实率很高。", "explanation": "这里应该用〈利润率〉。结实率只指植物开花后结果的比例，不用于商店的经营。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这棵苹果树今年的结实率了比去年高。", "corrected_sentence": "这棵苹果树今年的结实率比去年高。", "error_description": "“了”用错：“结实率”是名词，不能直接带“了”放在“比”字结构前。应去掉“了”，写作“这棵苹果树今年的结实率比去年高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片梨园今年的一只结实率比去年低。", "corrected_sentence": "这片梨园今年的结实率比去年低。", "error_description": "量词用错：“结实率”是抽象名词，不能用“只”。应去掉“一只”，写作“这片梨园今年的结实率比去年低”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
