INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13856, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "影响或扩散到某个范围或对象。", "primary_collocate": null, "pronunciation": "bō jí", "ipa": "pwɔ˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这些研究揭示了一个令人警觉的事实：当某一区域的授粉昆虫丰度下降时，不仅植物结实率显著降低，连锁效应还会波及依赖这些植物生存的鸟类、哺乳动物及其他无脊椎动物，从而引发生态系统服务功能的级联式崩溃。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "大火波及了旁边的几栋房子。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场地震波及了整个城市。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物价上涨波及到很多家庭。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情很快波及了周围的国家。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次停电波及了三条街。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水也波及过这个小镇。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的问题波及到了每个员工。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂关门波及了附近的小商店。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大雪波及了北方好几个省。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "波及了", "label": "体标"}, {"form": "波及过", "label": "体标"}, {"form": "波及到", "label": "补语"}], "register": "书面语", "sense_fingerprint": "影响扩散到某个范围或对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2ecdf8b-6c73-43ce-950c-3ea6afae921a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13856, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "波及", "is_correct": true, "explanation": "正确：“波及”表示影响扩散到依赖植物的动物，与连锁效应的语境相合。"}, {"text": "捕食", "is_correct": false, "explanation": "语义：“捕食”指捕捉其他动物为食，连锁效应不能捕食鸟类。"}, {"text": "扭转", "is_correct": false, "explanation": "搭配：“扭转”的宾语是局面、趋势，不能说扭转鸟类。"}, {"text": "资助", "is_correct": false, "explanation": "语义：“资助”指给予经济帮助，与连锁效应造成的生态崩溃不合。"}], "explanations": {"波及": "正确：“波及”表示影响扩散到依赖植物的动物，与连锁效应的语境相合。", "捕食": "语义：“捕食”指捕捉其他动物为食，连锁效应不能捕食鸟类。", "扭转": "搭配：“扭转”的宾语是局面、趋势，不能说扭转鸟类。", "资助": "语义：“资助”指给予经济帮助，与连锁效应造成的生态崩溃不合。"}, "sentence_index": 0, "correct_answer": "波及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书波及了很多历史问题。", "explanation": "这里应该用〈涉及〉。波及指影响扩散到某个范围或对象，谈论书的内容范围要用涉及。"}, {"text": "这种药品波及全国各地。", "explanation": "这里应该用〈遍及〉。遍及指分布到各处，药品的销售范围要用遍及；波及强调影响扩散，不用于此。"}, {"text": "他很少波及商界。", "explanation": "这里应该用〈涉足〉。涉足指进入某个领域，波及指影响扩散到某个对象，二者不能互换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "波及", "is_correct": true, "explanation": "正确：“波及过”表示洪水曾经影响到这个小镇，与洪水的语境相合。"}, {"text": "救助", "is_correct": false, "explanation": "语义：“救助”指帮助遇险的人，洪水不会救助小镇。"}, {"text": "装扮", "is_correct": false, "explanation": "体貌：“装扮”指给人或物打扮外貌，与洪水对小镇的破坏不合。"}, {"text": "捐助", "is_correct": false, "explanation": "语义：“捐助”指无偿给予财物，洪水不能向小镇捐助。"}], "explanations": {"波及": "正确：“波及过”表示洪水曾经影响到这个小镇，与洪水的语境相合。", "救助": "语义：“救助”指帮助遇险的人，洪水不会救助小镇。", "装扮": "体貌：“装扮”指给人或物打扮外貌，与洪水对小镇的破坏不合。", "捐助": "语义：“捐助”指无偿给予财物，洪水不能向小镇捐助。"}, "sentence_index": 6, "correct_answer": "波及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他波及了这个问题的核心。", "explanation": "这里应该用〈触及〉。触及指接触到问题的要点，波及指影响扩散，不能用来表示触及核心。"}, {"text": "我们终于波及了山顶。", "explanation": "这里应该用〈到达〉。到达指人抵达某处，登上山顶要用到达；波及指影响扩散到某个范围或对象，不能表示人抵达地点。"}, {"text": "工人们波及了严重的损失。", "explanation": "这里应该用〈遭受〉。遭受指承受伤害或损失，波及表示影响扩散，不能表示承受损失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场火灾波及了过附近的村子。", "corrected_sentence": "这场火灾波及过附近的村子。", "error_description": "错误：“波及了过”。“了”和“过”不能同时用在同一动词后；表示曾经发生过的经历只用“过”，应改为“波及过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "全城的餐馆把这次停水波及了。", "corrected_sentence": "全城的餐馆被这次停水波及了。", "error_description": "错误：「把」误用于被动句。「波及」的受事“全城的餐馆”要用「被」引出施事“这次停水”，应改为「被」，写作「全城的餐馆被这次停水波及了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddecee19-ff59-43cc-9ed7-c4b1b0b93097') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13857, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有", "is_correct": true, "explanation": "有：与“无”相对，《现代汉语词典》中“无”的释义即为“没有，与‘有’相对”。"}, {"text": "吃", "is_correct": false, "explanation": "吃是进食的动作，与“无”没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "看是视觉动作，与“无”没有反义关系。"}, {"text": "说", "is_correct": false, "explanation": "说是言语动作，与“无”没有反义关系。"}], "correct_answer": "有", "explanations": {"有": "有：与“无”相对，《现代汉语词典》中“无”的释义即为“没有，与‘有’相对”。", "吃": "吃是进食的动作，与“无”没有反义关系。", "看": "看是视觉动作，与“无”没有反义关系。", "说": "说是言语动作，与“无”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13857, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有", "is_correct": true, "explanation": "有：与“无”相对，《现代汉语词典》中“无”的释义即为“没有，与‘有’相对”。"}, {"text": "跑", "is_correct": false, "explanation": "跑是移动的动作，与“无”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱是发声的动作，与“无”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写是书写的动作，与“无”没有反义关系。"}], "correct_answer": "有", "explanations": {"有": "有：与“无”相对，《现代汉语词典》中“无”的释义即为“没有，与‘有’相对”。", "跑": "跑是移动的动作，与“无”没有反义关系。", "唱": "唱是发声的动作，与“无”没有反义关系。", "写": "写是书写的动作，与“无”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13857, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "没有（与“有”相对）。", "primary_collocate": null, "pronunciation": "wú", "ipa": "u˧˥", "syllable_count": 1, "sentences": [{"text": "山里无电，晚上只能点蜡烛。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河无桥，大家只能坐船过去。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "此路无出口，请你走另一边。", "target_word": "无", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "屋里无灯，我们只好摸黑走路。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家里无钱供他上学，只好去打工。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里无学生，老师和同学都去开会了。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市无地铁，上班要坐公交车。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个村子无医院，病人要去镇上看病。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她身边无亲人，所以常常觉得孤单。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条街无路灯，晚上走路要小心。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "無", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "无：没有，与“有”相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 村子 (Zipf 3.93), 镇上 (Zipf 3.93), 看病 (Zipf 3.73)']::text[], '7728ca8c-cc31-47be-a40d-da0fcf2ae697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13857, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无", "is_correct": true, "explanation": "无 wú，意思是没有，与“有”相对。"}, {"text": "悟", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是领会、醒悟。"}, {"text": "呜", "is_correct": false, "explanation": "wū（第一声）与 wú（第二声）声调不同，多用于拟声，如呜呜。"}, {"text": "污", "is_correct": false, "explanation": "wū（第一声）与 wú（第二声）声调不同，意思是脏、污染。"}, {"text": "误", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是错误、耽误。"}], "explanations": {"无": "无 wú，意思是没有，与“有”相对。", "悟": "wù（第四声）与 wú（第二声）声调不同，意思是领会、醒悟。", "呜": "wū（第一声）与 wú（第二声）声调不同，多用于拟声，如呜呜。", "污": "wū（第一声）与 wú（第二声）声调不同，意思是脏、污染。", "误": "wù（第四声）与 wú（第二声）声调不同，意思是错误、耽误。"}, "sentence_index": null, "correct_answer": "无"}, "level_3": {"options": [{"text": "无", "is_correct": true, "explanation": "无：“无电”表示没有电，与“只能点蜡烛”相呼应，句意通顺。"}, {"text": "有", "is_correct": false, "explanation": "语义：“有电”与“只能点蜡烛”相矛盾，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“电”不能作“吃”的宾语，句意不通。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”表示燃烧，“烧电”不成词，句意说不通。"}], "explanations": {"无": "无：“无电”表示没有电，与“只能点蜡烛”相呼应，句意通顺。", "有": "语义：“有电”与“只能点蜡烛”相矛盾，句意不通。", "吃": "搭配：“电”不能作“吃”的宾语，句意不通。", "烧": "语义：“烧”表示燃烧，“烧电”不成词，句意说不通。"}, "sentence_index": 0, "correct_answer": "无"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天无来上课，老师很担心。", "explanation": "这里应该用〈没〉。“无”表示没有某物，不能用在动作动词前；叙述过去的动作应说“没来”。"}, {"text": "我们学校很无操场，同学们只好在教室里玩。", "explanation": "这里不能说“很无”。“无”不受程度副词“很”修饰，应说“没有操场”。"}, {"text": "这条路无宽，车很难开过去。", "explanation": "这里应该用〈不〉。“无”表示没有某物，不能修饰形容词；形容路不宽，应说“不宽”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13857, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无", "is_correct": true, "explanation": "无 wú，意思是没有，与“有”相对。"}, {"text": "五", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是数字五。"}, {"text": "雾", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是雾气。"}, {"text": "午", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是中午。"}, {"text": "舞", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是跳舞。"}, {"text": "物", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是东西、事物。"}], "explanations": {"无": "无 wú，意思是没有，与“有”相对。", "五": "wǔ（第三声）与 wú（第二声）声调不同，意思是数字五。", "雾": "wù（第四声）与 wú（第二声）声调不同，意思是雾气。", "午": "wǔ（第三声）与 wú（第二声）声调不同，意思是中午。", "舞": "wǔ（第三声）与 wú（第二声）声调不同，意思是跳舞。", "物": "wù（第四声）与 wú（第二声）声调不同，意思是东西、事物。"}, "sentence_index": null, "correct_answer": "无"}, "level_3": {"options": [{"text": "无", "is_correct": true, "explanation": "无：“无地铁”表示没有地铁，与“坐公交车”相呼应，句意通顺。"}, {"text": "乘", "is_correct": false, "explanation": "配价：“乘”要求人作主语，“这座城市”不能乘坐地铁。"}, {"text": "骑", "is_correct": false, "explanation": "语义：“骑”多指骑车、骑马，不能用于地铁，句意不通。"}, {"text": "搭", "is_correct": false, "explanation": "配价：“搭”要求乘客作主语，“城市”不能搭地铁。"}], "explanations": {"无": "无：“无地铁”表示没有地铁，与“坐公交车”相呼应，句意通顺。", "乘": "配价：“乘”要求人作主语，“这座城市”不能乘坐地铁。", "骑": "语义：“骑”多指骑车、骑马，不能用于地铁，句意不通。", "搭": "配价：“搭”要求乘客作主语，“城市”不能搭地铁。"}, "sentence_index": 6, "correct_answer": "无"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨晚无回家，我们都很担心。", "explanation": "这里应该用〈没〉。“无”不能修饰动作动词“回家”；叙述已发生的动作应说“没回家”。"}, {"text": "这个公园很无椅子，老人们只能站着休息。", "explanation": "这里不能说“很无”。“无”不受程度副词“很”修饰，应说“没有椅子”。"}, {"text": "这个房间无暖，冬天特别冷。", "explanation": "这里应该用〈不〉。“无”表示没有某物，不能修饰形容词；形容房间不暖，应说“不暖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小岛无了淡水，居民要靠雨水生活。", "corrected_sentence": "这个小岛无淡水，居民要靠雨水生活。", "error_description": "“无”后面不能加“了”。应说“无淡水”，表示没有淡水。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13857, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个山区无没有学校，孩子们要走很远的路。", "corrected_sentence": "这个山区无学校，孩子们要走很远的路。", "error_description": "“无”和“没有”意思重复，只用其一。应说“无学校”或“没有学校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
